function cleanString(value) {
  return String(value || '').trim()
}

function buildMetaCapiRequestUrl(datasetId, accessToken, metaConfig = {}) {
  const params = new URLSearchParams({ access_token: accessToken })
  if (metaConfig?.oauth_appsecret_proof) {
    params.set('appsecret_proof', metaConfig.oauth_appsecret_proof)
  }
  return `${API_URLS.META_GRAPH}/${encodeURIComponent(datasetId)}/events?${params.toString()}`
}

const LEGACY_UUID_ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
const RISTAK_SITE_BLOCK_ID_PATTERN = /^rstk_site_block_[A-Za-z0-9]{6,64}$/

function canUseRequestedSiteBlockId(value) {
  const id = cleanString(value)
  return LEGACY_UUID_ID_PATTERN.test(id) || RISTAK_SITE_BLOCK_ID_PATTERN.test(id)
}

function normalizeSiteMetaEventName(value, { allowNone = false, fallback = 'Lead' } = {}) {
  const eventName = cleanString(value)
  if (allowNone && eventName.toLowerCase() === SITE_META_NO_EVENT) return SITE_META_NO_EVENT
  return SITE_META_EVENTS.has(eventName) ? eventName : fallback
}

function normalizeSiteMetaTrigger(value) {
  const trigger = cleanString(value)
  return SITE_META_TRIGGERS.has(trigger) ? trigger : 'page_view'
}

function buildUniqueSitePageId(value = '', index = 0, usedIds = new Set()) {
  const fallback = index === 0 ? DEFAULT_FUNNEL_PAGE_ID : `page-${index + 1}`
  const base = cleanString(value) || fallback
  let candidate = base
  let suffix = 2
  while (usedIds.has(candidate)) {
    candidate = `${base}-${suffix}`
    suffix += 1
  }
  usedIds.add(candidate)
  return candidate
}

function getMetaParameterFieldsForEvent(eventName) {
  return SITE_META_PARAMETER_FIELDS[normalizeSiteMetaEventName(eventName, { allowNone: true, fallback: SITE_META_NO_EVENT })] || []
}

function firstMetaParameterValue(source = {}, key) {
  const aliases = SITE_META_PARAMETER_ALIASES[key] || [key]
  for (const alias of aliases) {
    const value = source?.[alias]
    if (value !== undefined && value !== null && cleanString(value)) return cleanString(value)
  }
  return ''
}

function normalizeSiteMetaCustomParameterKey(value = '') {
  const key = cleanString(value)
    .replace(/[^a-zA-Z0-9_]/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 64)

  if (!key) return ''
  return /^[a-zA-Z_]/.test(key) ? key : `param_${key}`
}

function normalizeSiteMetaEventParameters(value = {}) {
  const source = value && typeof value === 'object' ? value : parseJson(value, {})
  const normalized = {}

  Object.keys(SITE_META_PARAMETER_ALIASES).forEach(key => {
    const fieldValue = firstMetaParameterValue(source, key)
    if (fieldValue) normalized[key] = key === 'currency' ? fieldValue.toUpperCase().slice(0, 3) : fieldValue
  })

  const customSource = Array.isArray(source.custom)
    ? source.custom
    : Array.isArray(source.customParameters)
      ? source.customParameters
      : Array.isArray(source.custom_parameters)
        ? source.custom_parameters
        : []

  const custom = customSource
    .map((parameter = {}) => ({
      id: cleanString(parameter.id),
      key: cleanString(parameter.key || parameter.name),
      value: cleanString(parameter.value)
    }))
    .filter(parameter => parameter.key || parameter.value)
    .slice(0, 12)

  if (custom.length) normalized.custom = custom

  return normalized
}

function normalizeImportedHtmlConversionAlias(value = '') {
  return cleanString(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
}

function getImportedHtmlConversionDefaultEventName(value = '') {
  const conversionType = IMPORTED_HTML_CONVERSION_TYPE_BY_ALIAS.get(normalizeImportedHtmlConversionAlias(value)) || ''
  return IMPORTED_HTML_CONVERSION_EVENT_BY_TYPE[conversionType] || ''
}

function normalizeImportedHtmlConversionType(value = '', eventName = '') {
  const alias = normalizeImportedHtmlConversionAlias(value)
  const explicitType = IMPORTED_HTML_CONVERSION_TYPE_BY_ALIAS.get(alias)
  if (explicitType) return explicitType

  if (eventName === 'Schedule') return 'appointment_scheduled'
  if (eventName === 'Purchase') return 'purchase'
  if (eventName === 'CompleteRegistration') return 'complete_registration'
  if (eventName === 'Contact') return 'contact'
  if (eventName === 'ViewContent') return 'view_content'
  return 'form_submit'
}

function getImportedHtmlConversionSource(meta = {}) {
  const source = meta && typeof meta === 'object' ? meta : {}
  const candidate =
    source.importedConversion ||
    source.imported_conversion ||
    source.rstkConversion ||
    source.rstk_conversion ||
    source.conversion ||
    null

  return candidate && typeof candidate === 'object' && !Array.isArray(candidate)
    ? candidate
    : null
}

function firstImportedHtmlConversionValue(source = {}, aliases = []) {
  for (const alias of aliases) {
    const value = source?.[alias]
    if (value !== undefined && value !== null && cleanString(value)) return cleanString(value)
  }
  return ''
}

function buildImportedHtmlConversionParameterSource(source = {}) {
  const data = source.data && typeof source.data === 'object' && !Array.isArray(source.data) ? source.data : {}
  const customData = source.customData && typeof source.customData === 'object' && !Array.isArray(source.customData)
    ? source.customData
    : source.custom_data && typeof source.custom_data === 'object' && !Array.isArray(source.custom_data)
      ? source.custom_data
      : {}
  const eventParameters = source.eventParameters && typeof source.eventParameters === 'object' && !Array.isArray(source.eventParameters)
    ? source.eventParameters
    : source.event_parameters && typeof source.event_parameters === 'object' && !Array.isArray(source.event_parameters)
      ? source.event_parameters
      : {}
  const parameters = source.parameters && typeof source.parameters === 'object' && !Array.isArray(source.parameters)
    ? source.parameters
    : {}

  return {
    ...source,
    ...data,
    ...customData,
    ...eventParameters,
    ...parameters,
    custom: Array.isArray(parameters.custom)
      ? parameters.custom
      : Array.isArray(eventParameters.custom)
        ? eventParameters.custom
        : Array.isArray(customData.custom)
          ? customData.custom
          : Array.isArray(data.custom)
            ? data.custom
            : Array.isArray(source.custom)
              ? source.custom
              : []
  }
}

function normalizeImportedHtmlConversionMeta(meta = {}) {
  const source = getImportedHtmlConversionSource(meta)
  if (!source) return null

  const parameterSource = buildImportedHtmlConversionParameterSource(source)
  const rawEventName = firstImportedHtmlConversionValue(parameterSource, [
    'eventName',
    'event_name',
    'metaEventName',
    'meta_event_name',
    'conversionEvent',
    'conversion_event'
  ])
  const rawConversionType = firstImportedHtmlConversionValue(parameterSource, [
    'conversionType',
    'conversion_type',
    'type',
    'eventType',
    'event_type'
  ])
  const fallbackEventName = getImportedHtmlConversionDefaultEventName(rawConversionType) || DEFAULT_SITE_META_FORM_SUBMIT_EVENT_NAME
  const eventName = normalizeSiteMetaEventName(rawEventName, {
    allowNone: true,
    fallback: fallbackEventName
  })

  if (!rawEventName && !rawConversionType && !Object.keys(parameterSource).length) return null
  if (eventName === SITE_META_NO_EVENT) return null

  const conversionType = normalizeImportedHtmlConversionType(rawConversionType, eventName)
  const rawSubmitCondition = firstImportedHtmlConversionValue(parameterSource, [
    'submitCondition',
    'submit_condition',
    'conversionCondition',
    'conversion_condition'
  ])
  const status = firstImportedHtmlConversionValue(parameterSource, ['status', 'estado']) ||
    (conversionType === 'appointment_scheduled'
      ? 'booked'
      : conversionType === 'purchase'
        ? firstImportedHtmlConversionValue(parameterSource, ['paymentStatus', 'payment_status', 'paymentEstado']) || 'paid'
        : '')

  return {
    enabled: true,
    eventName,
    conversionType,
    submitCondition: rawSubmitCondition ? normalizeSiteMetaSubmitCondition(rawSubmitCondition) : '',
    parameters: pruneSiteMetaEventParametersForEvent(parameterSource, eventName),
    label: firstImportedHtmlConversionValue(parameterSource, ['label', 'name', 'nombre']),
    source: firstImportedHtmlConversionValue(parameterSource, ['source', 'conversionSource', 'conversion_source']),
    status,
    calendarId: firstImportedHtmlConversionValue(parameterSource, ['calendarId', 'calendar_id', 'calendarioId']),
    calendarName: firstImportedHtmlConversionValue(parameterSource, ['calendarName', 'calendar_name', 'calendario']),
    appointmentId: firstImportedHtmlConversionValue(parameterSource, ['appointmentId', 'appointment_id', 'citaId']),
    appointmentStatus: firstImportedHtmlConversionValue(parameterSource, ['appointmentStatus', 'appointment_status', 'citaEstado']) || (conversionType === 'appointment_scheduled' ? status || 'booked' : ''),
    appointmentStartTime: firstImportedHtmlConversionValue(parameterSource, ['appointmentStartTime', 'appointment_start_time', 'startTime', 'start_time', 'startsAt', 'starts_at']),
    appointmentEndTime: firstImportedHtmlConversionValue(parameterSource, ['appointmentEndTime', 'appointment_end_time', 'endTime', 'end_time', 'endsAt', 'ends_at']),
    paymentId: firstImportedHtmlConversionValue(parameterSource, ['paymentId', 'payment_id', 'publicPaymentId', 'public_payment_id', 'orderId', 'order_id']),
    paymentStatus: firstImportedHtmlConversionValue(parameterSource, ['paymentStatus', 'payment_status']) || (conversionType === 'purchase' ? status || 'paid' : ''),
    contentName: firstImportedHtmlConversionValue(parameterSource, ['contentName', 'content_name', 'productName', 'product_name', 'serviceName', 'service_name']),
    contentCategory: firstImportedHtmlConversionValue(parameterSource, ['contentCategory', 'content_category']),
    orderId: firstImportedHtmlConversionValue(parameterSource, ['orderId', 'order_id'])
  }
}

function hasSiteMetaEventParameters(parameters = {}) {
  const normalized = normalizeSiteMetaEventParameters(parameters)
  return Object.keys(SITE_META_PARAMETER_ALIASES).some(key => cleanString(normalized[key])) ||
    (Array.isArray(normalized.custom) && normalized.custom.some(parameter => cleanString(parameter.key) || cleanString(parameter.value)))
}

function pruneSiteMetaEventParametersForEvent(parameters = {}, eventName = SITE_META_NO_EVENT) {
  const normalized = normalizeSiteMetaEventParameters(parameters)
  const fields = getMetaParameterFieldsForEvent(eventName)
  if (!fields.length) return {}
  const allowed = new Set([...fields, ...SITE_META_LEGACY_SYSTEM_PARAMETER_FIELDS])
  const pruned = {}

  allowed.forEach(key => {
    const value = cleanString(normalized[key])
    if (value) pruned[key] = value
  })

  if (Array.isArray(normalized.custom) && normalized.custom.length) {
    pruned.custom = normalized.custom
  }

  return pruned
}

function parseMetaNumber(value) {
  const raw = cleanString(value).replace(/[$,\s]/g, '')
  if (!raw) return null
  const number = Number(raw)
  return Number.isFinite(number) ? number : null
}

function parseMetaContentIds(value) {
  return cleanString(value)
    .split(',')
    .map(item => cleanString(item))
    .filter(Boolean)
    .slice(0, 50)
}

function contactCustomFieldBagFromRow(row = {}) {
  const bag = {}
  parseContactCustomFields(row?.custom_fields || row?.customFields || row?.custom_fields_json).forEach((field = {}) => {
    const key = cleanString(field.fieldKey || field.field_key || field.key || field.id)
    if (!key) return
    bag[key] = field.value ?? ''
  })
  return bag
}

function normalizeContactForMetaTemplate(contact = {}, contactId = '') {
  const fullName = cleanString(contact.fullName || contact.full_name || contact.name)
  const names = splitName(fullName)
  const firstName = cleanString(contact.firstName || contact.first_name) || names.firstName
  const lastName = cleanString(contact.lastName || contact.last_name) || names.lastName
  return {
    id: cleanString(contact.id || contactId),
    firstName,
    lastName,
    first_name: firstName,
    last_name: lastName,
    fullName: fullName || [firstName, lastName].filter(Boolean).join(' '),
    full_name: fullName || [firstName, lastName].filter(Boolean).join(' '),
    name: fullName || [firstName, lastName].filter(Boolean).join(' '),
    phone: cleanString(contact.phone),
    email: cleanString(contact.email),
    source: cleanString(contact.source),
    created_at: cleanString(contact.created_at || contact.createdAt),
    updated_at: cleanString(contact.updated_at || contact.updatedAt),
    customFields: contact.customFields && typeof contact.customFields === 'object'
      ? contact.customFields
      : contactCustomFieldBagFromRow(contact)
  }
}

async function loadContactForMetaTemplate(contactId, fallback = {}) {
  const id = cleanString(contactId || fallback?.id)
  if (!id) return normalizeContactForMetaTemplate(fallback, id)
  const row = await db.get('SELECT * FROM contacts WHERE id = ? LIMIT 1', [id]).catch(() => null)
  return normalizeContactForMetaTemplate(row || fallback, id)
}

function buildSiteMetaTemplateContext({
  site = {},
  page = null,
  contact = {},
  contactId = '',
  requestMeta = {},
  accountCurrency = '',
  formResponses = null,
  mappedFields = null,
  rawFields = null,
  derivedFields = null,
  appointment = null,
  calendar = null,
  payment = null,
  variableFields = {}
} = {}) {
  const meta = requestMeta?.meta && typeof requestMeta.meta === 'object' ? requestMeta.meta : {}
  const paymentGate = meta.paymentGate && typeof meta.paymentGate === 'object' ? meta.paymentGate : {}
  const rules = meta.rules && typeof meta.rules === 'object' ? meta.rules : {}
  const normalizedContact = normalizeContactForMetaTemplate(contact, contactId)
  const resolvedFormResponses = formResponses ||
    meta.formResponses ||
    meta.form_responses ||
    meta.automationFormResponses ||
    meta.automation_form_responses ||
    {}
  const resolvedPayment = payment || {
    id: cleanString(paymentGate.publicPaymentId || paymentGate.public_payment_id),
    public_id: cleanString(paymentGate.publicPaymentId || paymentGate.public_payment_id),
    amount: paymentGate.amount,
    currency: cleanString(paymentGate.currency || accountCurrency),
    status: paymentGate.status || (paymentGate.required ? 'paid' : ''),
    provider: paymentGate.provider || paymentGate.gateway || ''
  }
  const resolvedAppointment = appointment || {}
  const resolvedCalendar = calendar || {}

  return {
    contact: normalizedContact,
    contactId: normalizedContact.id || contactId,
    siteId: site.id || '',
    siteName: site.name || '',
    pageId: page?.id || meta.pageId || meta.page_id || '',
    pageTitle: page?.title || '',
    currency: accountCurrency || resolvedPayment.currency || '',
    formId: meta.formSiteId || meta.form_site_id || site.id || '',
    formName: meta.formSiteName || meta.form_site_name || site.name || '',
    formStatus: meta.formStatus || meta.form_status || rules.status || '',
    formDisqualified: meta.formDisqualified ?? meta.form_disqualified ?? rules.disqualified ?? false,
    submissionId: meta.submissionId || meta.submission_id || '',
    submittedAt: meta.submittedAt || meta.submitted_at || '',
    formResponses: resolvedFormResponses,
    form_responses: resolvedFormResponses,
    responses: resolvedFormResponses,
    mappedFields: mappedFields || meta.mappedFields || meta.mapped_fields || {},
    rawFields: rawFields || meta.rawFields || meta.raw_fields || {},
    derivedFields: derivedFields || meta.derivedFields || meta.derived_fields || {},
    variable: variableFields && typeof variableFields === 'object' ? variableFields : {},
    payment: resolvedPayment,
    paymentId: resolvedPayment.id || resolvedPayment.public_id || '',
    amount: resolvedPayment.amount ?? '',
    currencyCode: resolvedPayment.currency || accountCurrency || '',
    paymentStatus: resolvedPayment.status || '',
    appointment: resolvedAppointment,
    appointmentId: resolvedAppointment.id || resolvedAppointment.appointmentId || '',
    appointmentDate: resolvedAppointment.date || resolvedAppointment.startTime || resolvedAppointment.start_time || '',
    appointmentTime: resolvedAppointment.time || resolvedAppointment.startTime || resolvedAppointment.start_time || '',
    appointmentStatus: resolvedAppointment.status || '',
    calendar: resolvedCalendar,
    calendarId: resolvedCalendar.id || resolvedAppointment.calendarId || resolvedAppointment.calendar_id || '',
    calendarName: resolvedCalendar.name || resolvedAppointment.calendarName || resolvedAppointment.calendar_name || ''
  }
}

function renderSiteMetaParameterValue(value, templateContext = {}) {
  const source = cleanString(value)
  if (!source) return ''
  if (!source.includes('{{')) return source
  return cleanString(renderTemplate(source, templateContext, { preserveUnknown: false }))
}

function buildSiteMetaConfiguredCustomData(parameters = {}, eventName = SITE_META_NO_EVENT, templateContext = {}) {
  const pruned = pruneSiteMetaEventParametersForEvent(parameters, eventName)
  const customData = {}

  const value = parseMetaNumber(renderSiteMetaParameterValue(pruned.value, templateContext))
  if (value !== null) customData.value = value

  const predictedLtv = parseMetaNumber(renderSiteMetaParameterValue(pruned.predictedLtv, templateContext))
  if (predictedLtv !== null) customData.predicted_ltv = predictedLtv

  const currency = cleanString(pruned.currency).toUpperCase().slice(0, 3)
  if (/^[A-Z]{3}$/.test(currency)) customData.currency = currency

  const contentIds = parseMetaContentIds(renderSiteMetaParameterValue(pruned.contentIds, templateContext))
  if (contentIds.length) customData.content_ids = contentIds

  const numItems = parseMetaNumber(renderSiteMetaParameterValue(pruned.numItems, templateContext))
  if (numItems !== null) customData.num_items = Math.max(0, Math.round(numItems))

  ;[
    ['contentName', 'content_name'],
    ['contentCategory', 'content_category'],
    ['contentType', 'content_type'],
    ['orderId', 'order_id'],
    ['status', 'status'],
    ['searchString', 'search_string']
  ].forEach(([sourceKey, targetKey]) => {
    const value = renderSiteMetaParameterValue(pruned[sourceKey], templateContext)
    if (value) customData[targetKey] = value
  })

  if (Array.isArray(pruned.custom)) {
    pruned.custom.forEach(parameter => {
      const key = normalizeSiteMetaCustomParameterKey(parameter.key)
      const value = renderSiteMetaParameterValue(parameter.value, templateContext)
      if (key && value) customData[key] = value
    })
  }

  return customData
}

function mergeSiteMetaCustomData(base = {}, configured = {}) {
  const reserved = {}
  ;[
    'source',
    'site_id',
    'site_name',
    'public_page_id',
    'public_page_title',
    'conversion_type',
    'calendar_id',
    'calendar_name',
    'appointment_id',
    'appointment_status',
    'appointment_start_time',
    'appointment_end_time',
    'currency',
    'status'
  ].forEach(key => {
    if (base[key] !== undefined) reserved[key] = base[key]
  })

  const merged = { ...base, ...configured, ...reserved }
  Object.keys(merged).forEach(key => {
    if (merged[key] === undefined || merged[key] === null || merged[key] === '') delete merged[key]
  })
  return merged
}

function normalizeFormCompletionAction(value, fallback = 'form_default') {
  const action = cleanString(value)
  return ['form_default', 'next_page', 'specific_page', 'specific_page_if_qualified', 'next_page_if_qualified', 'redirect', 'redirect_qualified'].includes(action) ? action : fallback
}

function normalizeFormDisqualifiedCompletionAction(value, fallback = 'disqualified_page') {
  const action = cleanString(value)
  return ['disqualified_page', 'redirect_url'].includes(action) ? action : fallback
}

function hasFormEmbedCompletionAction(settings = {}) {
  return Boolean(cleanString(settings.completionAction || settings.completion_action))
}

function getFormEmbedSourceSiteId(settings = {}) {
  return cleanString(
    settings.formSiteId ||
    settings.form_site_id ||
    settings.embeddedSiteId ||
    settings.embedded_site_id
  )
}

function getFormEmbedCompletionActionOrigin(settings = {}) {
  return cleanString(settings.completionActionOrigin || settings.completion_action_origin)
}

function hasForwardPageForBlockSettings(site, settings = {}) {
  const pages = normalizeSitePages(site)
  const pageId = getBlockPageId({ settings }, pages)
  return Boolean(getNextPage(site, pageId))
}

function shouldDefaultLandingBlockToNextPage(site, settings = {}) {
  return site?.siteType === 'landing_page' &&
    !isImportedHtmlSite(site) &&
    getSitePageMode(site) === 'funnel' &&
    hasForwardPageForBlockSettings(site, settings)
}

function applyFormEmbedCreateDefaults(site, settings = {}) {
  const next = isPlainObject(settings) ? { ...settings } : {}
  const sourceFormId = getFormEmbedSourceSiteId(next)
  if (
    shouldDefaultLandingBlockToNextPage(site, next) &&
    !sourceFormId &&
    !hasFormEmbedCompletionAction(next)
  ) {
    next.completionAction = 'next_page'
    next.completionActionOrigin = 'auto_funnel'
  } else if (
    sourceFormId &&
    hasFormEmbedCompletionAction(next) &&
    !getFormEmbedCompletionActionOrigin(next)
  ) {
    // API/MCP: si el consumidor manda una acción junto con el formulario fuente,
    // se considera deliberada. El editor marca sus defaults automáticos aparte.
    next.completionActionOrigin = 'user'
  }
  return next
}

function applyLinkedFormSelectionDefaults(existingSettings = {}, nextSettings = {}) {
  const next = isPlainObject(nextSettings) ? { ...nextSettings } : {}
  const previousSourceFormId = getFormEmbedSourceSiteId(existingSettings)
  const nextSourceFormId = getFormEmbedSourceSiteId(next)
  const actionOrigin = getFormEmbedCompletionActionOrigin(next)

  if (
    nextSourceFormId &&
    nextSourceFormId !== previousSourceFormId &&
    actionOrigin !== 'user'
  ) {
    // Elegir/cambiar el formulario fuente debe empezar respetando SUS reglas.
    // El bloque vacío de un funnel puede traer next_page como conveniencia, pero
    // ese default no puede convertir una respuesta descalificada en "siguiente".
    next.completionAction = 'form_default'
    next.completionActionOrigin = 'form_source'
  }

  return next
}

function hasCalendarCompletionAction(settings = {}) {
  return Boolean(cleanString(settings.calendarCompletionAction || settings.calendar_completion_action))
}

function applyCalendarEmbedCreateDefaults(site, settings = {}) {
  const next = isPlainObject(settings) ? { ...settings } : {}
  if (shouldDefaultLandingBlockToNextPage(site, next) && !hasCalendarCompletionAction(next)) {
    next.calendarCompletionAction = 'next_page'
  }
  return next
}

function hasPaymentPostAction(settings = {}) {
  const source = settings.postPayment && typeof settings.postPayment === 'object'
    ? settings.postPayment
    : settings.post_payment && typeof settings.post_payment === 'object'
      ? settings.post_payment
      : {}
  return Boolean(cleanString(source.action))
}

const PAYMENT_POST_SUCCESS_MESSAGE_DEFAULT = 'Tu pago fue realizado correctamente. Gracias por tu compra.'

function defaultPaymentPostActionForBlock(site, settings = {}) {
  return {
    action: shouldDefaultLandingBlockToNextPage(site, settings) ? 'next_page' : 'success_message',
    message: PAYMENT_POST_SUCCESS_MESSAGE_DEFAULT,
    pageId: '',
    url: ''
  }
}

function applyPaymentBlockCreateDefaults(site, settings = {}) {
  const next = isPlainObject(settings) ? { ...settings } : {}
  if (!hasPaymentPostAction(next)) {
    next.postPayment = defaultPaymentPostActionForBlock(site, next)
  }
  return next
}

function normalizeSiteMetaSubmitCondition(value, fallback = 'always') {
  const condition = cleanString(value)
  return SITE_META_SUBMIT_CONDITIONS.has(condition) ? condition : fallback
}

function shouldDefaultSiteSubmitMetaEvent(siteType, { hasDetectedForms = false } = {}) {
  return FORM_SITE_TYPES.has(siteType) || Boolean(hasDetectedForms)
}

function shouldDefaultSitePageViewMetaEvent(siteType) {
  return siteType === 'landing_page'
}

function normalizeThemeMetaCalendarEvents(theme = {}) {
  const source = theme?.metaCalendarEvents && typeof theme.metaCalendarEvents === 'object'
    ? theme.metaCalendarEvents
    : theme?.meta_calendar_events && typeof theme.meta_calendar_events === 'object'
      ? theme.meta_calendar_events
      : {}
  return source && typeof source === 'object' && !Array.isArray(source) ? source : {}
}

function applyConnectedMetaDefaultsToTheme(theme = {}, { enabled = false, siteType = 'landing_page', calendarSurfaceIds = [] } = {}) {
  if (!enabled) return theme

  const nextTheme = { ...theme }

  if (shouldDefaultSitePageViewMetaEvent(siteType) && Array.isArray(nextTheme.pages) && nextTheme.pages.length) {
    nextTheme.pages = nextTheme.pages.map(page => {
      const eventName = normalizeSiteMetaEventName(
        page?.metaEventName || page?.meta_event_name,
        { allowNone: true, fallback: SITE_META_NO_EVENT }
      )
      const hasEvent = eventName !== SITE_META_NO_EVENT
      return {
        ...page,
        metaCapiEnabled: true,
        metaEventName: hasEvent ? eventName : DEFAULT_SITE_META_PAGE_VIEW_EVENT_NAME,
        metaTrigger: 'page_view'
      }
    })
  }

  const surfaceIds = [...new Set((Array.isArray(calendarSurfaceIds) ? calendarSurfaceIds : [])
    .map(surfaceId => cleanString(surfaceId))
    .filter(Boolean))]
  if (surfaceIds.length) {
    const currentEvents = normalizeThemeMetaCalendarEvents(nextTheme)
    const nextEvents = { ...currentEvents }
    for (const surfaceId of surfaceIds) {
      const existing = currentEvents[surfaceId] && typeof currentEvents[surfaceId] === 'object'
        ? currentEvents[surfaceId]
        : {}
      const eventName = normalizeSiteMetaEventName(
        existing.eventName || existing.event_name,
        { allowNone: true, fallback: SITE_META_NO_EVENT }
      )
      nextEvents[surfaceId] = {
        ...existing,
        enabled: true,
        eventName: eventName === SITE_META_NO_EVENT ? DEFAULT_SITE_META_CALENDAR_EVENT_NAME : eventName
      }
    }
    nextTheme.metaCalendarEvents = nextEvents
    delete nextTheme.meta_calendar_events
  }

  return nextTheme
}

function applyConnectedMetaDefaultsToNewThemePages(currentTheme = {}, nextTheme = {}, { enabled = false, siteType = 'landing_page' } = {}) {
  if (!enabled || !shouldDefaultSitePageViewMetaEvent(siteType) || !Array.isArray(nextTheme?.pages)) return nextTheme

  const existingPageIds = new Set((Array.isArray(currentTheme?.pages) ? currentTheme.pages : [])
    .map(page => cleanString(page?.id))
    .filter(Boolean))
  let changed = false
  const pages = nextTheme.pages.map(page => {
    const pageId = cleanString(page?.id)
    if (!pageId || existingPageIds.has(pageId)) return page

    const eventName = normalizeSiteMetaEventName(
      page?.metaEventName || page?.meta_event_name,
      { allowNone: true, fallback: SITE_META_NO_EVENT }
    )
    changed = true
    return {
      ...page,
      metaCapiEnabled: true,
      metaEventName: eventName === SITE_META_NO_EVENT ? DEFAULT_SITE_META_PAGE_VIEW_EVENT_NAME : eventName,
      metaTrigger: 'page_view'
    }
  })

  return changed ? { ...nextTheme, pages } : nextTheme
}

async function ensureConnectedMetaCalendarSurfaceDefault(site = {}, surfaceId = '') {
  const normalizedSurfaceId = cleanString(surfaceId)
  if (!normalizedSurfaceId || !normalizeBoolean(site?.metaCapiEnabled)) return false
  if (!await hasConnectedMetaDatasetConfig()) return false

  const theme = { ...(site.theme || {}) }
  const currentEvents = normalizeThemeMetaCalendarEvents(theme)
  const existing = currentEvents[normalizedSurfaceId] && typeof currentEvents[normalizedSurfaceId] === 'object'
    ? currentEvents[normalizedSurfaceId]
    : {}
  const eventName = normalizeSiteMetaEventName(
    existing.eventName || existing.event_name,
    { allowNone: true, fallback: SITE_META_NO_EVENT }
  )

  theme.metaCalendarEvents = {
    ...currentEvents,
    [normalizedSurfaceId]: {
      ...existing,
      enabled: true,
      eventName: eventName === SITE_META_NO_EVENT ? DEFAULT_SITE_META_CALENDAR_EVENT_NAME : eventName
    }
  }
  delete theme.meta_calendar_events

  await db.run(
    'UPDATE public_sites SET theme_json = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?',
    [jsonString(theme), site.id]
  )
  return true
}

async function resolveConnectedMetaSiteCreateDefaults(input = {}, { siteType = 'landing_page', theme = {}, hasDetectedForms = false, calendarSurfaceIds = [] } = {}) {
  const connectedMetaDataset = await hasConnectedMetaDatasetConfig()
  const requestedMetaEventName = normalizeSiteMetaEventName(input.metaEventName, {
    allowNone: true,
    fallback: SITE_META_NO_EVENT
  })
  const shouldDefaultSubmit = connectedMetaDataset && shouldDefaultSiteSubmitMetaEvent(siteType, { hasDetectedForms })

  return {
    metaCapiEnabled: connectedMetaDataset ? true : normalizeBoolean(input.metaCapiEnabled),
    metaEventName: shouldDefaultSubmit && requestedMetaEventName === SITE_META_NO_EVENT
      ? DEFAULT_SITE_META_FORM_SUBMIT_EVENT_NAME
      : requestedMetaEventName,
    theme: applyConnectedMetaDefaultsToTheme(theme, {
      enabled: connectedMetaDataset,
      siteType,
      calendarSurfaceIds
    })
  }
}

function normalizeSubmitIncompleteOnExit(theme = {}) {
  const source = theme && typeof theme === 'object' ? theme : {}
  const value = Object.prototype.hasOwnProperty.call(source, 'submitIncompleteOnExit')
    ? source.submitIncompleteOnExit
    : source.submit_incomplete_on_exit
  if (value === undefined || value === null || value === '') return false
  return normalizeBoolean(value) === 1
}

function normalizeImportedContactCaptureMode(value = '') {
  const normalized = cleanString(value)
    .toLowerCase()
    .replace(/[\s-]+/g, '_')

  return [
    IMPORTED_CONTACT_CAPTURE_ALL_SUBMISSIONS,
    'all',
    'always',
    'every_submission'
  ].includes(normalized)
    ? IMPORTED_CONTACT_CAPTURE_ALL_SUBMISSIONS
    : IMPORTED_CONTACT_CAPTURE_QUALIFIED_ONLY
}

function getImportedContactCaptureModeFromAttrs(attrs = {}) {
  return normalizeImportedContactCaptureMode(
    attrs['data-rstk-contact-capture'] ||
    attrs['data-ristak-contact-capture'] ||
    attrs['data-ristack-contact-capture'] ||
    attrs['data-rstk-contact-save'] ||
    attrs['data-ristak-contact-save'] ||
    attrs['data-ristack-contact-save']
  )
}

function emptyContactUpsertResult() {
  return {
    contactId: null,
    created: false,
    changedFields: []
  }
}

function parseJson(value, fallback) {
  if (value === null || value === undefined || value === '') return fallback
  if (typeof value !== 'string') return value

  try {
    return JSON.parse(value)
  } catch {
    return fallback
  }
}

function jsonString(value) {
  try {
    return JSON.stringify(value ?? null)
  } catch {
    return JSON.stringify(null)
  }
}

function decodeBase64Text(value) {
  const raw = cleanString(value)
  if (!raw) return ''
  const base64 = raw.includes(',') ? raw.split(',').pop() : raw
  return Buffer.from(base64, 'base64').toString('utf8')
}

function decodeBase64Buffer(value) {
  const raw = cleanString(value)
  if (!raw) return Buffer.alloc(0)
  const base64 = raw.includes(',') ? raw.split(',').pop() : raw
  return Buffer.from(base64, 'base64')
}

function decodeHtmlEntities(value = '') {
  return cleanString(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
}

function stripHtmlTags(value = '') {
  return decodeHtmlEntities(String(value || '').replace(/<[^>]+>/g, ' '))
    .replace(/\s+/g, ' ')
    .trim()
}

function parseHtmlAttributes(attributeText = '') {
  const attrs = {}
  const pattern = /([:\w-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g
  let match
  while ((match = pattern.exec(attributeText || ''))) {
    const key = cleanString(match[1]).toLowerCase()
    if (!key) continue
    attrs[key] = decodeHtmlEntities(match[2] ?? match[3] ?? match[4] ?? '')
  }
  return attrs
}

function normalizeImportedFieldKey(value, fallback = 'custom_field') {
  return cleanString(value || fallback)
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '') || fallback
}

const IMPORTED_CALENDAR_BOOK_FORM_ATTR_PATTERN = /\bdata-(?:rstk|ristak|ristack)-calendar-book-form(?:\s|=|$)/i
const IMPORTED_CALENDAR_NATIVE_ATTR_NAMES = [
  'data-rstk-native-element',
  'data-ristak-native-element',
  'data-ristack-native-element',
  'data-rstk-element',
  'data-ristak-element',
  'data-ristack-element',
  'data-rstk-element-type',
  'data-ristak-element-type',
  'data-ristack-element-type',
  'data-rstk-component',
  'data-ristak-component',
  'data-ristack-component',
  'data-rstk-widget',
  'data-ristak-widget',
  'data-ristack-widget'
]
const IMPORTED_VOID_HTML_TAGS = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
  'meta', 'param', 'source', 'track', 'wbr'
])

function isImportedCalendarNativeAttrs(attrs = {}) {
  const value = IMPORTED_CALENDAR_NATIVE_ATTR_NAMES
    .map(name => cleanString(attrs[name]))
    .find(Boolean)
  const token = cleanString(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[_\s]+/g, '-')
  return ['calendar', 'calendars', 'calendario', 'calendarios', 'agenda', 'cita', 'citas', 'booking', 'appointment', 'appointments'].includes(token)
}

function isImportedFormInsideNativeCalendar(html = '', formOffset = -1) {
  const source = String(html || '')
  if (!source || formOffset < 0) return false

  const tagPattern = /<(\/?)\s*([a-z][\w:-]*)\b([^>]*)>/gi
  const stack = []
  let match
  while ((match = tagPattern.exec(source))) {
    if (match.index >= formOffset) break
    const closing = Boolean(match[1])
    const tagName = cleanString(match[2]).toLowerCase()
    if (closing) {
      const openingIndex = stack.map(entry => entry.tagName).lastIndexOf(tagName)
      if (openingIndex >= 0) stack.splice(openingIndex)
      continue
    }
    if (/\/\s*>$/.test(match[0]) || IMPORTED_VOID_HTML_TAGS.has(tagName)) continue
    stack.push({
      tagName,
      calendar: isImportedCalendarNativeAttrs(parseHtmlAttributes(match[3] || ''))
    })
  }
  return stack.some(entry => entry.calendar)
}

function isImportedCalendarBookingForm(html = '', formOffset = -1, attrsText = '') {
  return IMPORTED_CALENDAR_BOOK_FORM_ATTR_PATTERN.test(String(attrsText || '')) ||
    isImportedFormInsideNativeCalendar(html, formOffset)
}

function escapeRegExp(value = '') {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function normalizeImportedAssetPath(value = '') {
  const withoutNulls = String(value || '').replace(/\0/g, '').replace(/\\/g, '/').trim()
  if (!withoutNulls || withoutNulls.startsWith('/')) return ''

  const normalized = path.posix.normalize(withoutNulls).replace(/^\.\/+/, '')
  if (!normalized || normalized === '.' || normalized === '..' || normalized.startsWith('../')) return ''
  return normalized
}

function normalizeImportedCodeUpdatePath(value = '') {
  const rawPath = cleanString(value)
  if (!rawPath || rawPath === '__main__' || rawPath === 'main') return ''
  const assetPath = normalizeImportedAssetPath(rawPath)
  if (assetPath === IMPORTED_POPUP_CODE_PATH || rawPath === POPUP_SELECTED_ID) return IMPORTED_POPUP_CODE_PATH
  return assetPath
}

function normalizeImportedDraftHtmlFiles(files = []) {
  const drafts = new Map()
  if (!Array.isArray(files)) return drafts

  for (const file of files) {
    const rawPath = cleanString(file?.path ?? file?.assetPath ?? file?.asset_path ?? '')
    const assetPath = normalizeImportedCodeUpdatePath(rawPath)
    const isMainHtml = !rawPath || rawPath === '__main__' || rawPath === 'main'
    if (rawPath && !assetPath && !isMainHtml) {
      const error = new Error('Ruta de archivo inválida')
      error.status = 400
      throw error
    }
    if (assetPath === IMPORTED_POPUP_CODE_PATH) continue
    if (assetPath) {
      const contentType = getImportedAssetContentType(assetPath)
      if (getImportedCodeLanguage(assetPath, contentType) !== 'html') continue
    }

    const content = String(file?.content ?? '')
    if (Buffer.byteLength(content, 'utf8') > IMPORTED_CODE_FILE_MAX_BYTES) {
      const error = new Error(`El archivo ${assetPath || 'principal'} supera el límite permitido.`)
      error.status = 413
      throw error
    }
    drafts.set(assetPath, content)
  }

  return drafts
}

function prepareImportedDraftHtmlForRender(html = '', {
  siteId = '',
  assetPath = '',
  availablePaths = new Set(),
  pageIdByAssetPath = new Map(),
  usedFormIds = new Set()
} = {}) {
  const sanitized = sanitizeImportedHtml(html)
  const pageForms = namespaceImportedPageForms(detectImportedForms(sanitized.html), assetPath, usedFormIds)
  pageForms.forEach(form => {
    const formId = cleanString(form?.id)
    if (formId) usedFormIds.add(formId)
  })
  let output = assignImportedFormIds(sanitized.html, pageForms)
  output = rewriteImportedHtmlReferences(output, assetPath, siteId, availablePaths, { pageIdByAssetPath })
  return output
}

function getImportedAssetExtension(assetPath = '') {
  const basename = normalizeImportedAssetPath(assetPath).split('/').pop() || ''
  const extension = basename.includes('.') ? basename.split('.').pop()?.toLowerCase() : ''
  return extension || ''
}

function getImportedAssetContentType(assetPath = '') {
  return IMPORTED_ASSET_CONTENT_TYPES.get(getImportedAssetExtension(assetPath)) || 'application/octet-stream'
}

function isImportedCodeContentType(contentType = '', assetPath = '') {
  const normalizedContentType = cleanString(contentType).split(';')[0].toLowerCase()
  const extension = getImportedAssetExtension(assetPath)
  return IMPORTED_HTML_EXTENSIONS.has(extension) ||
    normalizedContentType.startsWith('text/') ||
    [
      'application/json',
      'application/xml',
      'application/manifest+json',
      'image/svg+xml'
    ].includes(normalizedContentType) ||
    ['css', 'js', 'mjs', 'json', 'txt', 'svg', 'xml', 'webmanifest', 'map'].includes(extension)
}

function getImportedCodeLanguage(assetPath = '', contentType = '') {
  const extension = getImportedAssetExtension(assetPath)
  const normalizedContentType = cleanString(contentType).split(';')[0].toLowerCase()
  if (IMPORTED_HTML_EXTENSIONS.has(extension) || normalizedContentType === 'text/html') return 'html'
  if (extension === 'css' || normalizedContentType === 'text/css') return 'css'
  if (extension === 'js' || extension === 'mjs' || normalizedContentType.includes('javascript')) return 'javascript'
  if (extension === 'json' || extension === 'map' || normalizedContentType === 'application/json') return 'json'
  if (extension === 'svg' || normalizedContentType === 'image/svg+xml') return 'svg'
  if (extension === 'xml' || normalizedContentType === 'application/xml') return 'xml'
  return 'text'
}

function shouldStoreImportedAssetInMediaStorage(file = {}) {
  const contentType = cleanString(file.contentType || getImportedAssetContentType(file.assetPath)).split(';')[0].toLowerCase()
  return contentType.startsWith('image/') ||
    contentType.startsWith('video/') ||
    contentType.startsWith('audio/') ||
    contentType === 'application/pdf'
}

function isSkippedImportedZipPath(assetPath = '') {
  const parts = normalizeImportedAssetPath(assetPath).split('/').map(part => part.toLowerCase())
  return parts.some(part => part === '__macosx' || part === '.ds_store' || part === 'thumbs.db')
}

function splitImportedUrlReference(value = '') {
  const raw = String(value || '').trim()
  const hashIndex = raw.indexOf('#')
  const beforeHash = hashIndex >= 0 ? raw.slice(0, hashIndex) : raw
  const hash = hashIndex >= 0 ? raw.slice(hashIndex) : ''
  const queryIndex = beforeHash.indexOf('?')
  const pathname = queryIndex >= 0 ? beforeHash.slice(0, queryIndex) : beforeHash
  const search = queryIndex >= 0 ? beforeHash.slice(queryIndex) : ''
  return { pathname, search, hash }
}

function isImportedExternalReference(value = '') {
  const reference = String(value || '').trim()
  return !reference || /^(?:[a-z][a-z0-9+.-]*:|\/\/|#)/i.test(reference)
}

function resolveImportedRelativeReference(referencePath = '', currentAssetPath = '') {
  const normalizedReference = String(referencePath || '').replace(/\\/g, '/').trim()
  if (!normalizedReference) return ''

  const currentPath = normalizeImportedAssetPath(currentAssetPath)
  const baseDir = currentPath.includes('/') ? currentPath.split('/').slice(0, -1).join('/') : ''
  const combined = normalizedReference.startsWith('/')
    ? normalizedReference.slice(1)
    : [baseDir, normalizedReference].filter(Boolean).join('/')
  return normalizeImportedAssetPath(combined)
}

function decodeImportedPathSegment(segment = '') {
  try {
    return decodeURIComponent(segment)
  } catch {
    return segment
  }
}

function getImportedAssetPublicUrl(siteId, assetPath) {
  const encodedPath = normalizeImportedAssetPath(assetPath)
    .split('/')
    .map(segment => encodeURIComponent(segment))
    .join('/')
  return `/api/sites/public/imported-assets/${encodeURIComponent(siteId)}/${encodedPath}`
}

function getImportedAssetPathFromPublicUrl(pathname = '', siteId = '') {
  const prefix = `/api/sites/public/imported-assets/${encodeURIComponent(siteId)}/`
  const rawPathname = String(pathname || '')
  if (!rawPathname.startsWith(prefix)) return ''

  return normalizeImportedAssetPath(
    rawPathname
      .slice(prefix.length)
      .split('/')
      .map(decodeImportedPathSegment)
      .join('/')
  )
}

function buildImportedPageIdByAssetPath(pages = []) {
  const entries = (Array.isArray(pages) ? pages : [])
    .map(page => [
      normalizeImportedAssetPath(page?.importedAssetPath || page?.imported_asset_path || page?.filename || page?.assetPath),
      cleanString(page?.id || page?.pageId || page?.page_id)
    ])
    .filter(([assetPath, pageId]) => assetPath && pageId)

  return new Map(entries)
}

function buildImportedPageQueryHref(pageId = '', search = '', hash = '') {
  const cleanPageId = cleanString(pageId)
  if (!cleanPageId) return hash || '#'

  const params = new URLSearchParams()
  params.set('page', cleanPageId)
  const extraParams = new URLSearchParams(String(search || '').replace(/^\?/, ''))
  extraParams.forEach((value, key) => {
    if (key !== 'page') params.append(key, value)
  })

  return `?${params.toString()}${hash || ''}`
}

function buildImportedPageHref(pageId = '', search = '', hash = '', options = {}) {
  const cleanPageId = cleanString(pageId)
  if (!cleanPageId) return hash || '#'
  if (options?.linkStyle === 'path' && options?.site) {
    return `${buildPublicPageRoutePath(options.site, cleanPageId)}${search || ''}${hash || ''}`
  }
  return buildImportedPageQueryHref(cleanPageId, search, hash)
}

function rewriteImportedReferenceValue(value, currentAssetPath, siteId, availablePaths, options = {}) {
  const raw = String(value || '')
  if (isImportedExternalReference(raw)) return raw

  const { pathname, search, hash } = splitImportedUrlReference(raw)
  if (options?.preferPageHref && options?.site) {
    const params = new URLSearchParams(String(search || '').replace(/^\?/, ''))
    const queryPageId = cleanString(params.get('page'))
    const queryPageExists = queryPageId && normalizeSitePages(options.site).some(page => page.id === queryPageId)
    if (queryPageExists) {
      params.delete('page')
      const nextSearch = params.toString() ? `?${params.toString()}` : ''
      return buildImportedPageHref(queryPageId, nextSearch, hash, options)
    }
  }
  const resolvedPath = resolveImportedRelativeReference(pathname, currentAssetPath)
  const publicAssetPath = getImportedAssetPathFromPublicUrl(pathname, siteId)
  if (!resolvedPath && !publicAssetPath) return raw

  let assetPath = publicAssetPath || resolvedPath
  if (!publicAssetPath && !availablePaths.has(assetPath) && String(pathname || '').startsWith('/')) {
    const currentPath = normalizeImportedAssetPath(currentAssetPath)
    const rootFolder = currentPath.includes('/') ? currentPath.split('/')[0] : ''
    const prefixedPath = rootFolder ? normalizeImportedAssetPath(`${rootFolder}/${assetPath}`) : ''
    if (prefixedPath && availablePaths.has(prefixedPath)) {
      assetPath = prefixedPath
    }
  }

  if (!availablePaths.has(assetPath)) return raw

  const pageIdByAssetPath = options?.pageIdByAssetPath instanceof Map ? options.pageIdByAssetPath : null
  if (options?.preferPageHref && pageIdByAssetPath?.has(assetPath)) {
    return buildImportedPageHref(pageIdByAssetPath.get(assetPath), search, hash, options)
  }

  return `${getImportedAssetPublicUrl(siteId, assetPath)}${search}${hash}`
}

function rewriteImportedSrcsetValue(value, currentAssetPath, siteId, availablePaths) {
  return String(value || '')
    .split(',')
    .map(candidate => {
      const trimmed = candidate.trim()
      if (!trimmed) return ''
      const [url, ...descriptor] = trimmed.split(/\s+/)
      return [rewriteImportedReferenceValue(url, currentAssetPath, siteId, availablePaths), ...descriptor].join(' ')
    })
    .filter(Boolean)
    .join(', ')
}

function rewriteImportedCssReferences(css = '', currentAssetPath = '', siteId = '', availablePaths = new Set()) {
  let rewritten = String(css || '').replace(/url\(\s*(["']?)([^"')]+)\1\s*\)/gi, (_match, quote, value) => {
    const nextValue = rewriteImportedReferenceValue(value, currentAssetPath, siteId, availablePaths)
    return `url(${quote || ''}${nextValue}${quote || ''})`
  })

  rewritten = rewritten.replace(/@import\s+(["'])([^"']+)\1/gi, (_match, quote, value) => {
    const nextValue = rewriteImportedReferenceValue(value, currentAssetPath, siteId, availablePaths)
    return `@import ${quote}${nextValue}${quote}`
  })

  return rewritten
}

function rewriteImportedHtmlReferences(html = '', currentAssetPath = '', siteId = '', availablePaths = new Set(), options = {}) {
  let rewritten = String(html || '').replace(/\s(src|href|poster|action|srcset)\s*=\s*(["'])([^"']*)\2/gi, (_match, attr, quote, value) => {
    const attrName = attr.toLowerCase()
    const nextValue = attr.toLowerCase() === 'srcset'
      ? rewriteImportedSrcsetValue(value, currentAssetPath, siteId, availablePaths)
      : rewriteImportedReferenceValue(value, currentAssetPath, siteId, availablePaths, {
        ...options,
        preferPageHref: attrName === 'href'
      })
    return ` ${attr}=${quote}${nextValue}${quote}`
  })

  rewritten = rewritten.replace(/\s(src|href|poster|action|srcset)\s*=\s*([^\s"'=<>`]+)/gi, (_match, attr, value) => {
    const attrName = attr.toLowerCase()
    const nextValue = attrName === 'srcset'
      ? rewriteImportedSrcsetValue(value, currentAssetPath, siteId, availablePaths)
      : rewriteImportedReferenceValue(value, currentAssetPath, siteId, availablePaths, {
        ...options,
        preferPageHref: attrName === 'href'
      })
    return ` ${attr}="${nextValue}"`
  })

  rewritten = rewritten.replace(/(<style\b[^>]*>)([\s\S]*?)(<\/style>)/gi, (_match, open, css, close) => (
    `${open}${rewriteImportedCssReferences(css, currentAssetPath, siteId, availablePaths)}${close}`
  ))

  return rewritten
}

async function getImportedSiteAvailableAssetPaths(siteId) {
  const rows = await db.all(`
    SELECT asset_path
    FROM public_site_import_assets
    WHERE site_id = ?
  `, [siteId]).catch(() => [])

  return new Set(rows.map(row => normalizeImportedAssetPath(row.asset_path)).filter(Boolean))
}

function rewriteImportedHtmlForRender(site, html = '', currentAssetPath = '', availablePaths = new Set(), options = {}) {
  const pages = normalizeSitePages(site)
  return rewriteImportedHtmlReferences(html, currentAssetPath, site.id, availablePaths, {
    site,
    linkStyle: options.linkStyle || 'query',
    pageIdByAssetPath: buildImportedPageIdByAssetPath(pages)
  })
}

function hasImportedAlias(haystack = '', aliases = []) {
  return aliases.some(alias => {
    const normalized = normalizeImportedFieldKey(alias, '')
    if (!normalized) return false
    return new RegExp(`(?:^|\\s)${escapeRegExp(normalized)}(?:\\s|$)`).test(haystack)
  })
}

function getImportedFieldHaystack(field = {}) {
  return [
    normalizeImportedFieldKey(field.explicitField, ''),
    field.sourceName,
    field.name,
    field.htmlId,
    field.type,
    field.label,
    field.placeholder,
    field.nearbyText
  ].map(value => normalizeImportedFieldKey(value, '')).filter(Boolean).join(' ')
}

function getImportedFieldContextTokens(field = {}) {
  return new Set(
    getImportedFieldHaystack(field)
      .split(/[\s_]+/)
      .map(token => normalizeImportedFieldKey(token, ''))
      .filter(Boolean)
  )
}

function hasImportedNameContextExclusion(field = {}) {
  const tokens = getImportedFieldContextTokens(field)
  return [...tokens].some(token => IMPORTED_NAME_CONTEXT_EXCLUSION_TOKENS.has(token))
}

function isImportedAmbiguousPersonNameField(field = {}) {
  const haystack = getImportedFieldHaystack(field)
  if (!hasImportedAlias(haystack, IMPORTED_AMBIGUOUS_PERSON_NAME_ALIASES)) return false
  return !hasImportedNameContextExclusion(field)
}

function isImportedAmbiguousMappedPersonNameField(field = {}) {
  return isImportedAmbiguousPersonNameField({
    sourceName: field.sourceName,
    name: field.sourceName,
    type: field.type,
    label: field.label,
    placeholder: field.label
  })
}

function getImportedStandardAliasKey(haystack = '') {
  if (hasImportedAlias(haystack, IMPORTED_STANDARD_FIELD_ALIASES.email)) return 'email'
  if (hasImportedAlias(haystack, IMPORTED_STANDARD_FIELD_ALIASES.phone)) return 'phone'
  if (hasImportedAlias(haystack, IMPORTED_CUSTOM_SYSTEM_FIELD_ALIASES.address_1)) return 'address_1'
  if (hasImportedAlias(haystack, IMPORTED_CUSTOM_SYSTEM_FIELD_ALIASES.company)) return 'company'
  if (hasImportedAlias(haystack, IMPORTED_CUSTOM_SYSTEM_FIELD_ALIASES.city)) return 'city'
  if (hasImportedAlias(haystack, IMPORTED_STANDARD_FIELD_ALIASES.last_name)) return 'last_name'
  if (hasImportedAlias(haystack, IMPORTED_STANDARD_FIELD_ALIASES.first_name)) return 'first_name'
  if (hasImportedAlias(haystack, IMPORTED_STANDARD_FIELD_ALIASES.full_name)) return 'full_name'
  if (hasImportedAlias(haystack, IMPORTED_STANDARD_FIELD_ALIASES.message)) return 'message'
  return ''
}

function getImportedFieldRoute(field = {}, fallbackKey = 'custom_field') {
  const destinationType = field.ignored
    ? 'ignored'
    : cleanString(field.destinationType || field.destination_type || field.saveMode || field.save_mode || 'custom').toLowerCase()
  const destinationKey = normalizeImportedFieldKey(
    field.destinationKey || field.destination_key || field.customFieldKey || field.custom_field_key ||
      field.sourceName || field.source_name || field.fieldId || field.field_id || field.label,
    fallbackKey
  )

  // `message` se ofreció históricamente como campo estándar, pero contacts no
  // tiene una columna con ese nombre. Convertimos ese contrato legacy a un campo
  // personalizado real para no perder respuestas de formularios ya publicados.
  if (destinationType === 'standard' && destinationKey === IMPORTED_FORM_LEGACY_MESSAGE_FIELD_KEY) {
    return {
      destinationType: 'new_custom',
      destinationKey: IMPORTED_FORM_MESSAGE_CUSTOM_FIELD_KEY,
      upgradedLegacyMessage: true
    }
  }

  return { destinationType, destinationKey, upgradedLegacyMessage: false }
}

function getImportedCustomHintDestination(haystack = '', allowedKeys = null) {
  const tokens = haystack.split(/\s+/).filter(Boolean)
  for (const [hint, key] of IMPORTED_FORM_CUSTOM_FIELD_HINTS.entries()) {
    if (allowedKeys && !allowedKeys.has(key)) continue
    const matched = tokens.some(token => (
      token === hint ||
      token.startsWith(`${hint}_`) ||
      token.endsWith(`_${hint}`)
    ))
    if (matched) {
      return { destinationType: 'custom', destinationKey: key, confidence: 0.76 }
    }
  }
  return null
}

function shouldApplyImportedStaticFallback(html = '') {
  return /\bclass\s*=\s*(["'])[^"']*\breveal\b[^"']*\1/i.test(html) || /\sdata-aos(?:\s|=|>)/i.test(html)
}

function injectImportedStaticFallback(html = '', report = []) {
  if (!shouldApplyImportedStaticFallback(html) || /data-rstk-import-static-fallback/i.test(html)) return html

  report.push('Se activo respaldo visual para animaciones sin scripts')

  if (/<\/head>/i.test(html)) {
    return html.replace(/<\/head>/i, `${IMPORTED_STATIC_FALLBACK_STYLE}</head>`)
  }

  if (/<body\b[^>]*>/i.test(html)) {
    return html.replace(/<body\b[^>]*>/i, match => `${match}${IMPORTED_STATIC_FALLBACK_STYLE}`)
  }

  return `${IMPORTED_STATIC_FALLBACK_STYLE}${html}`
}

function getRawTrackingCode(value) {
  return typeof value === 'string' ? value : ''
}

const SITE_CONTACT_TEMPLATE_PATTERN = /\{\{\s*(?:contact\.|custom\.)/i
const SITE_CONTACT_TEMPLATE_SKIPPED_KEYS = new Set([
  'headerTrackingCode',
  'header_tracking_code',
  'htmlOriginal',
  'htmlSanitized',
  'html_original',
  'html_sanitized',
  'import',
  'importedPopupHtml',
  'imported_popup_html'
])
const SITE_HEADER_TRACKING_KEYS = ['headerTrackingCode', 'header_tracking_code']

export function siteUsesContactTemplateVariables(site) {
  const seen = new WeakSet()

  const visit = (value, key = '', depth = 0) => {
    if (SITE_CONTACT_TEMPLATE_SKIPPED_KEYS.has(key)) return false
    if (typeof value === 'string') return SITE_CONTACT_TEMPLATE_PATTERN.test(value)
    if (value === null || typeof value !== 'object' || depth > 60) return false
    if (value instanceof Date || Buffer.isBuffer(value) || seen.has(value)) return false
    seen.add(value)

    if (Array.isArray(value)) return value.some(item => visit(item, '', depth + 1))
    const prototype = Object.getPrototypeOf(value)
    if (prototype !== Object.prototype && prototype !== null) return false
    return Object.entries(value).some(([childKey, childValue]) => visit(childValue, childKey, depth + 1))
  }

  return visit(site)
}

function detachManagedHeaderTrackingTemplates(theme) {
  if (!theme || typeof theme !== 'object' || Array.isArray(theme)) {
    return { theme, entries: [] }
  }

  const nextTheme = { ...theme }
  const entries = []
  for (const key of SITE_HEADER_TRACKING_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(nextTheme, key)) continue
    entries.push({ scope: 'theme', key, value: nextTheme[key] })
    delete nextTheme[key]
  }

  if (Array.isArray(nextTheme.pages)) {
    nextTheme.pages = nextTheme.pages.map((page, index) => {
      if (!page || typeof page !== 'object' || Array.isArray(page)) return page
      const nextPage = { ...page }
      for (const key of SITE_HEADER_TRACKING_KEYS) {
        if (!Object.prototype.hasOwnProperty.call(nextPage, key)) continue
        entries.push({ scope: 'page', index, key, value: nextPage[key] })
        delete nextPage[key]
      }
      return nextPage
    })
  }

  return { theme: nextTheme, entries }
}

async function restoreManagedHeaderTrackingTemplates(rendered, entries = []) {
  if (!rendered || typeof rendered !== 'object' || entries.length === 0) return rendered

  const sourceValues = Object.fromEntries(entries.map((entry, index) => [String(index), entry.value]))
  // Los headers son codigo administrado por la cuenta. Resuelven campos variables
  // globales, pero nunca reciben contexto de contacto: un dato capturado por un
  // formulario no puede convertirse en JavaScript ejecutable de una pagina publica.
  const renderedValues = await renderTemplateVariablesInValue(sourceValues, {}, { preserveUnknown: true })
  rendered.theme = rendered.theme && typeof rendered.theme === 'object' && !Array.isArray(rendered.theme)
    ? { ...rendered.theme }
    : {}

  for (const [index, entry] of entries.entries()) {
    const value = renderedValues?.[String(index)] ?? ''
    if (entry.scope === 'theme') {
      rendered.theme[entry.key] = value
      continue
    }

    if (!Array.isArray(rendered.theme.pages) || !rendered.theme.pages[entry.index]) continue
    rendered.theme.pages = [...rendered.theme.pages]
    rendered.theme.pages[entry.index] = {
      ...rendered.theme.pages[entry.index],
      [entry.key]: value
    }
  }

  return rendered
}

async function renderSiteTemplateVariables(site, options = {}) {
  if (!site || typeof site !== 'object') {
    return renderTemplateVariablesInValue(site, options, { preserveUnknown: true })
  }

  // El HTML importado se sanitiza al guardarse. Apartarlo de esta pasada evita
  // que el valor de una variable vuelva a introducir markup ejecutable después
  // de esa frontera. Headers, páginas, bloques y el resto del tema sí se resuelven.
  const source = { ...site }
  const preservedTopLevel = {}
  for (const key of ['htmlOriginal', 'htmlSanitized', 'html_original', 'html_sanitized', 'import']) {
    if (!Object.prototype.hasOwnProperty.call(source, key)) continue
    preservedTopLevel[key] = source[key]
    delete source[key]
  }

  let sourceTheme = source.theme && typeof source.theme === 'object' && !Array.isArray(source.theme)
    ? { ...source.theme }
    : source.theme
  const preservedTheme = {}
  if (sourceTheme && typeof sourceTheme === 'object') {
    for (const key of ['importedPopupHtml', 'imported_popup_html']) {
      if (!Object.prototype.hasOwnProperty.call(sourceTheme, key)) continue
      preservedTheme[key] = sourceTheme[key]
      delete sourceTheme[key]
    }
    const detachedHeaders = detachManagedHeaderTrackingTemplates(sourceTheme)
    sourceTheme = detachedHeaders.theme
    source.theme = sourceTheme

    const rendered = await renderTemplateVariablesInValue(source, options, { preserveUnknown: true })
    if (!rendered || typeof rendered !== 'object') return rendered

    Object.assign(rendered, preservedTopLevel)
    if (Object.keys(preservedTheme).length) {
      rendered.theme = { ...(rendered.theme || {}), ...preservedTheme }
    }
    return restoreManagedHeaderTrackingTemplates(rendered, detachedHeaders.entries)
  }

  const rendered = await renderTemplateVariablesInValue(source, options, { preserveUnknown: true })
  if (!rendered || typeof rendered !== 'object') return rendered

  Object.assign(rendered, preservedTopLevel)
  if (Object.keys(preservedTheme).length) {
    rendered.theme = { ...(rendered.theme || {}), ...preservedTheme }
  }
  return rendered
}

function buildHeaderTrackingCode(site, activePage = null, {
  trackingEnabled = true,
  preview = false
} = {}) {
  // El header administrado puede contener scripts de terceros que se ejecutan
  // en cuanto el navegador parsea el HTML. La compuerta debe vivir aqui, antes
  // de construir la respuesta, para que no exista una ruta de render que olvide
  // excluir Clarity, GTM u otro snippet cuando el request usa no_track/notrack.
  if (!trackingEnabled || preview) return ''

  const globalCode = getRawTrackingCode(site?.theme?.headerTrackingCode ?? site?.theme?.header_tracking_code)
  const pageCode = getRawTrackingCode(activePage?.headerTrackingCode ?? activePage?.header_tracking_code)

  return [globalCode, pageCode]
    .filter(code => cleanString(code))
    .join('\n')
}

function injectHtmlBeforeHeadClose(html = '', injection = '') {
  const safeHtml = html || '<!doctype html><html><head></head><body></body></html>'
  if (!cleanString(injection)) return safeHtml

  if (/<\/head>/i.test(safeHtml)) {
    return safeHtml.replace(/<\/head>/i, `${injection}\n</head>`)
  }

  if (/<body\b/i.test(safeHtml)) {
    return safeHtml.replace(/<body\b/i, `<head>\n${injection}\n</head>\n$&`)
  }

  return `${injection}\n${safeHtml}`
}

const SITE_SEO_RESERVED_CUSTOM_META_KEYS = new Set([
  'name:description',
  'name:keywords',
  'name:author',
  'name:twitter:card',
  'name:twitter:title',
  'name:twitter:description',
  'name:twitter:image',
  'property:og:title',
  'property:og:description',
  'property:og:image'
])

function normalizeSiteSeoLanguage(value = '') {
  const language = cleanString(value).split(/\s+-\s+|\s+/)[0] || 'es'
  return /^[a-z]{2,3}(?:-[a-z0-9]{2,8})*$/i.test(language) ? language : 'es'
}

function normalizeSiteSeoUrl(value = '', site = {}, publicHost = '') {
  let raw = cleanString(value)
  if (/^<link\b/i.test(raw)) {
    const attrs = parseHtmlAttributes(raw.replace(/^<link\b/i, '').replace(/\/?\s*>\s*$/i, ''))
    raw = cleanString(attrs.href)
  }
  if (!raw) return ''
  if (/^\/\//.test(raw)) raw = `https:${raw}`

  const host = normalizeDomain(publicHost || site?.domain)
  if (raw.startsWith('/') && !host) return raw

  try {
    const url = host ? new URL(raw, `https://${host}/`) : new URL(raw)
    return ['http:', 'https:'].includes(url.protocol) ? url.toString() : ''
  } catch {
    return ''
  }
}

function buildSafeCustomSeoMetaTags(value = '') {
  const tags = []
  const keys = new Set()
  const pattern = /<meta\b([^>]*)\/?\s*>/gi
  let match

  while ((match = pattern.exec(String(value || '')))) {
    const attrs = parseHtmlAttributes(match[1] || '')
    const attribute = cleanString(attrs.name) ? 'name' : cleanString(attrs.property) ? 'property' : ''
    const keyValue = cleanString(attrs[attribute]).toLowerCase()
    const key = attribute && keyValue ? `${attribute}:${keyValue}` : ''
    if (
      !key ||
      SITE_SEO_RESERVED_CUSTOM_META_KEYS.has(key) ||
      !/^[a-z0-9][a-z0-9:._-]{0,100}$/i.test(keyValue) ||
      !Object.prototype.hasOwnProperty.call(attrs, 'content')
    ) {
      continue
    }

    keys.add(key)
    tags.push(`<meta ${attribute}="${escapeHtml(keyValue)}" content="${escapeHtml(attrs.content)}">`)
  }

  return { tags: [...new Set(tags)], keys }
}

function buildSiteSeoHead(site = {}, { publicHost = '' } = {}) {
  const theme = site?.theme && typeof site.theme === 'object' ? site.theme : {}
  const title = cleanString(site?.title)
  const description = cleanString(site?.description)
  const keywords = cleanString(theme.seoKeywords)
  const author = cleanString(theme.seoAuthor)
  const rawImage = cleanString(theme.seoImage)
  const image = normalizeSiteSeoUrl(rawImage, site, publicHost)
  const rawCanonical = cleanString(theme.seoCanonicalLinks)
  const canonical = rawCanonical
    .split('\n')
    .map(line => normalizeSiteSeoUrl(line, site, publicHost))
    .find(Boolean) || ''
  const custom = buildSafeCustomSeoMetaTags(theme.seoMetaTags)
  const managedMetaKeys = new Set([
    'name:description',
    'name:twitter:title',
    'name:twitter:description',
    'property:og:title',
    'property:og:description',
    ...custom.keys
  ])
  const tags = []

  if (title) {
    tags.push(`<title>${escapeHtml(title)}</title>`)
    tags.push(`<meta property="og:title" content="${escapeHtml(title)}">`)
    tags.push(`<meta name="twitter:title" content="${escapeHtml(title)}">`)
  }
  if (description) {
    tags.push(`<meta name="description" content="${escapeHtml(description)}">`)
    tags.push(`<meta property="og:description" content="${escapeHtml(description)}">`)
    tags.push(`<meta name="twitter:description" content="${escapeHtml(description)}">`)
  }
  if (keywords) {
    managedMetaKeys.add('name:keywords')
    tags.push(`<meta name="keywords" content="${escapeHtml(keywords)}">`)
  }
  if (author) {
    managedMetaKeys.add('name:author')
    tags.push(`<meta name="author" content="${escapeHtml(author)}">`)
  }
  if (rawImage) {
    managedMetaKeys.add('property:og:image')
    managedMetaKeys.add('name:twitter:card')
    managedMetaKeys.add('name:twitter:image')
  }
  if (image) {
    tags.push(`<meta property="og:image" content="${escapeHtml(image)}">`)
    tags.push('<meta name="twitter:card" content="summary_large_image">')
    tags.push(`<meta name="twitter:image" content="${escapeHtml(image)}">`)
  }
  if (canonical) {
    tags.push(`<link rel="canonical" href="${escapeHtml(canonical)}">`)
  }
  tags.push(...custom.tags)

  return {
    tags,
    managedMetaKeys,
    replaceCanonical: Boolean(rawCanonical),
    language: normalizeSiteSeoLanguage(theme.seoLanguage)
  }
}

export function applySiteSeoToHtml(site = {}, html = '', options = {}) {
  const seo = buildSiteSeoHead(site, options)
  let output = String(html || '<!doctype html><html><head></head><body></body></html>')

  if (/<html\b/i.test(output)) {
    output = output.replace(/<html\b([^>]*)>/i, (_match, attrsText = '') => {
      const attrsWithoutLanguage = String(attrsText)
        .replace(/\s+lang(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?/gi, '')
      return `<html${attrsWithoutLanguage} lang="${escapeHtml(seo.language)}">`
    })
  } else {
    output = `<!doctype html><html lang="${escapeHtml(seo.language)}"><head></head><body>${output}</body></html>`
  }

  if (!/<head\b/i.test(output)) {
    output = /<body\b/i.test(output)
      ? output.replace(/<body\b/i, '<head></head>\n$&')
      : output.replace(/<html\b[^>]*>/i, '$&<head></head>')
  }

  return output.replace(/(<head\b[^>]*>)([\s\S]*?)(<\/head>)/i, (_match, open, head, close) => {
    const withoutTitle = String(head).replace(/<title\b[^>]*>[\s\S]*?<\/title\s*>/gi, '')
    const withoutManagedMeta = withoutTitle.replace(/<meta\b([^>]*)\/?\s*>/gi, (tag, attrsText = '') => {
      const attrs = parseHtmlAttributes(attrsText)
      const key = cleanString(attrs.name)
        ? `name:${cleanString(attrs.name).toLowerCase()}`
        : cleanString(attrs.property)
          ? `property:${cleanString(attrs.property).toLowerCase()}`
          : ''
      return key && seo.managedMetaKeys.has(key) ? '' : tag
    })
    const cleanHead = seo.replaceCanonical
      ? withoutManagedMeta.replace(/<link\b([^>]*)\/?\s*>/gi, (tag, attrsText = '') => {
          const rel = cleanString(parseHtmlAttributes(attrsText).rel).toLowerCase().split(/\s+/)
          return rel.includes('canonical') ? '' : tag
        })
      : withoutManagedMeta
    const seoMarkup = seo.tags.join('\n')
    return `${open}${cleanHead}${seoMarkup ? `\n${seoMarkup}\n` : ''}${close}`
  })
}

function sanitizeImportedIframeTag(attrsText = '', report = []) {
  const attrs = parseHtmlAttributes(attrsText)
  const src = safeEmbedUrl(attrs.src || '')
  const managedAssetKey = cleanSiteContentAssetKey(
    attrs['data-rstk-asset-id'] || attrs['data-ristak-asset-id'] || attrs['data-ristack-asset-id'] || ''
  )
  if (!src && !managedAssetKey) {
    report.push('Se quito 1 iframe inseguro')
    return ''
  }

  if (!src) report.push('Se preservo 1 iframe administrado por una clave de contenido')

  const title = limitString(attrs.title || attrs['aria-label'] || 'Código', 120)
  const allow = limitString(attrs.allow || DEFAULT_EMBED_ALLOW, 280) || DEFAULT_EMBED_ALLOW
  const className = cleanString(attrs.class)
  const id = cleanString(attrs.id)
  const style = cleanString(attrs.style)
  const width = cleanString(attrs.width)
  const height = cleanString(attrs.height)
  const dataAttrs = Object.entries(attrs)
    .filter(([key]) => /^data-(rstk|ristak|ristack)-/i.test(key))
    .map(([key, value]) => ` ${key}="${escapeHtml(value)}"`)
    .join('')
  return `<iframe${id ? ` id="${escapeHtml(id)}"` : ''}${className ? ` class="${escapeHtml(className)}"` : ''}${dataAttrs}${src ? ` src="${escapeHtml(src)}"` : ''} title="${escapeHtml(title)}"${width ? ` width="${escapeHtml(width)}"` : ''}${height ? ` height="${escapeHtml(height)}"` : ''}${style ? ` style="${escapeHtml(style)}"` : ''} loading="lazy" referrerpolicy="no-referrer-when-downgrade" sandbox="${EMBED_SANDBOX_URL}" allow="${escapeHtml(allow)}" allowfullscreen></iframe>`
}

function replaceImportedWistiaPlayers(html = '', report = []) {
  let converted = 0
  const replacePlayer = (match, attrsText = '') => {
    const mediaId = getWistiaMediaIdFromValue(attrsText || match)
    if (!mediaId) return match
    converted += 1
    return buildImportedVideoMediaMarkup(buildWistiaIframeUrl(mediaId))
  }

  const nextHtml = String(html || '')
    .replace(/<wistia-player\b([^>]*)>[\s\S]*?<\/wistia-player>/gi, replacePlayer)
    .replace(/<wistia-player\b([^>]*?)\s*\/>/gi, replacePlayer)

  if (converted) {
    report.push(`Se convirtieron ${converted} videos personalizados para que funcionen en la vista previa`)
  }
  return nextHtml
}

function normalizeImportedCaptureFormTag(match = '', attrsText = '') {
  const normalizedAttrs = String(attrsText || '')
    .replace(
      /\s+data-(?:rstk|ristak|ristack)-import-form(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?/gi,
      ''
    )
    .replace(
      /\s+novalidate(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?/gi,
      ''
    )
    .replace(/\s+$/g, '')

  return `<form${normalizedAttrs} data-rstk-import-form novalidate>`
}

function sanitizeImportedHtml(html = '') {
  const report = []
  let sanitized = String(html || '')

  if (!sanitized.trim()) {
    throw new Error('El archivo HTML esta vacio')
  }

  if (Buffer.byteLength(sanitized, 'utf8') > IMPORTED_HTML_MAX_BYTES) {
    throw new Error('El HTML es demasiado grande. Sube un archivo de máximo 2 MB.')
  }

  sanitized = replaceImportedWistiaPlayers(sanitized, report)

  const removals = [
    { pattern: /<script\b[\s\S]*?<\/script>/gi, label: 'scripts' },
    { pattern: /<object\b[\s\S]*?<\/object>/gi, label: 'objects' },
    { pattern: /<embed\b[\s\S]*?>/gi, label: 'embeds' },
    { pattern: /<meta\b[^>]*http-equiv\s*=\s*["']?refresh["']?[^>]*>/gi, label: 'meta refresh' },
    { pattern: /<base\b[^>]*>/gi, label: 'base tags' }
  ]

  for (const removal of removals) {
    const count = (sanitized.match(removal.pattern) || []).length
    if (count) report.push(`Se quitaron ${count} ${removal.label}`)
    sanitized = sanitized.replace(removal.pattern, '')
  }

  sanitized = sanitized.replace(/<iframe\b([^>]*)>[\s\S]*?<\/iframe>/gi, (_match, attrsText = '') => (
    sanitizeImportedIframeTag(attrsText, report)
  ))

  sanitized = sanitized.replace(/\s(on[a-z]+)\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, (_match, attr) => {
    report.push(`Se quito atributo ${attr}`)
    return ''
  })
  sanitized = sanitized.replace(/\s(href|src|action)\s*=\s*(["'])\s*javascript:[\s\S]*?\2/gi, (_match, attr) => {
    report.push(`Se bloqueo ${attr} con javascript`)
    return ` ${attr}="#"`;
  })
  sanitized = sanitized.replace(/<form\b([^>]*)>/gi, (match, attrsText = '', offset = -1) => (
    isImportedCalendarBookingForm(sanitized, offset, attrsText)
      ? match
      : normalizeImportedCaptureFormTag(match, attrsText)
  ))

  if (!/<html[\s>]/i.test(sanitized)) {
    sanitized = `<!doctype html><html lang="es"><head><meta charset="utf-8">${DEFAULT_IMPORTED_HTML_VIEWPORT_TAG}</head><body>${sanitized}</body></html>`
  } else {
    const viewportReadyHtml = ensureImportedHtmlViewport(sanitized)
    if (viewportReadyHtml !== sanitized) {
      report.push('Se normalizo meta viewport para respetar el ancho real del celular')
    }
    sanitized = viewportReadyHtml
  }

  if (!importedHtmlHasFavicon(sanitized)) {
    sanitized = ensureImportedHtmlFavicon(sanitized)
    report.push('Se agrego favicon de respaldo para la pestana del sitio')
  }

  sanitized = injectImportedStaticFallback(sanitized, report)
  sanitized = ensureImportedHtmlVideoActionTargets(sanitized)

  return {
    html: sanitized,
    report: Array.from(new Set(report))
  }
}

export function inspectImportedSiteHtml(html = '') {
  const sourceHtml = String(html || '')
  const sanitized = sanitizeImportedHtml(sourceHtml)
  const detectedForms = namespaceImportedPageForms(
    detectImportedForms(sanitized.html),
    '',
    new Set()
  )

  return {
    sourceBytes: Buffer.byteLength(sourceHtml, 'utf8'),
    sanitizedBytes: Buffer.byteLength(sanitized.html, 'utf8'),
    securityReport: sanitized.report,
    detectedForms
  }
}

function getEnclosingImportedHtmlElement(html = '', startIndex = -1, tagName = '') {
  const source = String(html || '')
  const normalizedTag = cleanString(tagName).toLowerCase()
  if (!source || startIndex < 0 || !normalizedTag) return null

  const tagPattern = new RegExp(`<(/?)${escapeRegExp(normalizedTag)}\\b([^>]*)>`, 'gi')
  const stack = []
  let match

  while ((match = tagPattern.exec(source))) {
    if (match.index >= startIndex) break
    if (match[1]) {
      stack.pop()
      continue
    }
    if (/\/\s*>$/.test(match[0])) continue
    stack.push({ attrsText: match[2] || '', contentStart: tagPattern.lastIndex })
  }

  const active = stack.at(-1)
  if (!active) return null

  tagPattern.lastIndex = active.contentStart
  let depth = 1
  let contentEnd = source.length
  while ((match = tagPattern.exec(source))) {
    depth += match[1] ? -1 : 1
    if (depth === 0) {
      contentEnd = match.index
      break
    }
  }

  return {
    attrs: parseHtmlAttributes(active.attrsText),
    body: source.slice(active.contentStart, contentEnd)
  }
}

function getLabelForField(html = '', attrs = {}, startIndex = -1) {
  const wrappingLabel = getEnclosingImportedHtmlElement(html, startIndex, 'label')
  const wrappingText = stripHtmlTags(wrappingLabel?.body || '')
  if (wrappingText) return wrappingText

  const id = cleanString(attrs.id)
  if (id) {
    const escapedId = id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const labelMatch = html.match(new RegExp(`<label\\b[^>]*for=["']?${escapedId}["']?[^>]*>([\\s\\S]*?)<\\/label>`, 'i'))
    if (labelMatch) return stripHtmlTags(labelMatch[1])
  }

  return ''
}

function getImportedChoiceGroupLabel(html = '', startIndex = -1) {
  const fieldset = getEnclosingImportedHtmlElement(html, startIndex, 'fieldset')
  if (!fieldset) return ''

  const explicitLabel = cleanString(
    fieldset.attrs['data-rstk-label'] ||
    fieldset.attrs['data-ristak-label'] ||
    fieldset.attrs['data-ristack-label'] ||
    fieldset.attrs['aria-label']
  )
  if (explicitLabel) return explicitLabel

  // Only accept a legend from this fieldset. A nested fieldset owns its own
  // legend and must not rename the outer choice group.
  const tokenPattern = /<\/?fieldset\b[^>]*>|<legend\b[^>]*>([\s\S]*?)<\/legend>/gi
  let nestedFieldsetDepth = 0
  let tokenMatch
  while ((tokenMatch = tokenPattern.exec(fieldset.body))) {
    if (tokenMatch[1] !== undefined) {
      if (nestedFieldsetDepth === 0) {
        const legend = stripHtmlTags(tokenMatch[1])
        if (legend) return legend
      }
      continue
    }
    nestedFieldsetDepth += /^<\//.test(tokenMatch[0]) ? -1 : 1
  }

  return ''
}

function isImportedTechnicalText(value = '') {
  const text = cleanString(value)
  if (!text) return false
  if (/\bdata-(?:rstk|ristak|ristack)-/i.test(text)) return true
  if (/\b(?:open_popup|close_popup|buttonUrl|appointment_start_time|dataLayer)\b/i.test(text)) return true
  if (/[{[\]"'=]/.test(text) && /\b(?:action|button|popup|rstk|ristak)\b/i.test(text)) return true
  return false
}

function getNearbyText(html = '', startIndex = 0) {
  const before = html.slice(Math.max(0, startIndex - 360), startIndex)
  const headingMatch = before.match(/<(h1|h2|h3|legend|strong|b|p)\b[^>]*>([\s\S]*?)<\/\1>/gi)
  const headings = headingMatch ? [...headingMatch].reverse() : []
  // The raw slice can start mid-tag; drop the leading tag fragment (attribute
  // soup ending in ">") so it does not leak into the visible title.
  const fallback = before.slice(-180).replace(/^[^<>]*>/, '')
  const candidates = [...headings, fallback]
    .map(candidate => limitString(stripHtmlTags(candidate), 120))
    .filter(Boolean)
  return candidates.find(candidate => !isImportedTechnicalText(candidate)) || ''
}

function getImportedFieldRequiredFromAttrs(attrs = {}) {
  const explicit = cleanString(
    attrs['data-rstk-field-required'] ||
    attrs['data-ristak-field-required'] ||
    attrs['data-ristack-field-required']
  ).toLowerCase()

  if (['0', 'false', 'no', 'off', 'optional'].includes(explicit)) return false
  if (['1', 'true', 'yes', 'on', 'required'].includes(explicit)) return true

  if (attrs.required !== undefined) return true
  if (cleanString(attrs['aria-required']).toLowerCase() === 'true') return true

  return false
}

function normalizeImportedFieldOptionValue(option = {}, index = 0) {
  const source = option && typeof option === 'object' ? option : { label: option, value: option }
  const label = limitString(stripHtmlTags(source.label || source.text || source.value || `Opción ${index + 1}`), 140)
  const value = limitString(cleanString(source.value || source.label || source.text || label), 140)
  if (!label && !value) return null

  // Per-option actions (e.g. disqualify when selecting this option).
  const actions = []
  if (Array.isArray(source.actions)) {
    for (const [actionIndex, item] of source.actions.entries()) {
      if (actions.length >= 3) break
      try {
        const step = normalizeImportedActionStep(item, actionIndex)
        if (step) actions.push(step)
      } catch {
        // Skip invalid steps instead of failing the whole option update.
      }
    }
  }

  return {
    label: label || value,
    value: value || label,
    ...(actions.length ? { actions } : {})
  }
}

function normalizeImportedFieldOptions(options = []) {
  if (!Array.isArray(options)) return []
  return options
    .map((option, index) => normalizeImportedFieldOptionValue(option, index))
    .filter(Boolean)
    .slice(0, 30)
}

function getImportedStableFieldIdFromAttrs(attrs = {}) {
  return cleanString(
    attrs['data-rstk-field-id'] ||
    attrs['data-ristack-field-id'] ||
    attrs['data-ristak-field-id']
  )
}

function getImportedChoiceGroupIdentity(formHtml = '', candidate = {}, type = '', attrs = {}, sourceName = '', fallback = '') {
  const declaredStableFieldId = getImportedStableFieldIdFromAttrs(attrs)
  const choiceName = cleanString(attrs.name)
  if (!choiceName) {
    return {
      fieldId: normalizeImportedFieldKey(declaredStableFieldId || sourceName, fallback),
      hasStableFieldId: Boolean(declaredStableFieldId),
      members: [{ attrs, index: candidate.index }]
    }
  }

  const members = []
  const choicePattern = /<input\b([^>]*?)\s*(\/?)>/gi
  let choiceMatch
  while ((choiceMatch = choicePattern.exec(formHtml))) {
    const choiceAttrs = parseHtmlAttributes(choiceMatch[1] || '')
    const choiceType = cleanString(choiceAttrs.type || 'text').toLowerCase()
    if (choiceType !== type || cleanString(choiceAttrs.name) !== choiceName) continue
    members.push({ attrs: choiceAttrs, index: choiceMatch.index })
  }

  const stableIds = members.map(member => getImportedStableFieldIdFromAttrs(member.attrs))
  const sharedStableFieldId = stableIds.length > 0 &&
    stableIds.every(Boolean) &&
    new Set(stableIds).size === 1
    ? stableIds[0]
    : ''

  // En HTML, name define la identidad de un grupo radio/checkbox. Algunos
  // generadores antiguos pusieron un data-rstk-field-id diferente en cada
  // opción; en ese caso esos IDs describen opciones, no preguntas distintas.
  return {
    fieldId: normalizeImportedFieldKey(sharedStableFieldId || choiceName, fallback),
    hasStableFieldId: Boolean(sharedStableFieldId),
    members: members.length ? members : [{ attrs, index: candidate.index }]
  }
}

function extractImportedFields(formHtml = '', formIndex = 0) {
  const fields = []
  const candidates = []
  const inputPattern = /<input\b([^>]*)\/?\s*>/gi
  const textareaPattern = /<textarea\b([^>]*)>([\s\S]*?)<\/textarea>/gi
  const selectPattern = /<select\b([^>]*)>([\s\S]*?)<\/select>/gi
  let match

  while ((match = inputPattern.exec(formHtml))) {
    candidates.push({ tag: 'input', attrsText: match[1] || '', body: '', index: match.index })
  }

  while ((match = textareaPattern.exec(formHtml))) {
    candidates.push({ tag: 'textarea', attrsText: match[1] || '', body: match[2] || '', index: match.index })
  }

  while ((match = selectPattern.exec(formHtml))) {
    candidates.push({ tag: 'select', attrsText: match[1] || '', body: match[2] || '', index: match.index })
  }

  candidates.sort((a, b) => a.index - b.index)

  let index = 0

  for (const candidate of candidates) {
    const tag = candidate.tag
    const attrs = parseHtmlAttributes(candidate.attrsText)
    const type = tag === 'input'
      ? cleanString(attrs.type || 'text').toLowerCase()
      : tag === 'select' && Object.prototype.hasOwnProperty.call(attrs, 'multiple')
        ? 'multiselect'
        : tag
    if (['hidden', 'submit', 'button', 'reset', 'image'].includes(type)) continue

    const stableFieldId = getImportedStableFieldIdFromAttrs(attrs)
    const explicitField = cleanString(attrs['data-rstk-field'] || attrs['data-ristack-field'] || attrs['data-ristak-field'])
    const explicitCustomField = cleanString(attrs['data-rstk-custom-field'] || attrs['data-ristack-custom-field'] || attrs['data-ristak-custom-field'])
    const sourceName = cleanString(attrs.name || attrs.id || stableFieldId || explicitField || explicitCustomField || `field_${formIndex + 1}_${index + 1}`)
    const isChoiceField = tag === 'input' && ['radio', 'checkbox'].includes(type)
    const fieldFallback = `field_${formIndex + 1}_${index + 1}`
    const choiceGroup = isChoiceField
      ? getImportedChoiceGroupIdentity(formHtml, candidate, type, attrs, sourceName, fieldFallback)
      : null
    const fieldId = choiceGroup?.fieldId || normalizeImportedFieldKey(stableFieldId || sourceName, fieldFallback)
    const explicitFieldLabel = cleanString(
      attrs['data-rstk-label'] ||
      attrs['data-ristak-label'] ||
      attrs['data-ristack-label'] ||
      attrs['aria-label']
    )
    // The label on an individual radio/checkbox describes that option. The
    // logical field is named by its enclosing choice group (fieldset), while
    // option labels continue to be collected independently below.
    const label = isChoiceField
      ? getImportedChoiceGroupLabel(formHtml, candidate.index) || sourceName
      : explicitFieldLabel || getLabelForField(formHtml, attrs, candidate.index) || cleanString(attrs.placeholder) || sourceName
    const options = []
    if (tag === 'select') {
      const optionPattern = /<option\b([^>]*)>([\s\S]*?)<\/option>/gi
      const selectHtml = candidate.body || ''
      let optionMatch
      while ((optionMatch = optionPattern.exec(selectHtml))) {
        const optionAttrs = parseHtmlAttributes(optionMatch[1] || '')
        const optionLabel = stripHtmlTags(optionMatch[2] || '')
        const value = cleanString(optionAttrs.value || optionLabel)
        if (value || optionLabel) {
          options.push({ label: optionLabel || value, value })
        }
      }
    } else if (tag === 'input' && ['radio', 'checkbox'].includes(type)) {
      for (const member of choiceGroup?.members || []) {
        const choiceAttrs = member.attrs || {}
        const choiceLabel = cleanString(
          choiceAttrs['data-rstk-label'] ||
          choiceAttrs['data-ristak-label'] ||
          choiceAttrs['data-ristack-label'] ||
          choiceAttrs['aria-label']
        ) || getLabelForField(formHtml, choiceAttrs, member.index) || cleanString(choiceAttrs.value)
        const value = cleanString(choiceAttrs.value || choiceLabel)
        if (value || choiceLabel) options.push({ label: choiceLabel || value, value })
      }
    }

    const field = {
      id: fieldId,
      sourceName,
      name: cleanString(attrs.name),
      htmlId: cleanString(attrs.id),
      hasStableFieldId: choiceGroup?.hasStableFieldId ?? Boolean(stableFieldId),
      type,
      tag,
      placeholder: cleanString(attrs.placeholder),
      label,
      nearbyText: getNearbyText(formHtml, candidate.index),
      explicitField,
      explicitCustomField,
      required: getImportedFieldRequiredFromAttrs(attrs),
      options
    }

    // Un radio/checkbox con varias opciones es un solo campo lógico. Cada input
    // comparte data-rstk-field-id (o name en HTML legacy), por lo que exponer
    // una fila por opción volvería ambigua la identidad y rompería el PATCH.
    const existingChoiceField = ['radio', 'checkbox'].includes(type)
      ? fields.find(existing => existing.id === fieldId && existing.type === type)
      : null
    if (existingChoiceField) {
      existingChoiceField.required = Boolean(existingChoiceField.required || field.required)
      const seenOptions = new Set()
      existingChoiceField.options = normalizeImportedFieldOptions([
        ...(existingChoiceField.options || []),
        ...(field.options || [])
      ]).filter(option => {
        const key = `${cleanString(option?.value)}::${cleanString(option?.label)}`
        if (seenOptions.has(key)) return false
        seenOptions.add(key)
        return true
      })
      continue
    }

    fields.push(field)
    index += 1
  }

  return fields
}

function detectImportedForms(html = '') {
  const forms = []
  const formPattern = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi
  let formMatch
  let formIndex = 0
  let sourceFormIndex = 0

  while ((formMatch = formPattern.exec(html))) {
    const attrs = parseHtmlAttributes(formMatch[1] || '')
    const calendarBookingForm = isImportedCalendarBookingForm(html, formMatch.index, formMatch[1] || '')
    if (calendarBookingForm) {
      sourceFormIndex += 1
      continue
    }
    const formHtml = formMatch[2] || ''
    const explicitForm = cleanString(attrs['data-rstk-form'] || attrs['data-ristack-form'] || attrs['data-ristak-form'])
    const importedFormId = cleanString(attrs['data-rstk-form-id'] || attrs['data-ristack-form-id'] || attrs['data-ristak-form-id'])
    const fields = extractImportedFields(formHtml, formIndex)
    const buttonMatch = formHtml.match(/<button\b([^>]*)>([\s\S]*?)<\/button>|<input\b([^>]*type=["']?submit["']?[^>]*)>/i)
    const submitText = buttonMatch
      ? stripHtmlTags(buttonMatch[2] || parseHtmlAttributes(buttonMatch[3] || '').value || 'Enviar')
      : 'Enviar'
    const title = cleanString(attrs['data-rstk-label'] || attrs['data-ristack-label'] || attrs['data-ristak-label']) ||
      getNearbyText(html, formMatch.index) || explicitForm || `Formulario ${formIndex + 1}`

    if (fields.length) {
      forms.push({
        id: normalizeImportedFieldKey(importedFormId || explicitForm || attrs.id || attrs.name || `form_${formIndex + 1}`, `form_${formIndex + 1}`),
        explicitForm,
        importedFormId,
        hasStableFormId: Boolean(importedFormId),
        sourceFormIndex,
        sourceFormOffset: formMatch.index,
        title,
        purpose: 'lead_capture',
        contactCaptureMode: getImportedContactCaptureModeFromAttrs(attrs),
        submitText,
        fields
      })
      formIndex += 1
    }
    sourceFormIndex += 1
  }

  return forms
}

function ensureUniqueImportedFormId(baseId = 'form', usedIds = new Set()) {
  const normalized = normalizeImportedFieldKey(baseId, 'form')
  let candidate = normalized
  let index = 2
  while (usedIds.has(candidate)) {
    candidate = `${normalized}_${index}`
    index += 1
  }
  usedIds.add(candidate)
  return candidate
}

function namespaceImportedPageForms(forms = [], pagePath = '', usedIds = new Set()) {
  const pageKey = normalizeImportedFieldKey(pagePath.replace(/\.[^.]+$/, ''), 'page')
  return forms.map((form, index) => {
    const explicitId = cleanString(form.explicitForm || form.importedFormId)
    const baseId = explicitId
      ? form.id
      : normalizeImportedFieldKey(`${pageKey}_${form.id || `form_${index + 1}`}`, `form_${index + 1}`)
    // Un ID explícito es un contrato del autor. Si está duplicado no se corrige
    // a escondidas: se conserva para que el panel lo marque ambiguo y el runtime
    // rechace el submit hasta que el código use IDs únicos. Solo generamos IDs
    // únicos para formularios legacy que no declararon una identidad estable.
    const id = explicitId
      ? normalizeImportedFieldKey(baseId, `form_${index + 1}`)
      : ensureUniqueImportedFormId(baseId, usedIds)
    usedIds.add(id)

    return {
      ...form,
      id,
      pagePath,
      title: cleanString(form.title) || `Formulario ${index + 1}`
    }
  })
}

function assignImportedFormIds(html = '', forms = []) {
  const detectedForms = Array.isArray(forms) ? forms : []
  const formsByOffset = new Map(detectedForms
    .filter(form => Number.isInteger(form?.sourceFormOffset) && form.sourceFormOffset >= 0)
    .map(form => [form.sourceFormOffset, form]))
  const formsBySourceIndex = new Map(detectedForms
    .filter(form => Number.isInteger(form?.sourceFormIndex) && form.sourceFormIndex >= 0)
    .map(form => [form.sourceFormIndex, form]))
  const hasSourcePositions = formsByOffset.size > 0 || formsBySourceIndex.size > 0
  let sourceFormIndex = 0
  let legacyDetectedFormIndex = 0

  return String(html || '').replace(/<form\b([^>]*)>/gi, (match, attrsText = '', offset = -1) => {
    const attrs = parseHtmlAttributes(attrsText)
    const calendarBookingForm = isImportedCalendarBookingForm(html, offset, attrsText)
    if (calendarBookingForm) {
      sourceFormIndex += 1
      return match
    }
    const detectedForm = hasSourcePositions
      ? formsByOffset.get(offset) || formsBySourceIndex.get(sourceFormIndex) || null
      : detectedForms[legacyDetectedFormIndex] || null
    sourceFormIndex += 1
    if (!hasSourcePositions) legacyDetectedFormIndex += 1

    // Un formulario sin campos guardables no pertenece al arreglo detectado.
    // Debe quedarse intacto y, sobre todo, no consumir el ID del siguiente form.
    if (!detectedForm) return match
    if (cleanString(attrs['data-rstk-form-id'])) {
      return match
    }

    const formId = cleanString(detectedForm.id)
    if (!formId) return match

    return `<form${attrsText} data-rstk-form-id="${escapeHtml(formId)}">`
  })
}

function getImportedEditableAttr(attrs = {}, key = '') {
  const aliases = IMPORTED_EDITABLE_ATTR_ALIASES[key] || []
  for (const alias of aliases) {
    const value = cleanString(attrs[alias])
    if (value) return value
  }
  return ''
}

function hasImportedEditableAttr(attrs = {}, key = '') {
  return Boolean(getImportedEditableAttr(attrs, key))
}

function collectImportedEditableIds(html = '') {
  const ids = new Set()
  const tagPattern = /<[a-z][\w:-]*\b([^>]*)>/gi
  let match
  while ((match = tagPattern.exec(String(html || '')))) {
    const id = getImportedEditableAttr(parseHtmlAttributes(match[1] || ''), 'id')
    if (id) ids.add(id)
  }
  return ids
}

function normalizeImportedEditableContentType(value = '') {
  const type = cleanString(value).toLowerCase().replace(/[-\s]+/g, '_')
  return IMPORTED_EDITABLE_CONTENT_TYPES.has(type) ? type : ''
}

function makeImportedEditableId(type = 'text', label = '', usedIds = new Set()) {
  const base = normalizeImportedFieldKey(`${type}_${label || 'elemento'}`, `${type}_elemento`).slice(0, 72)
  let candidate = base
  let index = 2
  while (usedIds.has(candidate)) {
    candidate = `${base}_${index}`
    index += 1
  }
  usedIds.add(candidate)
  return candidate
}

function buildImportedEditableAttributes(attrsText = '', { type = 'text', label = '', usedIds = new Set() } = {}) {
  const attrs = parseHtmlAttributes(attrsText)
  const additions = []
  const normalizedType = normalizeImportedEditableContentType(type) || 'text'
  const normalizedLabel = limitString(stripHtmlTags(label) || attrs.alt || attrs.placeholder || attrs.name || attrs.id || normalizedType, 80)

  if (!hasImportedEditableAttr(attrs, 'editable')) additions.push('data-rstk-editable="true"')
  if (!hasImportedEditableAttr(attrs, 'type')) additions.push(`data-rstk-edit-type="${escapeHtml(normalizedType)}"`)
  if (!hasImportedEditableAttr(attrs, 'label')) additions.push(`data-rstk-label="${escapeHtml(normalizedLabel)}"`)
  if (!hasImportedEditableAttr(attrs, 'id')) {
    additions.push(`data-rstk-edit-id="${escapeHtml(makeImportedEditableId(normalizedType, normalizedLabel, usedIds))}"`)
  }

  return additions.length ? ` ${additions.join(' ')}` : ''
}

function buildImportedSectionAttributes(attrsText = '', { label = '' } = {}) {
  const attrs = parseHtmlAttributes(attrsText)
  const additions = []
  const normalizedLabel = limitString(stripHtmlTags(label) || attrs.id || attrs.class || 'Seccion', 80)

  if (!hasImportedEditableAttr(attrs, 'section')) additions.push(`data-rstk-section="${escapeHtml(normalizedLabel)}"`)
  if (!hasImportedEditableAttr(attrs, 'label')) additions.push(`data-rstk-label="${escapeHtml(normalizedLabel)}"`)

  return additions.length ? ` ${additions.join(' ')}` : ''
}

function addImportedEditableAttributesToTag(tagName = 'div', attrsText = '', selfClose = '', options = {}) {
  return `<${tagName}${attrsText}${buildImportedEditableAttributes(attrsText, options)}${selfClose ? ' /' : ''}>`
}

function addImportedSectionAttributesToTag(tagName = 'section', attrsText = '', selfClose = '', options = {}) {
  return `<${tagName}${attrsText}${buildImportedSectionAttributes(attrsText, options)}${selfClose ? ' /' : ''}>`
}

function isSimpleEditableTextHtml(innerHtml = '') {
  const text = stripHtmlTags(innerHtml)
  if (!text || text.length > 1200) return false
  return !/<(script|style|form|fieldset|input|textarea|select|option|button|a|img|picture|svg|video|iframe|table|ul|ol|li|section|article|header|footer|main|div)\b/i.test(innerHtml)
}

// Containers (div/span/li/...) only qualify as editable text when they hold
// plain inline text — not when they wrap headings/paragraphs/labels, which are
// annotated on their own.
function isSimpleEditableInlineTextHtml(innerHtml = '') {
  return isSimpleEditableTextHtml(innerHtml) && !/<(p|h[1-6]|label|blockquote|figcaption|span)\b/i.test(innerHtml)
}

function getImportedElementLabel(tagName = '', attrs = {}, fallback = '') {
  return limitString(
    attrs['aria-label'] ||
    attrs.alt ||
    attrs.placeholder ||
    attrs.value ||
    attrs.name ||
    attrs.id ||
    attrs.class ||
    fallback ||
    tagName,
    80
  )
}

function getImportedTextEditType(tagName = '', attrs = {}) {
  const tag = cleanString(tagName).toLowerCase()
  if (/^h[1-6]$/.test(tag)) return 'heading'
  if (tag === 'label') return 'form_label'
  if (tag === 'button') return 'button'
  if (tag === 'a') {
    const buttonHint = `${attrs.role || ''} ${attrs.class || ''} ${attrs.id || ''}`.toLowerCase()
    return /\b(button|btn|boton|cta|call|action)\b/.test(buttonHint) ? 'button' : 'text'
  }
  return 'text'
}

function annotateImportedTextTags(html = '', usedIds = new Set()) {
  return String(html || '').replace(/<(h[1-6]|p|label|button|a)\b([^>]*)>([\s\S]*?)<\/\1>/gi, (match, tagName, attrsText = '', innerHtml = '') => {
    if (!isSimpleEditableTextHtml(innerHtml)) return match
    const attrs = parseHtmlAttributes(attrsText)
    const openTag = addImportedEditableAttributesToTag(tagName, attrsText, '', {
      type: getImportedTextEditType(tagName, attrs),
      label: getImportedElementLabel(tagName, attrs, stripHtmlTags(innerHtml)),
      usedIds
    })
    return `${openTag}${innerHtml}</${tagName}>`
  })
}

// Modern pages carry visible copy in generic containers (Tailwind spans/divs,
// list items, table cells). Annotate the innermost ones that hold simple text so
// they are editable too. The tempered pattern (no same-tag nesting inside the
// match) keeps the regex anchored to innermost elements.
const IMPORTED_SIMPLE_TEXT_CONTAINER_TAGS = ['span', 'li', 'td', 'th', 'blockquote', 'figcaption', 'div']

function annotateImportedSimpleTextContainers(html = '', usedIds = new Set()) {
  let nextHtml = String(html || '')
  for (const tag of IMPORTED_SIMPLE_TEXT_CONTAINER_TAGS) {
    const pattern = new RegExp(`<${tag}\\b([^>]*)>((?:(?!<${tag}\\b|</${tag})[\\s\\S])*?)</${tag}>`, 'gi')
    nextHtml = nextHtml.replace(pattern, (match, attrsText = '', innerHtml = '') => {
      const attrs = parseHtmlAttributes(attrsText)
      if (hasImportedEditableAttr(attrs, 'editable') || hasImportedEditableAttr(attrs, 'type')) return match
      if (!isSimpleEditableInlineTextHtml(innerHtml)) return match
      if (isLikelyImportedVideoElement(tag, attrs)) return match
      const openTag = addImportedEditableAttributesToTag(tag, attrsText, '', {
        type: 'text',
        label: getImportedElementLabel(tag, attrs, stripHtmlTags(innerHtml)),
        usedIds
      })
      return `${openTag}${innerHtml}</${tag}>`
    })
  }
  return nextHtml
}

function annotateImportedInputs(html = '', usedIds = new Set()) {
  let nextHtml = String(html || '').replace(/<input\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '', selfClose = '') => {
    const attrs = parseHtmlAttributes(attrsText)
    const type = cleanString(attrs.type || 'text').toLowerCase()
    if (['radio', 'checkbox'].includes(type)) {
      const editableTag = addImportedEditableAttributesToTag('input', attrsText, selfClose, {
        type: 'form_field',
        label: getImportedElementLabel('input', attrs, attrs.value || attrs.name || 'Opción'),
        usedIds
      })
      return setImportedDefaultFieldRequired(editableTag, attrsText)
    }
    if (['hidden', 'reset', 'file'].includes(type)) return match
    if (['submit', 'button'].includes(type)) {
      return addImportedEditableAttributesToTag('input', attrsText, selfClose, {
        type: 'button',
        label: getImportedElementLabel('input', attrs, attrs.value || 'Botón'),
        usedIds
      })
    }
    const editableTag = addImportedEditableAttributesToTag('input', attrsText, selfClose, {
      type: 'form_field',
      label: getImportedElementLabel('input', attrs, attrs.placeholder || attrs.name || attrs.id || 'Campo'),
      usedIds
    })
    return setImportedDefaultFieldRequired(editableTag, attrsText)
  })

  nextHtml = nextHtml.replace(/<textarea\b([^>]*)>([\s\S]*?)<\/textarea>/gi, (match, attrsText = '', innerHtml = '') => {
    const attrs = parseHtmlAttributes(attrsText)
    const openTag = addImportedEditableAttributesToTag('textarea', attrsText, '', {
      type: 'form_field',
      label: getImportedElementLabel('textarea', attrs, attrs.placeholder || attrs.name || attrs.id || 'Campo'),
      usedIds
    })
    return `${setImportedDefaultFieldRequired(openTag, attrsText)}${innerHtml}</textarea>`
  })

  nextHtml = nextHtml.replace(/<select\b([^>]*)>([\s\S]*?)<\/select>/gi, (match, attrsText = '', innerHtml = '') => {
    const attrs = parseHtmlAttributes(attrsText)
    const openTag = addImportedEditableAttributesToTag('select', attrsText, '', {
      type: 'form_field',
      label: getImportedElementLabel('select', attrs, attrs.name || attrs.id || 'Campo'),
      usedIds
    })
    return `${setImportedDefaultFieldRequired(openTag, attrsText)}${innerHtml}</select>`
  })

  return nextHtml
}

function annotateImportedImages(html = '', usedIds = new Set()) {
  return String(html || '').replace(/<img\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '', selfClose = '') => {
    const attrs = parseHtmlAttributes(attrsText)
    if (!cleanString(attrs.src)) return match
    return addImportedEditableAttributesToTag('img', attrsText, selfClose, {
      type: 'image',
      label: getImportedElementLabel('img', attrs, 'Imagen'),
      usedIds
    })
  })
}

const IMPORTED_VIDEO_HINT_PATTERN = /\b(video|videos|vsl|player|embed|iframe|youtube|youtu|vimeo|wistia|loom|vidyard|webinar|presentacion|presentation|reproductor|curso|clase)\b/i
const IMPORTED_DIRECT_VIDEO_PATTERN = /\.(mp4|webm|ogg|mov)(?:$|[?#])/i

function isLikelyImportedVideoElement(tagName = '', attrs = {}) {
  const tag = cleanString(tagName).toLowerCase()
  if (tag === 'video') return true
  if (tag === 'wistia-player') return true

  const srcHint = `${attrs.src || ''} ${attrs.data || ''} ${attrs.poster || ''} ${attrs.type || ''}`
  const textHint = [
    attrs.id,
    attrs.class,
    attrs.title,
    attrs['aria-label'],
    attrs.name,
    attrs.role,
    attrs['data-video'],
    attrs['data-video-url'],
    attrs['data-src'],
    attrs['data-embed'],
    attrs['data-wistia-id'],
    attrs['data-youtube-id'],
    attrs['data-vimeo-id']
  ].map(value => cleanString(value)).filter(Boolean).join(' ')
  const combinedHint = `${srcHint} ${textHint}`

  if (['iframe', 'embed', 'object'].includes(tag)) {
    return IMPORTED_VIDEO_HINT_PATTERN.test(combinedHint) ||
      IMPORTED_DIRECT_VIDEO_PATTERN.test(combinedHint) ||
      /(?:youtube\.com|youtu\.be|vimeo\.com|wistia\.(?:com|net)|loom\.com|vidyard\.com)/i.test(combinedHint)
  }

  if (!['div', 'section', 'article', 'figure', 'aside'].includes(tag)) return false
  if (IMPORTED_VIDEO_HINT_PATTERN.test(combinedHint)) return true

  const style = cleanString(attrs.style)
  const hasMediaShape = /aspect-ratio\s*:\s*(16\s*\/\s*9|1\.7)/i.test(style) ||
    /\b(min-)?height\s*:\s*(1[8-9]\d|[2-9]\d{2})px/i.test(style)
  const hasDarkSurface = /background(?:-color)?\s*:\s*(#000|#000000|black|rgb\(\s*0\s*,\s*0\s*,\s*0\s*\))/i.test(style)
  return hasMediaShape && hasDarkSurface
}

function annotateImportedVideos(html = '', usedIds = new Set()) {
  return String(html || '').replace(/<([a-z][\w:-]*)\b([^>]*?)\s*(\/?)>/gi, (match, tagName = '', attrsText = '', selfClose = '') => {
    const attrs = parseHtmlAttributes(attrsText)
    if (hasImportedEditableAttr(attrs, 'type')) return match
    if (!isLikelyImportedVideoElement(tagName, attrs)) return match
    return addImportedEditableAttributesToTag(tagName, attrsText, selfClose, {
      type: 'video',
      label: getImportedElementLabel(tagName, attrs, 'Video'),
      usedIds
    })
  })
}

function annotateImportedBackgroundImages(html = '', usedIds = new Set()) {
  return String(html || '').replace(/<([a-z][\w:-]*)\b([^>]*)>/gi, (match, tagName, attrsText = '') => {
    const tag = cleanString(tagName).toLowerCase()
    if (['img', 'html', 'head', 'meta', 'link', 'style', 'script'].includes(tag)) return match
    const attrs = parseHtmlAttributes(attrsText)
    if (!cleanString(attrs.style) || !/background(?:-image)?\s*:/i.test(attrs.style) || !/url\s*\(/i.test(attrs.style)) return match
    if (hasImportedEditableAttr(attrs, 'type')) return match
    return addImportedEditableAttributesToTag(tagName, attrsText, '', {
      type: 'background_image',
      label: getImportedElementLabel(tagName, attrs, 'Imagen de fondo'),
      usedIds
    })
  })
}

function annotateImportedSections(html = '') {
  return String(html || '').replace(/<(section|header|main|footer|article|div)\b([^>]*)>/gi, (match, tagName, attrsText = '') => {
    const attrs = parseHtmlAttributes(attrsText)
    const tag = cleanString(tagName).toLowerCase()
    const classHint = `${attrs.id || ''} ${attrs.class || ''}`.toLowerCase()
    const shouldMark = tag !== 'div' || /\b(hero|section|container|wrapper|banner|features|services|contact|form|cta|footer|header|main)\b/.test(classHint)
    if (!shouldMark) return match
    return addImportedSectionAttributesToTag(tagName, attrsText, '', {
      label: getImportedElementLabel(tagName, attrs, tag === 'div' ? 'Seccion' : tag)
    })
  })
}

function annotateImportedEditableHtml(html = '') {
  const usedIds = collectImportedEditableIds(html)
  let nextHtml = annotateImportedSections(html)
  nextHtml = annotateImportedTextTags(nextHtml, usedIds)
  nextHtml = annotateImportedSimpleTextContainers(nextHtml, usedIds)
  nextHtml = annotateImportedInputs(nextHtml, usedIds)
  nextHtml = annotateImportedImages(nextHtml, usedIds)
  nextHtml = annotateImportedVideos(nextHtml, usedIds)
  nextHtml = annotateImportedBackgroundImages(nextHtml, usedIds)
  return nextHtml
}

function hasImportedEditId(attrsText = '', editId = '') {
  return getImportedEditableAttr(parseHtmlAttributes(attrsText), 'id') === editId
}

function getImportedEditTypeFromAttrs(attrsText = '') {
  return normalizeImportedEditableContentType(getImportedEditableAttr(parseHtmlAttributes(attrsText), 'type'))
}

const IMPORTED_HTML_VOID_TAGS = new Set([
  'area',
  'base',
  'br',
  'col',
  'embed',
  'hr',
  'img',
  'input',
  'link',
  'meta',
  'param',
  'source',
  'track',
  'wbr'
])

function isImportedHtmlSelfClosingTag(tagName = '', openingTag = '') {
  return IMPORTED_HTML_VOID_TAGS.has(cleanString(tagName).toLowerCase()) || /\/\s*>$/.test(openingTag)
}

function findImportedHtmlElementEnd(html = '', tagName = '', openEnd = 0) {
  const source = String(html || '')
  const tag = cleanString(tagName).toLowerCase()
  if (!tag) return -1

  const tagPattern = new RegExp(`<\\/?${escapeRegExp(tag)}\\b[^>]*>`, 'gi')
  tagPattern.lastIndex = openEnd

  let depth = 1
  let match
  while ((match = tagPattern.exec(source))) {
    const token = match[0] || ''
    if (/^<\s*\//.test(token)) {
      depth -= 1
      if (depth === 0) return tagPattern.lastIndex
      continue
    }

    if (!isImportedHtmlSelfClosingTag(tag, token)) {
      depth += 1
    }
  }

  return -1
}

function findImportedEditableElementById(html = '', editId = '', editType = '') {
  const source = String(html || '')
  if (!editId) return null

  const openingPattern = /<([a-z][\w:-]*)\b([^>]*)>/gi
  let match
  while ((match = openingPattern.exec(source))) {
    const tagName = match[1] || ''
    const attrsText = match[2] || ''
    if (!hasImportedEditId(attrsText, editId)) continue
    const currentEditType = getImportedEditTypeFromAttrs(attrsText)
    if (editType && currentEditType !== editType) continue

    const openingTag = match[0] || ''
    const start = match.index
    const openEnd = openingPattern.lastIndex
    const selfClosing = isImportedHtmlSelfClosingTag(tagName, openingTag)
    const end = selfClosing ? openEnd : findImportedHtmlElementEnd(source, tagName, openEnd)
    if (end < openEnd) continue

    return {
      attrsText,
      editType: currentEditType,
      openingTag,
      tagName,
      selfClosing,
      start,
      openEnd,
      end,
      html: source.slice(start, end)
    }
  }

  return null
}

function replaceImportedEditableElementById(html = '', editId = '', editType = '', buildReplacement = null) {
  const source = String(html || '')
  if (!editId || !editType || typeof buildReplacement !== 'function') {
    return { html: source, updated: false }
  }

  const target = findImportedEditableElementById(source, editId, editType)
  if (!target) return { html: source, updated: false }

  const replacement = buildReplacement(target)
  if (typeof replacement !== 'string' || !replacement) {
    return { html: source, updated: false }
  }

  return {
    html: `${source.slice(0, target.start)}${replacement}${source.slice(target.end)}`,
    updated: true
  }
}

function setHtmlAttribute(openingTag = '', _attrsText = '', attrName = '', value = '') {
  const escapedValue = escapeHtml(value)
  const attrPattern = new RegExp(`(\\s${escapeRegExp(attrName)}\\s*=\\s*)("[^"]*"|'[^']*'|[^\\s>]+)`, 'i')
  if (attrPattern.test(openingTag)) {
    return openingTag.replace(attrPattern, (_match, prefix) => `${prefix}"${escapedValue}"`)
  }

  const insertAt = openingTag.endsWith('/>') ? openingTag.length - 2 : openingTag.length - 1
  const spacer = openingTag[insertAt - 1] === ' ' ? '' : ' '
  return `${openingTag.slice(0, insertAt)}${spacer}${attrName}="${escapedValue}"${openingTag.slice(insertAt)}`
}

function removeHtmlAttribute(openingTag = '', attrName = '') {
  if (!attrName) return openingTag
  const attrPattern = new RegExp(`\\s${escapeRegExp(attrName)}(?:\\s*=\\s*(?:"[^"]*"|'[^']*'|[^\\s>]+))?`, 'i')
  return String(openingTag || '').replace(attrPattern, '')
}

function setImportedFieldRequiredAttributes(openingTag = '', attrsText = '', required = true) {
  let nextTag = setHtmlAttribute(openingTag, attrsText, 'data-rstk-field-required', required ? 'true' : 'false')
  nextTag = setHtmlAttribute(nextTag, attrsText, 'aria-required', required ? 'true' : 'false')
  return required
    ? setHtmlAttribute(removeHtmlAttribute(nextTag, 'required'), attrsText, 'required', 'required')
    : removeHtmlAttribute(nextTag, 'required')
}

function setImportedDefaultFieldRequired(openingTag = '', attrsText = '') {
  return setImportedFieldRequiredAttributes(openingTag, attrsText, getImportedFieldRequiredFromAttrs(parseHtmlAttributes(attrsText)))
}

function normalizeImportedEditableImageUrl(value = '') {
  const raw = cleanString(value)
  if (!raw) {
    const error = new Error('La URL de la imagen está vacía')
    error.status = 400
    throw error
  }
  if (raw.startsWith('/')) return raw
  const absoluteUrl = safeUrl(raw)
  if (absoluteUrl) return absoluteUrl
  const error = new Error('Usa una URL completa de imagen con http o https')
  error.status = 400
  throw error
}

function setStyleBackgroundUrl(style = '', url = '') {
  const nextUrl = normalizeImportedEditableImageUrl(url)
  const safeBackground = `url("${nextUrl.replace(/"/g, '%22')}")`
  if (/url\s*\(/i.test(style)) {
    return String(style || '').replace(/url\s*\(\s*(?:"[^"]*"|'[^']*'|[^)]*)\s*\)/i, safeBackground)
  }
  const prefix = cleanString(style).replace(/;?\s*$/, '')
  return `${prefix}${prefix ? '; ' : ''}background-image: ${safeBackground}`
}

function normalizeImportedTextFontSizePx(input = {}) {
  const raw = input.fontSizePx ?? input.font_size_px ?? input.fontSize ?? input.font_size
  if (raw === undefined || raw === null || raw === '') return null
  const parsed = Number.parseFloat(String(raw).replace(/px$/i, ''))
  if (!Number.isFinite(parsed)) return null
  return Math.min(96, Math.max(10, Math.round(parsed)))
}

function setInlineStyleDeclaration(styleValue = '', property = '', value = '') {
  if (!property) return styleValue
  const declarationPattern = new RegExp(`\\s*${escapeRegExp(property)}\\s*:\\s*[^;]+;?`, 'ig')
  const withoutDeclaration = String(styleValue || '')
    .replace(declarationPattern, '')
    .replace(/;+\s*$/g, '')
    .trim()
  const cleanValue = cleanString(value)
  return [withoutDeclaration, cleanValue ? `${property}: ${cleanValue}` : '']
    .filter(Boolean)
    .join('; ')
}

function setImportedTextFontSizeAttribute(openingTag = '', attrsText = '', input = {}) {
  const fontSizePx = normalizeImportedTextFontSizePx(input)
  if (!fontSizePx) return openingTag
  const attrs = parseHtmlAttributes(attrsText)
  return setHtmlAttribute(
    openingTag,
    attrsText,
    'style',
    setInlineStyleDeclaration(attrs.style || '', 'font-size', `${fontSizePx}px`)
  )
}

function getWistiaMediaIdFromValue(value = '') {
  const raw = decodeHtmlAttribute(cleanString(value))
  if (!raw) return ''

  const patterns = [
    /(?:media-id|data-media-id)\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/i,
    /(?:hashedId|mediaId)\s*[:=]\s*(?:"([^"]+)"|'([^']+)'|([a-z0-9]+))/i,
    /wistia_async_([a-z0-9]+)/i,
    /fast\.wistia\.(?:com|net)\/embed\/([a-z0-9]+)\.js/i,
    /(?:fast\.)?wistia\.(?:com|net)\/embed\/iframe\/([a-z0-9]+)/i,
    /(?:fast\.)?wistia\.(?:com|net)\/embed\/medias\/([a-z0-9]+)\/swatch/i,
    /wistia\.com\/medias\/([a-z0-9]+)/i
  ]

  for (const pattern of patterns) {
    const match = raw.match(pattern)
    const mediaId = cleanString(match?.[1] || match?.[2] || match?.[3] || '')
    if (/^[a-z0-9]+$/i.test(mediaId)) return mediaId
  }
  return ''
}

function buildWistiaIframeUrl(mediaId = '') {
  return `https://fast.wistia.net/embed/iframe/${encodeURIComponent(mediaId)}`
}

function getImportedVideoValueSource(value = '') {
  const raw = decodeHtmlAttribute(cleanString(value))
  if (!raw) return { raw: '', candidate: '', title: 'Video', allow: DEFAULT_EMBED_ALLOW }

  const iframeTag = raw.match(/<iframe\b[\s\S]*?>/i)?.[0] || ''
  if (iframeTag) {
    return {
      raw,
      candidate: getIframeAttribute(iframeTag, 'src'),
      title: getIframeAttribute(iframeTag, 'title') || 'Video',
      allow: getIframeAttribute(iframeTag, 'allow') || DEFAULT_EMBED_ALLOW
    }
  }

  const videoTag = raw.match(/<video\b[\s\S]*?>/i)?.[0] || ''
  if (videoTag) {
    const sourceMatch = raw.match(/<source\b[^>]*\ssrc\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i)
    return {
      raw,
      candidate: getIframeAttribute(videoTag, 'src') || sourceMatch?.[1] || sourceMatch?.[2] || sourceMatch?.[3] || '',
      title: 'Video',
      allow: DEFAULT_EMBED_ALLOW
    }
  }

  const wistiaMediaId = getWistiaMediaIdFromValue(raw)
  if (wistiaMediaId) {
    return {
      raw,
      candidate: buildWistiaIframeUrl(wistiaMediaId),
      title: 'Video personalizado',
      allow: DEFAULT_EMBED_ALLOW
    }
  }

  return {
    raw,
    candidate: raw,
    title: 'Video',
    allow: DEFAULT_EMBED_ALLOW
  }
}

function normalizeImportedVideoEmbed(value = '') {
  const source = getImportedVideoValueSource(value)
  if (!source.candidate) {
    const error = new Error('Pega una URL o código embed de video.')
    error.status = 400
    throw error
  }

  const rawWistiaId = getWistiaMediaIdFromValue(`${source.raw} ${source.candidate}`)
  if (rawWistiaId) {
    return { kind: 'iframe', src: buildWistiaIframeUrl(rawWistiaId), title: source.title || 'Video personalizado', allow: source.allow }
  }

  const safeCandidate = safeEmbedUrl(source.candidate)
  if (!safeCandidate) {
    const error = new Error('Usa una URL de video con http o https, o un iframe válido.')
    error.status = 400
    throw error
  }

  try {
    const parsed = new URL(safeCandidate)
    const host = parsed.hostname.replace(/^www\./i, '').toLowerCase()
    const pathParts = parsed.pathname.split('/').filter(Boolean)
    const directVideo = IMPORTED_DIRECT_VIDEO_PATTERN.test(parsed.pathname)
    if (directVideo) {
      return { kind: 'video', src: parsed.toString(), title: source.title, allow: source.allow }
    }

    if (host === 'youtu.be' && pathParts[0]) {
      return { kind: 'iframe', src: `https://www.youtube.com/embed/${encodeURIComponent(pathParts[0])}`, title: source.title || 'YouTube', allow: source.allow }
    }

    if (host.endsWith('youtube.com') || host.endsWith('youtube-nocookie.com')) {
      const videoId = parsed.searchParams.get('v') || (pathParts[0] === 'shorts' ? pathParts[1] : '') || (pathParts[0] === 'embed' ? pathParts[1] : '')
      if (videoId) {
        return { kind: 'iframe', src: `https://www.youtube.com/embed/${encodeURIComponent(videoId)}`, title: source.title || 'YouTube', allow: source.allow }
      }
    }

    if (host.endsWith('vimeo.com')) {
      const videoId = pathParts[0] === 'video' ? pathParts[1] : pathParts[0]
      if (videoId && /^\d+$/.test(videoId)) {
        return { kind: 'iframe', src: `https://player.vimeo.com/video/${encodeURIComponent(videoId)}`, title: source.title || 'Vimeo', allow: source.allow }
      }
    }

    const wistiaId = getWistiaMediaIdFromValue(`${source.raw} ${parsed.toString()}`) ||
      (host.endsWith('wistia.com') || host.endsWith('wistia.net') ? pathParts[pathParts.length - 1] : '')
    if (wistiaId && /^[a-z0-9]+$/i.test(wistiaId)) {
      return { kind: 'iframe', src: buildWistiaIframeUrl(wistiaId), title: source.title || 'Video personalizado', allow: source.allow }
    }

    if (host.endsWith('loom.com')) {
      const videoId = pathParts[0] === 'embed' ? pathParts[1] : pathParts[0] === 'share' ? pathParts[1] : ''
      if (videoId) {
        return { kind: 'iframe', src: `https://www.loom.com/embed/${encodeURIComponent(videoId)}`, title: source.title || 'Loom', allow: source.allow }
      }
    }

    return { kind: 'iframe', src: parsed.toString(), title: source.title, allow: source.allow }
  } catch {
    const error = new Error('No pudimos leer esa URL de video.')
    error.status = 400
    throw error
  }
}

function buildImportedVideoMediaMarkup(value = '') {
  const video = normalizeImportedVideoEmbed(value)
  if (video.kind === 'video') {
    return `<video src="${escapeHtml(video.src)}" controls playsinline preload="metadata" style="width:100%;height:100%;min-height:220px;aspect-ratio:16/9;display:block;background:#000;border:0;border-radius:inherit;object-fit:cover;"></video>`
  }
  return `<iframe src="${escapeHtml(video.src)}" title="${escapeHtml(video.title || 'Video')}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" sandbox="${EMBED_SANDBOX_URL}" allow="${escapeHtml(video.allow || DEFAULT_EMBED_ALLOW)}" allowfullscreen style="width:100%;height:100%;min-height:220px;aspect-ratio:16/9;display:block;background:#000;border:0;border-radius:inherit;"></iframe>`
}

function parseImportedVideoSettingsValue(value) {
  if (!value) return {}
  if (typeof value === 'object' && !Array.isArray(value)) return value
  if (typeof value !== 'string') return {}
  try {
    const parsed = JSON.parse(value)
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}
  } catch {
    return {}
  }
}

function normalizeImportedVideoSettings(settings = {}, mediaUrl = '') {
  const nextSettings = settings && typeof settings === 'object' && !Array.isArray(settings) ? { ...settings } : {}
  const cleanMediaUrl = cleanString(mediaUrl || nextSettings.mediaUrl)
  if (cleanMediaUrl) nextSettings.mediaUrl = cleanMediaUrl
  return nextSettings
}

function getImportedVideoSettingsFromAttrs(attrsText = '', mediaUrl = '') {
  const attrs = parseHtmlAttributes(attrsText)
  const rawSettings = attrs['data-rstk-video-settings'] ||
    attrs['data-ristak-video-settings'] ||
    attrs['data-ristack-video-settings'] ||
    ''
  const sourceUrl = mediaUrl || attrs['data-rstk-video-url'] || attrs['data-ristak-video-url'] || attrs['data-rstk-video-embed'] || ''
  return normalizeImportedVideoSettings(parseImportedVideoSettingsValue(rawSettings), sourceUrl)
}

function getImportedVideoSettingsForUpdate(input = {}, attrsText = '', mediaUrl = '') {
  const rawInputSettings = Object.prototype.hasOwnProperty.call(input, 'videoSettings')
    ? input.videoSettings
    : Object.prototype.hasOwnProperty.call(input, 'video_settings')
      ? input.video_settings
      : null
  const sourceSettings = rawInputSettings !== null
    ? parseImportedVideoSettingsValue(rawInputSettings)
    : getImportedVideoSettingsFromAttrs(attrsText, mediaUrl)
  return normalizeImportedVideoSettings(sourceSettings, mediaUrl)
}

function setImportedVideoSettingsAttributes(openingTag = '', attrsText = '', input = {}, value = '') {
  const videoSource = normalizeImportedVideoEmbed(value).src
  let nextTag = setHtmlAttribute(openingTag, attrsText, 'data-rstk-video-url', videoSource)
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-video-settings', jsonString(getImportedVideoSettingsForUpdate(input, attrsText, videoSource)))
  return nextTag
}

function buildImportedVideoReplacement(value = '', attrsText = '', editId = '', input = {}) {
  const attrs = parseHtmlAttributes(attrsText)
  const label = getImportedElementLabel('video', attrs, 'Video')
  const videoSource = normalizeImportedVideoEmbed(value).src
  const videoSettings = getImportedVideoSettingsForUpdate(input, attrsText, videoSource)
  return `<div class="rstk-imported-video-slot" data-rstk-editable="true" data-rstk-edit-type="video" data-rstk-label="${escapeHtml(label)}" data-rstk-edit-id="${escapeHtml(editId)}" data-rstk-video-url="${escapeHtml(videoSource)}" data-rstk-video-settings="${escapeHtml(jsonString(videoSettings))}" style="width:100%;aspect-ratio:16/9;min-height:220px;overflow:hidden;background:#000;border-radius:inherit;">${buildImportedVideoMediaMarkup(value)}</div>`
}

function getImportedEditableTextValue(input = {}) {
  const value = limitString(String(input.value ?? input.text ?? input.url ?? ''), 5000).trim()
  if (!value) {
    const error = new Error('El contenido nuevo esta vacio')
    error.status = 400
    throw error
  }
  return value
}

const IMPORTED_BUTTON_ACTIONS = new Set([
  'none',
  'url',
  'next_page',
  'specific_page',
  'open_popup',
  'close_popup',
  'submit',
  'disqualify',
  'disqualify_after_submit',
  'automation',
  'notify_team',
  'add_tag',
  'send_whatsapp',
  'create_payment'
])

function normalizeImportedButtonAction(value = '') {
  const action = cleanString(value).toLowerCase().replace(/[-\s]+/g, '_')
  return IMPORTED_BUTTON_ACTIONS.has(action) ? action : ''
}

function hasImportedButtonActionPatch(input = {}) {
  return [
    input.buttonActions,
    input.button_actions,
    input.buttonAction,
    input.button_action,
    input.buttonUrl,
    input.button_url,
    input.buttonPageId,
    input.button_page_id,
    input.buttonMessage,
    input.button_message
  ].some(value => value !== undefined)
}

function normalizeImportedActionStep(input = {}, index = 0) {
  const source = input && typeof input === 'object' ? input : {}
  const action = normalizeImportedButtonAction(source.action || source.buttonAction || source.button_action || source.type)
  if (!action || action === 'none') return null

  const buttonUrl = cleanString(source.buttonUrl || source.button_url || source.url)
  const buttonPageId = cleanString(source.buttonPageId || source.button_page_id || source.pageId || source.page_id)
  const buttonMessage = limitString(cleanString(source.buttonMessage || source.button_message || source.message), 500)
  const rawDisqualifyOutcome = cleanString(source.disqualifyOutcome || source.disqualify_outcome).toLowerCase()
  const disqualifyOutcome = action === 'disqualify'
    ? ['message', 'specific_page', 'url'].includes(rawDisqualifyOutcome)
      ? rawDisqualifyOutcome
      : buttonPageId
        ? 'specific_page'
        : buttonUrl
          ? 'url'
          : 'message'
    : ''
  const automationName = limitString(cleanString(source.automationName || source.automation_name || source.automation || source.label), 140)
  const warnBeforeDisqualify = normalizeBoolean(source.warnBeforeDisqualify ?? source.warn_before_disqualify)
  const disqualifyNoticeMessage = limitString(cleanString(source.disqualifyNoticeMessage || source.disqualify_notice_message), 300)

  if (action === 'url' && !safeHref(buttonUrl, '')) {
    const error = new Error('Usa una URL válida para el botón')
    error.status = 400
    throw error
  }

  if (action === 'specific_page' && !buttonPageId) {
    const error = new Error('Selecciona la página destino del botón')
    error.status = 400
    throw error
  }

  if (action === 'disqualify' && disqualifyOutcome === 'specific_page' && !buttonPageId) {
    const error = new Error('Selecciona la página para contactos no calificados')
    error.status = 400
    throw error
  }

  if (action === 'disqualify' && disqualifyOutcome === 'url' && !safeHref(buttonUrl, '')) {
    const error = new Error('Usa una URL válida para contactos no calificados')
    error.status = 400
    throw error
  }

  return {
    id: cleanString(source.id) || `action-${index + 1}`,
    action,
    buttonUrl,
    buttonPageId,
    buttonMessage,
    ...(disqualifyOutcome ? { disqualifyOutcome } : {}),
    automationName,
    warnBeforeDisqualify,
    disqualifyNoticeMessage
  }
}

function normalizeImportedActionSteps(input = {}) {
  const rawActions = Array.isArray(input.buttonActions)
    ? input.buttonActions
    : Array.isArray(input.button_actions)
      ? input.button_actions
      : null

  if (rawActions) {
    const usedActions = new Set()
    return rawActions
      .map((item, index) => normalizeImportedActionStep(item, index))
      .filter(Boolean)
      .filter(step => {
        if (usedActions.has(step.action)) return false
        usedActions.add(step.action)
        return true
      })
      .slice(0, 8)
  }

  const legacyAction = normalizeImportedButtonAction(input.buttonAction || input.button_action || 'none')
  if (!legacyAction || legacyAction === 'none') return []
  return [normalizeImportedActionStep({
    id: 'action-1',
    action: legacyAction,
    buttonUrl: input.buttonUrl || input.button_url,
    buttonPageId: input.buttonPageId || input.button_page_id,
    buttonMessage: input.buttonMessage || input.button_message
  }, 0)].filter(Boolean)
}

function getImportedButtonActionPatch(input = {}) {
  if (!hasImportedButtonActionPatch(input)) return null

  const actions = normalizeImportedActionSteps(input)
  const primary = actions[0] || { action: 'none', buttonUrl: '', buttonPageId: '', buttonMessage: '', automationName: '' }

  return {
    ...primary,
    actions
  }
}

function getImportedPageHref(pageId = '') {
  const cleanPageId = cleanString(pageId)
  return cleanPageId ? `?page=${encodeURIComponent(cleanPageId)}` : '#'
}

function setImportedButtonActionAttributes(openingTag = '', attrsText = '', patch = null) {
  if (!patch) return openingTag

  let nextTag = openingTag
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-button-action', patch.action)
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-button-actions', jsonString(patch.actions || []))
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-button-url', patch.action === 'url' ? safeHref(patch.buttonUrl, '') : '')
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-button-page-id', ['specific_page', 'disqualify'].includes(patch.action) ? patch.buttonPageId : '')
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-button-message', patch.action === 'disqualify' ? patch.buttonMessage : '')

  const tagName = cleanString((nextTag.match(/^<\s*([a-z][\w:-]*)/i) || [])[1]).toLowerCase()
  if (tagName === 'a') {
    if (patch.action === 'url') return setHtmlAttribute(nextTag, attrsText, 'href', safeHref(patch.buttonUrl, '#'))
    if (patch.action === 'specific_page') return setHtmlAttribute(nextTag, attrsText, 'href', getImportedPageHref(patch.buttonPageId))
    return setHtmlAttribute(nextTag, attrsText, 'href', '#')
  }

  if (tagName === 'button' || tagName === 'input') {
    const buttonType = patch.action === 'submit' ? 'submit' : 'button'
    nextTag = setHtmlAttribute(nextTag, attrsText, 'type', buttonType)
  }

  return nextTag
}

function getImportedChoiceActionPatch(input = {}) {
  const rawActions = Array.isArray(input.choiceActions)
    ? input.choiceActions
    : Array.isArray(input.choice_actions)
      ? input.choice_actions
      : []

  const usedActions = new Set()

  return {
    actions: rawActions
      .map((item, index) => normalizeImportedActionStep(item, index))
      .filter(Boolean)
      .filter(step => {
        if (usedActions.has(step.action)) return false
        usedActions.add(step.action)
        return true
      })
      .slice(0, 8),
    choiceName: cleanString(input.choiceName || input.choice_name),
    choiceValue: cleanString(input.choiceValue || input.choice_value),
    choiceInputType: ['radio', 'checkbox'].includes(cleanString(input.choiceInputType || input.choice_input_type).toLowerCase())
      ? cleanString(input.choiceInputType || input.choice_input_type).toLowerCase()
      : '',
    choiceIndex: Number.isFinite(Number(input.choiceIndex ?? input.choice_index))
      ? Math.max(0, Number(input.choiceIndex ?? input.choice_index))
      : null
  }
}

function getImportedChoiceKey(attrs = {}) {
  return cleanString(attrs.name || attrs.id || attrs.value || 'choice')
}

function setImportedChoiceActionAttributes(openingTag = '', attrsText = '', patch = null, editId = '') {
  if (!patch) return openingTag
  let nextTag = openingTag
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-choice-id', editId)
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-choice-actions', jsonString(patch.actions || []))
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-choice-name', patch.choiceName)
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-choice-value', patch.choiceValue)
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-editable', 'true')
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-edit-type', 'choice_option')
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-edit-id', editId)
  return nextTag
}

function getImportedFormFieldPatch(input = {}, value = '') {
  return {
    label: limitString(stripHtmlTags(input.fieldLabel || input.field_label || value), 160),
    placeholder: limitString(cleanString(input.fieldPlaceholder || input.field_placeholder), 200),
    required: Boolean(normalizeBoolean(input.fieldRequired ?? input.field_required ?? true)),
    options: normalizeImportedFieldOptions(input.fieldOptions || input.field_options || []),
    fieldName: cleanString(input.fieldName || input.field_name),
    fieldHtmlId: cleanString(input.fieldHtmlId || input.field_html_id),
    fieldTag: cleanString(input.fieldTag || input.field_tag).toLowerCase(),
    fieldInputType: cleanString(input.fieldInputType || input.field_input_type).toLowerCase()
  }
}

function importedFormFieldMatches(attrsText = '', editId = '', patch = {}) {
  const attrs = parseHtmlAttributes(attrsText)
  if (hasImportedEditId(attrsText, editId)) return true

  const attrName = cleanString(attrs.name)
  const attrId = cleanString(attrs.id)
  if (patch.fieldHtmlId && attrId === patch.fieldHtmlId) return true
  if (patch.fieldName && [attrName, attrId].includes(patch.fieldName)) return true

  return false
}

function setImportedFormFieldTagAttributes(openingTag = '', attrsText = '', patch = null) {
  if (!patch) return openingTag
  let nextTag = openingTag
  if (patch.placeholder) nextTag = setHtmlAttribute(nextTag, attrsText, 'placeholder', patch.placeholder)
  nextTag = setHtmlAttribute(nextTag, attrsText, 'data-rstk-label', patch.label || patch.placeholder || patch.fieldName || 'Campo')
  nextTag = setImportedFieldRequiredAttributes(nextTag, attrsText, patch.required)
  return nextTag
}

function buildImportedSelectOptions(options = [], existingBody = '') {
  const normalizedOptions = normalizeImportedFieldOptions(options)
  if (!normalizedOptions.length) return existingBody

  const firstOptionMatch = String(existingBody || '').match(/<option\b([^>]*)>([\s\S]*?)<\/option>/i)
  const firstOptionAttrs = firstOptionMatch ? parseHtmlAttributes(firstOptionMatch[1] || '') : {}
  const firstOptionValue = cleanString(firstOptionAttrs.value || stripHtmlTags(firstOptionMatch?.[2] || ''))
  const keepsEmptyOption = firstOptionMatch && !firstOptionValue
  const emptyOption = keepsEmptyOption
    ? firstOptionMatch[0]
    : '<option value="">Selecciona una opción</option>'

  return [
    emptyOption,
    ...normalizedOptions.map(option => {
      const optionActions = Array.isArray(option.actions) && option.actions.length
        ? ` data-rstk-choice-actions="${escapeHtml(jsonString(option.actions))}"`
        : ''
      return `<option value="${escapeHtml(option.value)}"${optionActions}>${escapeHtml(option.label)}</option>`
    })
  ].join('\n')
}

function buildImportedChoiceGroupHtml({ type = 'radio', name = '', options = [], required = true, editId = '', labelAttrs = '' } = {}) {
  const normalizedOptions = normalizeImportedFieldOptions(options)
  if (!normalizedOptions.length || !name) return ''
  const cleanType = ['radio', 'checkbox'].includes(type) ? type : 'radio'
  const cleanName = cleanString(name)
  const baseAttrs = cleanString(labelAttrs)

  return normalizedOptions.map((option, index) => {
    const optionId = `${normalizeImportedFieldKey(cleanName, 'field')}_${index + 1}`
    const inputRequired = required && index === 0 ? ' required="required" aria-required="true" data-rstk-field-required="true"' : ` aria-required="${required ? 'true' : 'false'}" data-rstk-field-required="${required ? 'true' : 'false'}"`
    const optionEditId = `${editId || cleanName}_${index + 1}`
    const optionActions = Array.isArray(option.actions) && option.actions.length
      ? ` data-rstk-choice-actions="${escapeHtml(jsonString(option.actions))}"`
      : ''
    return `<label${baseAttrs ? ` ${baseAttrs}` : ''}><input type="${cleanType}" name="${escapeHtml(cleanName)}" id="${escapeHtml(optionId)}" value="${escapeHtml(option.value)}"${inputRequired} data-rstk-editable="true" data-rstk-edit-type="form_field" data-rstk-edit-id="${escapeHtml(optionEditId)}" data-rstk-label="${escapeHtml(option.label)}"${optionActions}> ${escapeHtml(option.label)}</label>`
  }).join('\n')
}

function replaceImportedChoiceFieldGroup(html = '', editId = '', patch = null) {
  if (!patch || !['radio', 'checkbox'].includes(patch.fieldInputType) || !patch.options.length) {
    return { html, updated: false }
  }

  const matches = []
  const inputPattern = /<input\b([^>]*?)\s*(\/?)>/gi
  let match
  while ((match = inputPattern.exec(String(html || '')))) {
    const attrsText = match[1] || ''
    const attrs = parseHtmlAttributes(attrsText)
    const type = cleanString(attrs.type || 'text').toLowerCase()
    if (type !== patch.fieldInputType) continue
    if (!importedFormFieldMatches(attrsText, editId, patch)) continue
    matches.push({ index: match.index, end: inputPattern.lastIndex, attrs, attrsText })
  }

  if (!matches.length) return { html, updated: false }

  const groupName = patch.fieldName || cleanString(matches[0].attrs.name || matches[0].attrs.id)
  const groupMatches = []
  inputPattern.lastIndex = 0
  while ((match = inputPattern.exec(String(html || '')))) {
    const attrsText = match[1] || ''
    const attrs = parseHtmlAttributes(attrsText)
    const type = cleanString(attrs.type || 'text').toLowerCase()
    const sameGroup = type === patch.fieldInputType && cleanString(attrs.name || attrs.id) === groupName
    if (sameGroup) groupMatches.push({ index: match.index, end: inputPattern.lastIndex, attrs, attrsText })
  }

  const targetMatches = groupMatches.length ? groupMatches : matches
  const ranges = targetMatches.map(item => {
    const before = String(html || '').slice(0, item.index)
    const labelStart = before.lastIndexOf('<label')
    const previousLabelEnd = before.lastIndexOf('</label>')
    const labelEnd = String(html || '').indexOf('</label>', item.end)
    if (labelStart !== -1 && labelStart > previousLabelEnd && labelEnd !== -1) {
      return {
        start: labelStart,
        end: labelEnd + '</label>'.length,
        labelAttrs: (String(html || '').slice(labelStart).match(/^<label\b([^>]*)>/i) || [])[1] || ''
      }
    }
    return { start: item.index, end: item.end, labelAttrs: '' }
  })

  const start = Math.min(...ranges.map(range => range.start))
  const end = Math.max(...ranges.map(range => range.end))
  const labelAttrs = ranges.find(range => cleanString(range.labelAttrs))?.labelAttrs || ''
  const replacement = buildImportedChoiceGroupHtml({
    type: patch.fieldInputType,
    name: groupName,
    options: patch.options,
    required: patch.required,
    editId,
    labelAttrs
  })

  if (!replacement) return { html, updated: false }

  return {
    html: `${String(html || '').slice(0, start)}${replacement}${String(html || '').slice(end)}`,
    updated: true
  }
}

function replaceImportedLabelForField(html = '', fieldId = '', label = '') {
  const cleanFieldId = cleanString(fieldId)
  const cleanLabel = limitString(stripHtmlTags(label), 160)
  if (!cleanFieldId || !cleanLabel) return html
  const escapedId = escapeRegExp(cleanFieldId)
  const labelPattern = new RegExp(`(<label\\b[^>]*\\bfor\\s*=\\s*(?:"${escapedId}"|'${escapedId}'|${escapedId})[^>]*>)([\\s\\S]*?)(<\\/label>)`, 'i')
  return String(html || '').replace(labelPattern, (_match, openTag, _inner, closeTag) => `${openTag}${escapeHtml(cleanLabel)}${closeTag}`)
}

function applyImportedEditableContentUpdate(html = '', input = {}) {
  const editId = cleanString(input.editId || input.edit_id)
  const editType = normalizeImportedEditableContentType(input.editType || input.edit_type)
  const value = getImportedEditableTextValue(input)
  const buttonActionPatch = editType === 'button' ? getImportedButtonActionPatch(input) : null
  const choiceActionPatch = editType === 'choice_option' ? getImportedChoiceActionPatch(input) : null
  const formFieldPatch = editType === 'form_field' ? getImportedFormFieldPatch(input, value) : null

  if (!editId || !editType) {
    const error = new Error('Selección inválida para editar contenido')
    error.status = 400
    throw error
  }

  let updated = false
  let nextHtml = annotateImportedEditableHtml(html)

  if (editType === 'image') {
    const imageUrl = normalizeImportedEditableImageUrl(value)
    nextHtml = nextHtml.replace(/<img\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'image') return match
      updated = true
      return setHtmlAttribute(match, attrsText, 'src', imageUrl)
    })
  } else if (editType === 'background_image') {
    nextHtml = nextHtml.replace(/<([a-z][\w:-]*)\b([^>]*)>/gi, (match, _tagName, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'background_image') return match
      const attrs = parseHtmlAttributes(attrsText)
      updated = true
      return setHtmlAttribute(match, attrsText, 'style', setStyleBackgroundUrl(attrs.style || '', value))
    })
  } else if (editType === 'video') {
    const mediaMarkup = buildImportedVideoMediaMarkup(value)
    const preciseVideoUpdate = replaceImportedEditableElementById(nextHtml, editId, 'video', ({
      attrsText,
      openingTag,
      tagName,
      selfClosing
    }) => {
      const tag = cleanString(tagName).toLowerCase()
      if (selfClosing || ['iframe', 'video', 'object', 'embed', 'wistia-player'].includes(tag)) {
        return buildImportedVideoReplacement(value, attrsText, editId, input)
      }

      const openingTagWithSource = setImportedVideoSettingsAttributes(openingTag, attrsText, input, value)
      return `${openingTagWithSource}${mediaMarkup}</${tagName}>`
    })
    if (preciseVideoUpdate.updated) {
      updated = true
      nextHtml = preciseVideoUpdate.html
    }
    nextHtml = nextHtml.replace(/<(iframe|video|object)\b([^>]*)>[\s\S]*?<\/\1>/gi, (match, _tagName, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'video') return match
      updated = true
      return buildImportedVideoReplacement(value, attrsText, editId, input)
    })
    nextHtml = nextHtml.replace(/<embed\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'video') return match
      updated = true
      return buildImportedVideoReplacement(value, attrsText, editId, input)
    })
    nextHtml = nextHtml.replace(/<wistia-player\b([^>]*)>[\s\S]*?<\/wistia-player>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'video') return match
      updated = true
      return buildImportedVideoReplacement(value, attrsText, editId, input)
    })
    nextHtml = nextHtml.replace(/<wistia-player\b([^>]*?)\s*\/>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'video') return match
      updated = true
      return buildImportedVideoReplacement(value, attrsText, editId, input)
    })
    nextHtml = nextHtml.replace(/<(div|section|article|figure|aside)\b([^>]*)>([\s\S]*?)<\/\1>/gi, (match, tagName, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'video') return match
      updated = true
      const openingTag = setImportedVideoSettingsAttributes(`<${tagName}${attrsText}>`, attrsText, input, value)
      return `${openingTag}${mediaMarkup}</${tagName}>`
    })
  } else if (editType === 'placeholder') {
    nextHtml = nextHtml.replace(/<input\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'placeholder') return match
      updated = true
      return setHtmlAttribute(match, attrsText, 'placeholder', value)
    })
    nextHtml = nextHtml.replace(/<textarea\b([^>]*)>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'placeholder') return match
      updated = true
      return setHtmlAttribute(match, attrsText, 'placeholder', value)
    })
  } else if (editType === 'form_field') {
    let fieldHtmlId = formFieldPatch?.fieldHtmlId || ''
    const choiceGroupUpdate = replaceImportedChoiceFieldGroup(nextHtml, editId, formFieldPatch)
    if (choiceGroupUpdate.updated) {
      updated = true
      nextHtml = choiceGroupUpdate.html
    }
    nextHtml = nextHtml.replace(/<select\b([^>]*)>([\s\S]*?)<\/select>/gi, (match, attrsText = '', innerHtml = '') => {
      if (updated || !importedFormFieldMatches(attrsText, editId, formFieldPatch)) return match
      updated = true
      const attrs = parseHtmlAttributes(attrsText)
      fieldHtmlId = fieldHtmlId || cleanString(attrs.id)
      const openingTag = setImportedFormFieldTagAttributes(`<select${attrsText}>`, attrsText, formFieldPatch)
      return `${openingTag}${buildImportedSelectOptions(formFieldPatch?.options || [], innerHtml)}</select>`
    })
    nextHtml = nextHtml.replace(/<textarea\b([^>]*)>([\s\S]*?)<\/textarea>/gi, (match, attrsText = '', innerHtml = '') => {
      if (updated || !importedFormFieldMatches(attrsText, editId, formFieldPatch)) return match
      updated = true
      const attrs = parseHtmlAttributes(attrsText)
      fieldHtmlId = fieldHtmlId || cleanString(attrs.id)
      const openingTag = setImportedFormFieldTagAttributes(`<textarea${attrsText}>`, attrsText, formFieldPatch)
      return `${openingTag}${innerHtml}</textarea>`
    })
    nextHtml = nextHtml.replace(/<input\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '') => {
      if (updated || !importedFormFieldMatches(attrsText, editId, formFieldPatch)) return match
      const attrs = parseHtmlAttributes(attrsText)
      const type = cleanString(attrs.type || 'text').toLowerCase()
      if (['hidden', 'submit', 'button', 'reset', 'image'].includes(type)) return match
      updated = true
      fieldHtmlId = fieldHtmlId || cleanString(attrs.id)
      return setImportedFormFieldTagAttributes(match, attrsText, formFieldPatch)
    })
    if (updated) {
      nextHtml = replaceImportedLabelForField(nextHtml, fieldHtmlId, formFieldPatch?.label || value)
    }
  } else if (editType === 'button') {
    nextHtml = nextHtml.replace(/<input\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'button') return match
      updated = true
      const withValue = setHtmlAttribute(match, attrsText, 'value', value)
      return setImportedButtonActionAttributes(withValue, attrsText, buttonActionPatch)
    })
    nextHtml = nextHtml.replace(/<(button|a)\b([^>]*)>([\s\S]*?)<\/\1>/gi, (match, tagName, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId) || getImportedEditTypeFromAttrs(attrsText) !== 'button') return match
      updated = true
      const openingTag = setImportedButtonActionAttributes(`<${tagName}${attrsText}>`, attrsText, buttonActionPatch)
      return `${openingTag}${escapeHtml(value)}</${tagName}>`
    })
  } else if (editType === 'choice_option') {
    const fieldPatch = getImportedFormFieldPatch(input, value)
    const choiceGroupUpdate = fieldPatch.options.length && ['radio', 'checkbox'].includes(fieldPatch.fieldInputType)
      ? replaceImportedChoiceFieldGroup(nextHtml, editId, fieldPatch)
      : { html: nextHtml, updated: false }
    if (choiceGroupUpdate.updated) {
      nextHtml = choiceGroupUpdate.html
    }
    const choiceCounters = new Map()
    nextHtml = nextHtml.replace(/<input\b([^>]*?)\s*(\/?)>/gi, (match, attrsText = '') => {
      if (updated) return match
      const attrs = parseHtmlAttributes(attrsText)
      const type = cleanString(attrs.type || 'text').toLowerCase()
      if (!['radio', 'checkbox'].includes(type)) return match
      const key = `${type}:${getImportedChoiceKey(attrs)}`
      const currentIndex = choiceCounters.get(key) || 0
      choiceCounters.set(key, currentIndex + 1)
      const attrEditId = getImportedEditableAttr(attrs, 'id') || cleanString(attrs['data-rstk-choice-id'])
      const nameMatch = !choiceActionPatch?.choiceName || [attrs.name, attrs.id].map(cleanString).includes(choiceActionPatch.choiceName)
      const valueMatch = !choiceActionPatch?.choiceValue || cleanString(attrs.value) === choiceActionPatch.choiceValue
      const typeMatch = !choiceActionPatch?.choiceInputType || type === choiceActionPatch.choiceInputType
      const indexMatch = choiceActionPatch?.choiceIndex === null || currentIndex === choiceActionPatch?.choiceIndex
      if (attrEditId !== editId && !(nameMatch && valueMatch && typeMatch && indexMatch)) return match
      updated = true
      return setImportedChoiceActionAttributes(match, attrsText, choiceActionPatch, editId)
    })
  } else {
    nextHtml = nextHtml.replace(/<(h[1-6]|p|label|a|span|strong|em|small|li)\b([^>]*)>([\s\S]*?)<\/\1>/gi, (match, tagName, attrsText = '') => {
      if (updated || !hasImportedEditId(attrsText, editId)) return match
      const currentType = getImportedEditTypeFromAttrs(attrsText)
      if (currentType && currentType !== editType) return match
      updated = true
      const openingTag = setImportedTextFontSizeAttribute(`<${tagName}${attrsText}>`, attrsText, input)
      return `${openingTag}${escapeHtml(value)}</${tagName}>`
    })
    // Generic containers annotated as editable text (innermost match, see
    // annotateImportedSimpleTextContainers).
    if (!updated) {
      for (const tag of IMPORTED_SIMPLE_TEXT_CONTAINER_TAGS) {
        if (updated) break
        const pattern = new RegExp(`<${tag}\\b([^>]*)>((?:(?!<${tag}\\b|</${tag})[\\s\\S])*?)</${tag}>`, 'gi')
        nextHtml = nextHtml.replace(pattern, (match, attrsText = '') => {
          if (updated || !hasImportedEditId(attrsText, editId)) return match
          const currentType = getImportedEditTypeFromAttrs(attrsText)
          if (currentType && currentType !== editType) return match
          updated = true
          const openingTag = setImportedTextFontSizeAttribute(`<${tag}${attrsText}>`, attrsText, input)
          return `${openingTag}${escapeHtml(value)}</${tag}>`
        })
      }
    }
  }

  if (!updated) {
    const error = new Error('No encontramos ese elemento editable en la página')
    error.status = 404
    throw error
  }

  return nextHtml
}

function inferImportedFieldDestination(field = {}) {
  const explicit = normalizeImportedFieldKey(field.explicitField, '')
  const explicitCustom = normalizeImportedFieldKey(field.explicitCustomField, '')
  const haystack = getImportedFieldHaystack(field)
  const suppressAmbiguousName = hasImportedNameContextExclusion(field) && hasImportedAlias(haystack, IMPORTED_AMBIGUOUS_PERSON_NAME_ALIASES)

  if (explicitCustom) {
    return { destinationType: 'custom', destinationKey: explicitCustom, confidence: 0.98 }
  }

  if (explicit && IMPORTED_FORM_SYSTEM_FIELDS.has(explicit)) {
    return { destinationType: 'standard', destinationKey: explicit, confidence: 0.98 }
  }

  const explicitStandardAlias = explicit ? getImportedStandardAliasKey(explicit) : ''
  if (explicitStandardAlias) {
    if (explicitStandardAlias === IMPORTED_FORM_LEGACY_MESSAGE_FIELD_KEY) {
      return { destinationType: 'custom', destinationKey: IMPORTED_FORM_MESSAGE_CUSTOM_FIELD_KEY, confidence: 0.96 }
    }
    return { destinationType: 'standard', destinationKey: explicitStandardAlias, confidence: 0.96 }
  }

  if (explicit) {
    return { destinationType: 'custom', destinationKey: explicit, confidence: 0.94 }
  }

  if (field.type === 'email') {
    return { destinationType: 'standard', destinationKey: 'email', confidence: 0.92 }
  }

  if (field.type === 'tel') {
    return { destinationType: 'standard', destinationKey: 'phone', confidence: 0.9 }
  }

  const standardAlias = getImportedStandardAliasKey(haystack)
  if (standardAlias) {
    if (standardAlias === IMPORTED_FORM_LEGACY_MESSAGE_FIELD_KEY) {
      return { destinationType: 'custom', destinationKey: IMPORTED_FORM_MESSAGE_CUSTOM_FIELD_KEY, confidence: 0.9 }
    }
    if (suppressAmbiguousName && ['first_name', 'full_name'].includes(standardAlias)) {
      const customHint = getImportedCustomHintDestination(haystack)
      if (customHint) return customHint
      return {
        destinationType: 'custom',
        destinationKey: normalizeImportedFieldKey(field.label || field.placeholder || field.sourceName || field.name || field.id, 'custom_field'),
        confidence: 0.56
      }
    }

    const confidence = standardAlias === 'first_name' || standardAlias === 'last_name'
      ? 0.9
      : standardAlias === 'full_name'
        ? 0.84
        : 0.9
    return { destinationType: 'standard', destinationKey: standardAlias, confidence }
  }

  const contactCustom = getImportedCustomHintDestination(haystack, IMPORTED_CONTACT_CUSTOM_FIELD_KEYS)
  if (contactCustom) return contactCustom

  const customHint = getImportedCustomHintDestination(haystack)
  if (customHint) return customHint

  return {
    destinationType: 'custom',
    destinationKey: normalizeImportedFieldKey(field.name || field.label || field.placeholder || field.id, 'custom_field'),
    confidence: 0.45
  }
}

function buildDefaultImportedFormMappings(forms = []) {
  const formIdCounts = new Map()
  for (const form of Array.isArray(forms) ? forms : []) {
    const formId = normalizeImportedFieldKey(form?.id, '')
    if (formId) formIdCounts.set(formId, (formIdCounts.get(formId) || 0) + 1)
  }

  return forms.map(form => {
    const fields = form.fields.map(field => {
      const inferred = inferImportedFieldDestination(field)
      return {
        fieldId: field.id,
        sourceName: field.sourceName,
        hasStableFieldId: field.hasStableFieldId === true,
        label: field.label || field.placeholder || field.sourceName,
        type: field.type,
        destinationType: inferred.destinationType === 'custom' ? 'new_custom' : inferred.destinationType,
        destinationKey: inferred.destinationKey,
        saveMode: inferred.destinationType === 'standard' ? 'standard' : 'new_custom',
        confidence: inferred.confidence,
        ignored: false,
        present: true,
        options: field.options || []
      }
    })
    const hasLastName = fields.some(field => (
      field.destinationType === 'standard' &&
      field.destinationKey === 'last_name' &&
      !field.ignored
    ))
    const ambiguousPersonNameFields = fields.filter(isImportedAmbiguousMappedPersonNameField)
    const fieldIdCounts = new Map()
    for (const field of fields) {
      const fieldId = importedFieldMappingIdentity(field)
      if (fieldId) fieldIdCounts.set(fieldId, (fieldIdCounts.get(fieldId) || 0) + 1)
    }
    const duplicateFieldIds = new Set(
      [...fieldIdCounts.entries()].filter(([, count]) => count > 1).map(([fieldId]) => fieldId)
    )

    return {
      formId: form.id,
      formTitle: form.title,
      pagePath: cleanString(form.pagePath || form.page_path),
      hasStableFormId: form.hasStableFormId === true,
      ...(formIdCounts.get(normalizeImportedFieldKey(form.id, '')) > 1 ? { mappingAmbiguous: true } : {}),
      ...(duplicateFieldIds.size > 0 ? { fieldMappingAmbiguous: true } : {}),
      purpose: form.purpose || 'lead_capture',
      contactCaptureMode: normalizeImportedContactCaptureMode(
        form.contactCaptureMode || form.contact_capture_mode
      ),
      submitText: form.submitText || 'Enviar',
      present: true,
      fields: fields.map(mappedField => {
        if (duplicateFieldIds.has(importedFieldMappingIdentity(mappedField))) {
          return { ...mappedField, mappingAmbiguous: true }
        }
        const isOnlyAmbiguousPersonName = ambiguousPersonNameFields.length === 1 &&
          ambiguousPersonNameFields[0].fieldId === mappedField.fieldId

        if (
          isOnlyAmbiguousPersonName &&
          mappedField.destinationType === 'standard' &&
          ['first_name', 'full_name'].includes(mappedField.destinationKey)
        ) {
          return {
            ...mappedField,
            destinationKey: hasLastName ? 'first_name' : 'full_name',
            saveMode: 'standard',
            confidence: Math.max(Number(mappedField.confidence || 0), 0.9)
          }
        }

        return mappedField
      })
    }
  })
}

function countImportedDetectedFields(forms = []) {
  return forms.reduce((total, form) => total + (Array.isArray(form?.fields) ? form.fields.length : 0), 0)
}

function countImportedMappedFields(mappings = []) {
  return mappings.reduce((total, mapping) => (
    mapping?.present === false
      ? total
      : total + (Array.isArray(mapping?.fields) ? mapping.fields.filter(field => field?.present !== false).length : 0)
  ), 0)
}

function hasImportedExplodedChoiceGroups(forms = []) {
  return (Array.isArray(forms) ? forms : []).some(form => {
    if (form?.present === false) return false
    const counts = new Map()
    for (const field of Array.isArray(form?.fields) ? form.fields : []) {
      if (field?.present === false) continue
      const type = normalizeImportedFieldKey(field?.type, '')
      const sourceName = normalizeImportedFieldKey(field?.sourceName || field?.source_name || field?.name, '')
      if (!['radio', 'checkbox'].includes(type) || !sourceName) continue
      const key = `${type}:${sourceName}`
      counts.set(key, (counts.get(key) || 0) + 1)
      if (counts.get(key) > 1) return true
    }
    return false
  })
}

function getImportedActiveFormIds(forms = []) {
  return new Set((Array.isArray(forms) ? forms : [])
    .filter(form => form?.present !== false)
    .map(form => normalizeImportedFieldKey(form?.formId || form?.form_id || form?.id, ''))
    .filter(Boolean))
}

function importedFormMappingIdentity(mapping = {}) {
  return [
    normalizeImportedAssetPath(mapping.pagePath || mapping.page_path || ''),
    normalizeImportedFieldKey(mapping.formId || mapping.form_id, '')
  ].join('::')
}

function importedFormMappingStableId(mapping = {}) {
  return normalizeImportedFieldKey(mapping.formId || mapping.form_id, '')
}

function isImportedAmbiguousFormMapping(mapping = {}) {
  return mapping?.mappingAmbiguous === true || mapping?.mapping_ambiguous === true
}

function importedFieldMappingIdentity(field = {}) {
  return normalizeImportedFieldKey(field.fieldId || field.field_id || field.sourceName || field.source_name, '')
}

function isImportedAmbiguousFieldMapping(field = {}) {
  return field?.mappingAmbiguous === true || field?.mapping_ambiguous === true
}

function getImportedDuplicateActiveFieldIds(mapping = {}) {
  const counts = new Map()
  for (const field of Array.isArray(mapping?.fields) ? mapping.fields : []) {
    if (field?.present === false) continue
    const fieldId = importedFieldMappingIdentity(field)
    if (fieldId) counts.set(fieldId, (counts.get(fieldId) || 0) + 1)
  }
  return new Set([...counts.entries()].filter(([, count]) => count > 1).map(([fieldId]) => fieldId))
}

function hasImportedAmbiguousFieldMappings(mapping = {}) {
  return mapping?.fieldMappingAmbiguous === true ||
    mapping?.field_mapping_ambiguous === true ||
    getImportedDuplicateActiveFieldIds(mapping).size > 0 ||
    (Array.isArray(mapping?.fields) && mapping.fields.some(field => (
      field?.present !== false && isImportedAmbiguousFieldMapping(field)
    )))
}

function isImportedRuntimeAmbiguousFormMapping(mapping = {}) {
  return isImportedAmbiguousFormMapping(mapping) || hasImportedAmbiguousFieldMappings(mapping)
}

function findExistingImportedFormMapping(existingMappings = [], nextForm = {}) {
  const normalizedFormId = importedFormMappingStableId(nextForm)
  if (!normalizedFormId) return null

  // data-rstk-form-id es único para todo el sitio. pagePath describe dónde se
  // detectó el formulario, pero no forma parte de su identidad persistente: si
  // la IA mueve el mismo formulario de archivo, conserva sus asociaciones.
  // Los placeholders ambiguos nunca pueden convertirse en la fuente canónica.
  const candidates = (Array.isArray(existingMappings) ? existingMappings : []).filter(mapping => (
    !isImportedAmbiguousFormMapping(mapping) &&
    importedFormMappingStableId(mapping) === normalizedFormId
  ))
  if (candidates.length === 1) return candidates[0]

  // Recuperación defensiva para datos antiguos que permitían el mismo ID por
  // página: si el path actual identifica uno solo, úsalo y elimina los demás en
  // el siguiente merge. Si tampoco es inequívoco, no copies datos a ciegas.
  const nextIdentity = importedFormMappingIdentity(nextForm)
  const exactMatches = candidates.filter(mapping => importedFormMappingIdentity(mapping) === nextIdentity)
  return exactMatches.length === 1 ? exactMatches[0] : null
}

function importedFieldMappingAssignmentSignature(field = {}) {
  return JSON.stringify({
    destinationType: cleanString(field.destinationType || field.destination_type),
    destinationKey: normalizeImportedFieldKey(field.destinationKey || field.destination_key, ''),
    saveMode: cleanString(field.saveMode || field.save_mode),
    ignored: Boolean(field.ignored || field.destinationType === 'ignored' || field.destination_type === 'ignored'),
    customFieldDefinitionId: cleanString(field.customFieldDefinitionId || field.custom_field_definition_id),
    customFieldKey: normalizeImportedFieldKey(field.customFieldKey || field.custom_field_key, ''),
    customFieldLabel: cleanString(field.customFieldLabel || field.custom_field_label),
    customFieldDataType: cleanString(field.customFieldDataType || field.custom_field_data_type),
    customFieldSyncTarget: cleanString(field.customFieldSyncTarget || field.custom_field_sync_target)
  })
}

function findExistingImportedFieldMapping(existingMappings = [], nextForm = {}, nextField = {}) {
  const existingForm = findExistingImportedFormMapping(existingMappings, nextForm)
  if (!existingForm) return null
  const normalizedFieldId = normalizeImportedFieldKey(nextField.fieldId, '')
  const normalizedSourceName = normalizeImportedFieldKey(nextField.sourceName, '')
  const fields = Array.isArray(existingForm.fields) ? existingForm.fields : []
  const exactIdMatches = fields.filter(field => (
    !isImportedAmbiguousFieldMapping(field) &&
    normalizedFieldId && normalizeImportedFieldKey(field?.fieldId, '') === normalizedFieldId
  ))
  if (exactIdMatches.length === 1) return exactIdMatches[0]

  // sourceName solo existe como puente para imports legacy. Si cualquiera de
  // los lados declaró data-rstk-field-id, cambiar ese ID significa crear una
  // identidad nueva aunque el atributo name siga igual.
  if (nextField?.hasStableFieldId === true) return null
  const sourceMatches = fields.filter(field => (
    !isImportedAmbiguousFieldMapping(field) &&
    field?.present !== false &&
    field?.hasStableFieldId !== true &&
    normalizedSourceName && normalizeImportedFieldKey(field?.sourceName, '') === normalizedSourceName
  ))
  if (sourceMatches.length === 1) return sourceMatches[0]

  // Recuperación puntual de HTML generado con un ID distinto por opción. Si
  // todos los radios/checkboxes del mismo name tenían exactamente la misma
  // asociación, el nuevo campo lógico puede heredarla sin adivinar. Un grupo
  // con destinos distintos queda sin herencia para no pisar datos del usuario.
  const nextType = normalizeImportedFieldKey(nextField.type, '')
  if (!['radio', 'checkbox'].includes(nextType) || !normalizedSourceName) return null
  const choiceMatches = fields.filter(field => (
    !isImportedAmbiguousFieldMapping(field) &&
    field?.present !== false &&
    normalizeImportedFieldKey(field?.type, '') === nextType &&
    normalizeImportedFieldKey(field?.sourceName, '') === normalizedSourceName
  ))
  if (!choiceMatches.length) return null
  const assignmentSignatures = new Set(choiceMatches.map(importedFieldMappingAssignmentSignature))
  return assignmentSignatures.size === 1 ? choiceMatches[0] : null
}

function mergeImportedFormMappings(existingMappings = [], nextMappings = []) {
  const existing = Array.isArray(existingMappings) ? existingMappings : []
  const nextFormIdCounts = new Map()
  for (const mapping of Array.isArray(nextMappings) ? nextMappings : []) {
    const formId = importedFormMappingStableId(mapping)
    if (formId) nextFormIdCounts.set(formId, (nextFormIdCounts.get(formId) || 0) + 1)
  }
  const ambiguousFormIds = new Set(
    [...nextFormIdCounts.entries()]
      .filter(([, count]) => count > 1)
      .map(([formId]) => formId)
  )

  const next = (Array.isArray(nextMappings) ? nextMappings : []).map(nextForm => {
    const stableFormId = importedFormMappingStableId(nextForm)
    if (ambiguousFormIds.has(stableFormId)) {
      // Dos zonas con el mismo ID se muestran para que el usuario las corrija,
      // pero ninguna hereda asociaciones ni un source form. La versión canónica
      // anterior se conserva abajo como tombstone y reaparece al resolver el ID.
      return {
        ...nextForm,
        mappingAmbiguous: true,
        formSiteId: undefined,
        present: true,
        fields: (Array.isArray(nextForm?.fields) ? nextForm.fields : [])
          .map(field => ({ ...field, present: true }))
      }
    }

    const existingForm = findExistingImportedFormMapping(existingMappings, nextForm)
    const formSiteId = cleanString(existingForm?.formSiteId || existingForm?.form_site_id || nextForm?.formSiteId || nextForm?.form_site_id)
    const duplicateFieldIds = getImportedDuplicateActiveFieldIds(nextForm)
    const nextFieldIdentities = new Set((nextForm.fields || []).map(importedFieldMappingIdentity).filter(Boolean))
    const dormantFields = (Array.isArray(existingForm?.fields) ? existingForm.fields : [])
      .filter(field => (
        !isImportedAmbiguousFieldMapping(field) && (
          !nextFieldIdentities.has(importedFieldMappingIdentity(field)) ||
          duplicateFieldIds.has(importedFieldMappingIdentity(field))
        )
      ))
      .map(field => ({ ...field, mappingAmbiguous: undefined, present: false }))

    return {
      ...nextForm,
      mappingAmbiguous: undefined,
      fieldMappingAmbiguous: duplicateFieldIds.size > 0 ? true : undefined,
      ...(formSiteId ? { formSiteId } : {}),
      present: true,
      fields: (Array.isArray(nextForm?.fields) ? nextForm.fields : []).map(nextField => {
        if (duplicateFieldIds.has(importedFieldMappingIdentity(nextField))) {
          return { ...nextField, mappingAmbiguous: true, present: true }
        }
        const existingField = findExistingImportedFieldMapping(existingMappings, nextForm, nextField)
        if (!existingField) return { ...nextField, mappingAmbiguous: undefined, present: true }

        return {
          ...nextField,
          mappingAmbiguous: undefined,
          present: true,
          destinationType: existingField.destinationType || nextField.destinationType,
          destinationKey: existingField.destinationKey || nextField.destinationKey,
          saveMode: existingField.saveMode || nextField.saveMode,
          ignored: Boolean(existingField.ignored || existingField.destinationType === 'ignored'),
          confidence: Number(existingField.confidence || nextField.confidence || 0) || nextField.confidence,
          customFieldDefinitionId: existingField.customFieldDefinitionId || existingField.custom_field_definition_id || nextField.customFieldDefinitionId,
          customFieldKey: existingField.customFieldKey || existingField.custom_field_key || nextField.customFieldKey,
          customFieldLabel: existingField.customFieldLabel || existingField.custom_field_label || nextField.customFieldLabel,
          customFieldDataType: existingField.customFieldDataType || existingField.custom_field_data_type || nextField.customFieldDataType,
          customFieldSyncTarget: existingField.customFieldSyncTarget || existingField.custom_field_sync_target || nextField.customFieldSyncTarget,
          options: Array.isArray(nextField.options) && nextField.options.length
            ? nextField.options
            : existingField.options || []
        }
      }).concat(dormantFields)
    }
  })

  const nextFormIds = new Set(next.map(importedFormMappingStableId).filter(Boolean))
  const dormantForms = existing
    .filter(mapping => {
      if (isImportedAmbiguousFormMapping(mapping)) return false
      const stableFormId = importedFormMappingStableId(mapping)
      return stableFormId && (!nextFormIds.has(stableFormId) || ambiguousFormIds.has(stableFormId))
    })
    .map(mapping => ({
      ...mapping,
      mappingAmbiguous: undefined,
      present: false,
      fields: (Array.isArray(mapping.fields) ? mapping.fields : []).map(field => ({ ...field, present: false }))
    }))

  return [...next, ...dormantForms]
}

function importedFieldDefinitionDataType(field = {}) {
  return inferImportedDataType(field, '')
}

function importedDefinitionAcceptsField(definition = {}, field = {}) {
  const definitionType = inferImportedDataType({
    type: definition.dataType || definition.data_type || 'text'
  }, '')
  return definitionType === importedFieldDefinitionDataType(field)
}

function isImportedDefinitionUniqueConflict(error) {
  const code = cleanString(error?.code).toUpperCase()
  const message = cleanString(error?.message).toLowerCase()
  return code === '23505' || code.includes('SQLITE_CONSTRAINT') || (
    message.includes('unique') && message.includes('contact_custom_field_definitions')
  )
}

function importedDefinitionMapping(field = {}, definition = {}) {
  const fieldKey = normalizeImportedFieldKey(
    definition.fieldKey || definition.key || definition.field_key,
    field.destinationKey || field.customFieldKey || 'custom_field'
  )

  return {
    ...field,
    destinationType: 'custom',
    destinationKey: fieldKey,
    saveMode: 'custom',
    ignored: false,
    customFieldDefinitionId: cleanString(
      definition.definitionId || definition.id || definition.definition_id
    ),
    customFieldKey: fieldKey,
    customFieldLabel: cleanString(definition.label || definition.name || field.label) || fieldKey,
    customFieldDataType: cleanString(definition.dataType || definition.data_type) || importedFieldDefinitionDataType(field),
    customFieldSyncTarget: cleanString(definition.syncTarget || definition.sync_target) || 'local'
  }
}

function importedAutomaticFieldDefinitionCandidates(field = {}, definitionsByKey = new Map()) {
  const baseKey = normalizeImportedFieldKey(
    field.destinationKey || field.customFieldKey || field.sourceName || field.fieldId || field.label,
    'custom_field'
  )
  const dataType = importedFieldDefinitionDataType(field)
  const candidates = [baseKey]
  const typedKey = normalizeImportedFieldKey(`${baseKey}_${dataType}`, 'custom_field')
  if (typedKey !== baseKey) candidates.push(typedKey)

  for (let suffix = 2; suffix <= 100; suffix += 1) {
    const candidate = normalizeImportedFieldKey(`${typedKey}_${suffix}`, 'custom_field')
    if (!definitionsByKey.has(candidate)) {
      candidates.push(candidate)
      break
    }
    candidates.push(candidate)
  }

  return candidates
}

async function materializeImportedCustomFieldMappings({ site, imported, mappings = [] } = {}) {
  const definitions = await listContactCustomFieldDefinitions()
  const definitionsByKey = new Map(definitions.map(definition => [
    normalizeImportedFieldKey(definition.fieldKey || definition.key, ''),
    definition
  ]))
  const definitionsById = new Map(definitions.map(definition => [
    cleanString(definition.definitionId || definition.id),
    definition
  ]))

  const nextMappings = []
  for (const mapping of Array.isArray(mappings) ? mappings : []) {
    if (mapping?.present === false || isImportedRuntimeAmbiguousFormMapping(mapping)) {
      nextMappings.push(mapping)
      continue
    }

    const nextFields = []
    for (const originalField of Array.isArray(mapping?.fields) ? mapping.fields : []) {
      if (originalField?.present === false || isImportedAmbiguousFieldMapping(originalField)) {
        nextFields.push(originalField)
        continue
      }

      const route = getImportedFieldRoute(originalField, 'custom_field')
      const destinationType = route.destinationType
      const field = route.upgradedLegacyMessage
        ? {
            ...originalField,
            destinationType,
            destinationKey: route.destinationKey,
            saveMode: destinationType,
            ignored: false,
            customFieldDefinitionId: undefined,
            customFieldKey: route.destinationKey,
            customFieldLabel: cleanString(originalField.customFieldLabel || originalField.label) || route.destinationKey,
            customFieldDataType: cleanString(originalField.customFieldDataType) || importedFieldDefinitionDataType(originalField),
            customFieldSyncTarget: cleanString(originalField.customFieldSyncTarget) || 'local'
          }
        : originalField
      if (destinationType === 'standard' || destinationType === 'ignored') {
        nextFields.push(field)
        continue
      }

      const destinationKey = route.destinationKey
      if (IMPORTED_FORM_SYSTEM_FIELDS.has(destinationKey)) {
        nextFields.push({
          ...field,
          destinationType: 'standard',
          destinationKey,
          saveMode: 'standard',
          ignored: false,
          customFieldDefinitionId: undefined,
          customFieldKey: undefined,
          customFieldLabel: undefined,
          customFieldDataType: undefined,
          customFieldSyncTarget: undefined
        })
        continue
      }

      const configuredDefinitionId = cleanString(
        field.customFieldDefinitionId || field.custom_field_definition_id
      )
      const configuredDefinition = configuredDefinitionId
        ? definitionsById.get(configuredDefinitionId)
        : null
      if (destinationType === 'custom' && configuredDefinition) {
        nextFields.push(importedDefinitionMapping(field, configuredDefinition))
        continue
      }

      let materializedDefinition = null
      const candidates = importedAutomaticFieldDefinitionCandidates(field, definitionsByKey)
      for (const candidateKey of candidates) {
        const existing = definitionsByKey.get(candidateKey)
        if (existing && !importedDefinitionAcceptsField(existing, field)) continue

        try {
          materializedDefinition = await upsertContactCustomFieldDefinition({
            fieldKey: candidateKey,
            label: cleanString(field.customFieldLabel || field.label) || candidateKey,
            dataType: importedFieldDefinitionDataType(field),
            options: normalizeImportedFieldOptions(field.options || []),
            syncTarget: cleanString(field.customFieldSyncTarget) || 'local',
            sourceType: 'imported_html',
            sourceId: imported?.id || '',
            sourceSiteId: site?.id || '',
            sourcePageId: cleanString(mapping.pagePath || mapping.page_path),
            sourceFormId: cleanString(mapping.formId || mapping.form_id),
            sourceFormName: cleanString(mapping.formTitle || mapping.form_title),
            sourceFieldId: cleanString(field.fieldId || field.field_id),
            sourceFieldName: cleanString(field.sourceName || field.source_name),
            sourceLabel: cleanString(field.label),
            sourceContext: {
              imported: true,
              originalFilename: imported?.originalFilename || '',
              confidence: field.confidence ?? null
            }
          }, {
            sourceType: 'imported_html',
            sourceId: imported?.id || '',
            sourceSiteId: site?.id || '',
            syncTarget: 'local'
          })
        } catch (error) {
          // Otro import puede crear la misma llave entre la lectura y el INSERT.
          // Releer en la siguiente vuelta permite reutilizarla sin duplicar campos.
          const refreshed = await listContactCustomFieldDefinitions()
          for (const definition of refreshed) {
            definitionsByKey.set(
              normalizeImportedFieldKey(definition.fieldKey || definition.key, ''),
              definition
            )
            definitionsById.set(cleanString(definition.definitionId || definition.id), definition)
          }
          const concurrent = definitionsByKey.get(candidateKey)
          if (!concurrent || !importedDefinitionAcceptsField(concurrent, field)) {
            if (isImportedDefinitionUniqueConflict(error)) continue
            throw error
          }
          materializedDefinition = concurrent
        }

        if (materializedDefinition && importedDefinitionAcceptsField(materializedDefinition, field)) break
        materializedDefinition = null
      }

      if (!materializedDefinition) {
        nextFields.push(field)
        continue
      }

      definitionsByKey.set(
        normalizeImportedFieldKey(materializedDefinition.fieldKey || materializedDefinition.key, ''),
        materializedDefinition
      )
      definitionsById.set(
        cleanString(materializedDefinition.definitionId || materializedDefinition.id),
        materializedDefinition
      )
      nextFields.push(importedDefinitionMapping(field, materializedDefinition))
    }

    nextMappings.push({ ...mapping, fields: nextFields })
  }

  return nextMappings
}

function importedMappingsAreFullyResolved(mappings = []) {
  return (Array.isArray(mappings) ? mappings : []).every(mapping => {
    if (mapping?.present === false) return true
    if (isImportedRuntimeAmbiguousFormMapping(mapping)) return false
    return (Array.isArray(mapping?.fields) ? mapping.fields : []).every(field => {
      if (field?.present === false) return true
      const destinationType = field.ignored
        ? 'ignored'
        : cleanString(field.destinationType || field.saveMode || '').toLowerCase()
      if (destinationType === 'standard' || destinationType === 'ignored') return true
      return destinationType === 'custom' && Boolean(cleanString(
        field.customFieldDefinitionId || field.custom_field_definition_id
      ))
    })
  })
}

function getImportedFormMappingSourceSiteId(mapping = {}) {
  return cleanString(mapping.formSiteId || mapping.form_site_id)
}

function findImportedDetectedFormForMapping(detectedForms = [], mapping = {}) {
  const normalizedFormId = normalizeImportedFieldKey(mapping?.formId, '')
  const normalizedFormTitle = normalizeImportedFieldKey(mapping?.formTitle, '')
  const forms = Array.isArray(detectedForms) ? detectedForms : []

  return forms.find(form => normalizeImportedFieldKey(form?.id, '') === normalizedFormId) ||
    forms.find(form => normalizedFormTitle && normalizeImportedFieldKey(form?.title, '') === normalizedFormTitle) ||
    null
}

function findImportedDetectedFieldForMapping(detectedForm = {}, fieldMapping = {}) {
  const fields = Array.isArray(detectedForm?.fields) ? detectedForm.fields : []
  const normalizedFieldId = normalizeImportedFieldKey(fieldMapping?.fieldId, '')
  const normalizedSourceName = normalizeImportedFieldKey(fieldMapping?.sourceName, '')

  return fields.find(field => normalizeImportedFieldKey(field?.id, '') === normalizedFieldId) ||
    fields.find(field => normalizedSourceName && normalizeImportedFieldKey(field?.sourceName || field?.name, '') === normalizedSourceName) ||
    null
}

function getImportedSourceFormName(site = {}, mapping = {}, detectedForm = {}) {
  const siteName = cleanString(site.name || site.title || site.slug) || 'la página'
  const formTitle = cleanString(mapping.formTitle || detectedForm.title)
  const genericTitle = /^formulario(?:\s+\d+| detectado)?$/i.test(formTitle)
  const suffix = formTitle && !genericTitle ? ` - ${formTitle}` : ''
  return limitString(`Formulario de ${siteName}${suffix}`, 100)
}

function getImportedSourceFormSlug(site = {}, mapping = {}) {
  return slugify(`formulario-${site.slug || site.name || site.id}-${mapping.formId || mapping.formTitle || 'html'}`)
}

function getImportedSourceFormBlockId(siteId = '', formId = '', fieldId = '') {
  return `imported_field_${crypto
    .createHash('sha1')
    .update(`${siteId}:${formId}:${fieldId}`)
    .digest('hex')
    .slice(0, 28)}`
}

function getImportedSourceFieldBlockType(fieldMapping = {}, detectedField = {}) {
  const type = normalizeImportedFieldKey(fieldMapping.type || detectedField.type || detectedField.tag, '')
  const tag = normalizeImportedFieldKey(detectedField.tag, '')

  if (tag === 'textarea' || type === 'textarea' || type === 'paragraph') return 'paragraph'
  if (type === 'multiselect') return 'multiselect'
  if (type === 'checkboxes') return 'checkboxes'
  if (tag === 'select' || type === 'select' || type === 'dropdown') return 'dropdown'
  if (type === 'radio') return 'radio'
  if (type === 'checkbox') return 'checkboxes'
  if (type === 'email') return 'email'
  if (type === 'tel' || type === 'phone') return 'phone'
  if (type === 'number') return 'number'
  if (type === 'date') return 'date'
  if (type === 'currency') return 'currency'
  return 'short_text'
}

function getImportedSourceFieldOptions(fieldMapping = {}, detectedField = {}) {
  const options = Array.isArray(detectedField?.options) && detectedField.options.length
    ? detectedField.options
    : fieldMapping.options

  return normalizeImportedFieldOptions(options || [])
}

function getImportedSourceFieldSettings({ site, imported, mapping, fieldMapping, detectedField }) {
  const { destinationType, destinationKey } = getImportedFieldRoute(fieldMapping, 'custom_field')
  const internalName = normalizeImportedFieldKey(fieldMapping?.sourceName || fieldMapping?.fieldId || destinationKey, 'field')
  const settings = {
    pageId: DEFAULT_FUNNEL_PAGE_ID,
    internalName,
    importedHtmlSource: true,
    importedHtmlSourceSiteId: site?.id || '',
    importedHtmlSourceImportId: imported?.id || '',
    importedHtmlSourceFormId: mapping?.formId || '',
    importedHtmlSourceFieldId: fieldMapping?.fieldId || detectedField?.id || '',
    importedHtmlSourceName: fieldMapping?.sourceName || detectedField?.sourceName || '',
    importedDestinationType: destinationType,
    importedDestinationKey: destinationKey,
    importedIgnored: destinationType === 'ignored'
  }

  if (destinationType === 'standard' && IMPORTED_FORM_SYSTEM_FIELDS.has(destinationKey)) {
    settings.systemFieldKey = destinationKey
  } else if (destinationType !== 'ignored') {
    const customFieldDefinitionId = cleanString(
      fieldMapping?.customFieldDefinitionId || fieldMapping?.custom_field_definition_id
    )
    const configuredDataType = cleanString(
      fieldMapping?.customFieldDataType || fieldMapping?.custom_field_data_type
    )
    if (customFieldDefinitionId) settings.customFieldDefinitionId = customFieldDefinitionId
    settings.customFieldKey = destinationKey
    settings.customFieldLabel = cleanString(fieldMapping?.customFieldLabel || fieldMapping?.label || detectedField?.label) || settings.customFieldKey
    settings.customFieldDataType = destinationType === 'custom' && configuredDataType
      ? configuredDataType
      : inferImportedDataType(fieldMapping, '')
    settings.customFieldSyncTarget = cleanString(fieldMapping?.customFieldSyncTarget || fieldMapping?.custom_field_sync_target || 'local')
  }

  if (settings.systemFieldKey === 'email') settings.validation = 'email'
  if (settings.systemFieldKey === 'phone') settings.validation = 'phone'

  return settings
}

function buildImportedSourceFormBlocks({ formSiteId, site, imported, mapping, detectedForm }) {
  return (Array.isArray(mapping?.fields) ? mapping.fields : []).map((fieldMapping, index) => {
    const detectedField = findImportedDetectedFieldForMapping(detectedForm, fieldMapping) || {}
    const label = cleanString(fieldMapping.label || detectedField.label || detectedField.placeholder || fieldMapping.sourceName || fieldMapping.fieldId) ||
      `Pregunta ${index + 1}`

    return {
      id: getImportedSourceFormBlockId(site?.id, mapping?.formId, fieldMapping.fieldId || fieldMapping.sourceName || index),
      siteId: formSiteId,
      blockType: getImportedSourceFieldBlockType(fieldMapping, detectedField),
      label,
      content: '',
      placeholder: cleanString(detectedField.placeholder || fieldMapping.placeholder),
      required: Boolean(detectedField.required || fieldMapping.required),
      options: getImportedSourceFieldOptions(fieldMapping, detectedField),
      settings: getImportedSourceFieldSettings({ site, imported, mapping, fieldMapping, detectedField }),
      sortOrder: index
    }
  })
}

function buildImportedSourceFormTheme({ sourceSite, existingSite, mapping, detectedForm }) {
  const existingTheme = existingSite?.theme || {}
  const existingPages = normalizeSitePages({
    siteType: 'standard_form',
    theme: existingTheme
  })
  const finalPages = existingPages.filter(page => FORM_FINAL_PAGE_IDS.has(page.id))
  const submitText = cleanString(mapping?.submitText || detectedForm?.submitText) || 'Enviar'
  const sourceTemplate = cleanString(sourceSite?.theme?.template)

  return withSiteLibraryMetadata({
    ...existingTheme,
    template: cleanString(existingTheme.template) || (sourceTemplate && sourceTemplate !== IMPORTED_SITE_TEMPLATE ? sourceTemplate : 'ristak'),
    formCompletionAction: normalizeFormCompletionAction(existingTheme.formCompletionAction || existingTheme.form_completion_action, 'next_page_if_qualified'),
    submitText,
    pages: [
      {
        ...(existingPages.find(page => !FORM_FINAL_PAGE_IDS.has(page.id)) || {}),
        id: DEFAULT_FUNNEL_PAGE_ID,
        title: cleanString(mapping?.formTitle || detectedForm?.title) || 'Formulario',
        sortOrder: 0,
        buttonText: submitText
      },
      ...finalPages
    ],
    importedHtmlSource: true,
    importedHtmlSourceActive: true,
    importedHtmlSourceSiteId: sourceSite?.id || '',
    importedHtmlSourceSiteName: cleanString(sourceSite?.name || sourceSite?.title),
    importedHtmlSourceFormId: mapping?.formId || '',
    submitIncompleteOnExit: normalizeImportedContactCaptureMode(
      mapping?.contactCaptureMode || mapping?.contact_capture_mode || detectedForm?.contactCaptureMode || detectedForm?.contact_capture_mode
    ) === IMPORTED_CONTACT_CAPTURE_ALL_SUBMISSIONS,
    importedHtmlSourcePagePath: cleanString(detectedForm?.pagePath || detectedForm?.page_path),
    importedHtmlSourceTitle: cleanString(mapping?.formTitle || detectedForm?.title),
    importedHtmlSourceSubmitText: submitText
  }, {
    folderId: cleanString(existingTheme.libraryFolderId) || SITE_LIBRARY_HTML_FORMS_FOLDER_ID,
    source: cleanString(existingTheme.librarySource) || SITE_LIBRARY_SOURCE_HTML
  })
}

async function markImportedSourceFormInactive(formSiteId, sourceSiteId) {
  const sourceForm = cleanString(formSiteId)
    ? await getSite(formSiteId, { includeBlocks: false, includeSubmissions: false }).catch(() => null)
    : null
  if (
    !sourceForm?.theme?.importedHtmlSource ||
    cleanString(sourceForm.theme.importedHtmlSourceSiteId) !== cleanString(sourceSiteId) ||
    sourceForm.theme.importedHtmlSourceActive === false
  ) return

  await updateSite(sourceForm.id, {
    theme: {
      ...sourceForm.theme,
      importedHtmlSourceActive: false
    }
  })
}

async function syncImportedSourceFormBlocks(formSiteId, blocks = [], context = {}) {
  const nextIds = new Set(blocks.map(block => cleanString(block.id)).filter(Boolean))
  const currentBlocks = await listSiteBlocks(formSiteId).catch(() => [])

  for (const block of currentBlocks) {
    const settings = block.settings || {}
    const isImportedBlock = settings.importedHtmlSource === true &&
      cleanString(settings.importedHtmlSourceSiteId) === cleanString(context.sourceSiteId) &&
      cleanString(settings.importedHtmlSourceFormId) === cleanString(context.sourceFormId)
    if (isImportedBlock && !nextIds.has(block.id)) {
      await deleteBlock(formSiteId, block.id)
    }
  }

  if (blocks.length) {
    await restoreBlocks(formSiteId, blocks)
  }
}

async function syncImportedFormSourceSites({ site, imported, detectedForms = [], mappings = [] } = {}) {
  if (!site || !imported) return Array.isArray(mappings) ? mappings : []

  const activeFormIdCounts = new Map()
  for (const mapping of Array.isArray(mappings) ? mappings : []) {
    if (mapping?.present === false) continue
    const formId = importedFormMappingStableId(mapping)
    if (formId) activeFormIdCounts.set(formId, (activeFormIdCounts.get(formId) || 0) + 1)
  }

  const nextMappings = []
  for (const mapping of Array.isArray(mappings) ? mappings : []) {
    if (mapping?.present === false) {
      await markImportedSourceFormInactive(
        getImportedFormMappingSourceSiteId(mapping),
        site.id
      )
      nextMappings.push(mapping)
      continue
    }

    const stableFormId = importedFormMappingStableId(mapping)
    if (isImportedRuntimeAmbiguousFormMapping(mapping) || activeFormIdCounts.get(stableFormId) !== 1) {
      nextMappings.push(mapping)
      continue
    }

    const fields = Array.isArray(mapping?.fields)
      ? mapping.fields.filter(field => field?.present !== false)
      : []
    if (!cleanString(mapping?.formId) || fields.length === 0) {
      nextMappings.push(mapping)
      continue
    }

    const activeMapping = {
      ...mapping,
      fields
    }

    const detectedForm = findImportedDetectedFormForMapping(detectedForms, activeMapping) || {}
    const name = getImportedSourceFormName(site, activeMapping, detectedForm)
    let formSiteId = getImportedFormMappingSourceSiteId(activeMapping)
    let sourceForm = formSiteId
      ? await getSite(formSiteId, { includeBlocks: true, includeSubmissions: false }).catch(() => null)
      : null
    const theme = buildImportedSourceFormTheme({
      sourceSite: site,
      existingSite: sourceForm,
      mapping: activeMapping,
      detectedForm
    })

    if (!sourceForm) {
      sourceForm = await createSite({
        name,
        title: name,
        slug: getImportedSourceFormSlug(site, mapping),
        siteType: 'standard_form',
        status: site.status === 'published' ? 'published' : 'draft',
        blankCanvas: true,
        theme
      })
      formSiteId = sourceForm?.id || ''
    } else {
      await updateSite(formSiteId, {
        name,
        title: name,
        description: sourceForm.description || '',
        siteType: 'standard_form',
        status: sourceForm.status || (site.status === 'published' ? 'published' : 'draft'),
        theme
      })
    }

    const sourceBlocks = buildImportedSourceFormBlocks({
      formSiteId,
      site,
      imported,
      mapping: activeMapping,
      detectedForm
    })
    await syncImportedSourceFormBlocks(formSiteId, sourceBlocks, {
      sourceSiteId: site.id,
      sourceFormId: activeMapping.formId
    })

    nextMappings.push({
      ...mapping,
      formSiteId
    })
  }

  return nextMappings
}

function mergeImportedFormSourceIds(currentMappings = [], syncedMappings = []) {
  const syncedByIdentity = new Map()
  for (const mapping of Array.isArray(syncedMappings) ? syncedMappings : []) {
    if (mapping?.present === false || isImportedRuntimeAmbiguousFormMapping(mapping)) continue
    const identity = importedFormMappingIdentity(mapping)
    const formSiteId = getImportedFormMappingSourceSiteId(mapping)
    if (!identity || !formSiteId) continue
    const matches = syncedByIdentity.get(identity) || []
    matches.push(formSiteId)
    syncedByIdentity.set(identity, matches)
  }

  return (Array.isArray(currentMappings) ? currentMappings : []).map(mapping => {
    if (mapping?.present === false || isImportedRuntimeAmbiguousFormMapping(mapping)) return mapping
    const matches = syncedByIdentity.get(importedFormMappingIdentity(mapping)) || []
    const uniqueIds = [...new Set(matches.filter(Boolean))]
    return uniqueIds.length === 1 ? { ...mapping, formSiteId: uniqueIds[0] } : mapping
  })
}

async function syncAndPersistImportedFormSourceSites(siteId) {
  const [site, imported] = await Promise.all([
    getSite(siteId, { includeBlocks: false, includeSubmissions: false }),
    getImportedSiteBySiteId(siteId)
  ])

  if (!site || !imported) return imported

  // La detección no termina en un "campo nuevo" virtual. Antes de construir el
  // formulario ejecutable, cada destino personalizado se reutiliza o se crea en
  // el catálogo canónico y la asociación completa queda persistida en el import.
  // Así el HTML, el formulario fuente y Contactos comparten el mismo definitionId
  // desde el primer envío, sin una visita manual al panel de mapeo.
  const materializedMappings = await materializeImportedCustomFieldMappings({
    site,
    imported,
    mappings: imported.formMappings
  })
  const materializedStatus = importedMappingsAreFullyResolved(materializedMappings)
    ? 'mapping_confirmed'
    : 'mapping_pending'
  await db.run(`
    UPDATE public_site_imports SET
      form_mappings_json = ?,
      status = ?,
      updated_at = CURRENT_TIMESTAMP
    WHERE site_id = ?
  `, [jsonString(materializedMappings), materializedStatus, siteId])

  const materializedImport = {
    ...imported,
    formMappings: materializedMappings,
    status: materializedStatus
  }

  const syncedMappings = await syncImportedFormSourceSites({
    site,
    imported: materializedImport,
    detectedForms: materializedImport.detectedForms,
    mappings: materializedMappings
  })

  // El sync crea/actualiza formularios relacionados fuera de la transacción.
  // Al persistir, releemos la fila bloqueada y mezclamos únicamente formSiteId;
  // nunca reescribimos rutas de campos desde un snapshot potencialmente viejo.
  const persistedMappings = await db.transaction(async tx => {
    const lockSuffix = databaseDialect === 'postgres' ? ' FOR UPDATE' : ''
    const row = await tx.get(`
      SELECT form_mappings_json
      FROM public_site_imports
      WHERE site_id = ?${lockSuffix}
    `, [siteId])
    if (!row) return syncedMappings
    const latestMappings = parseJson(row.form_mappings_json, [])
    const mergedMappings = mergeImportedFormSourceIds(latestMappings, syncedMappings)
    await tx.run(`
      UPDATE public_site_imports SET
        form_mappings_json = ?,
        updated_at = CURRENT_TIMESTAMP
      WHERE site_id = ?
    `, [jsonString(mergedMappings), siteId])
    return mergedMappings
  })

  return {
    ...materializedImport,
    formMappings: persistedMappings
  }
}

const importedSiteMutationLockContext = new AsyncLocalStorage()

async function withImportedSiteMutationLock(siteId, operation) {
  const normalizedSiteId = cleanString(siteId)
  const parentScope = importedSiteMutationLockContext.getStore()
  if (parentScope?.active === true && parentScope.siteIds?.has(normalizedSiteId)) {
    return operation()
  }

  const lockName = `sites:imported-html:${normalizedSiteId}`
  for (let attempt = 0; attempt < 120; attempt += 1) {
    try {
      return await db.withAdvisoryLock(
        lockName,
        async () => {
          const scope = {
            active: true,
            siteIds: new Set(parentScope?.active === true ? parentScope.siteIds : [])
          }
          scope.siteIds.add(normalizedSiteId)
          try {
            return await importedSiteMutationLockContext.run(scope, operation)
          } finally {
            // Un trabajo desprendido puede heredar AsyncLocalStorage. Marcar el
            // scope como cerrado evita que confunda ese contexto con un lock vivo.
            scope.active = false
          }
        },
        // La sincronización puede actualizar formularios fuente, cada uno con su
        // propio candado. El lock de sesión sigue reservado, pero las consultas no
        // quedan fijadas a esa conexión y PostgreSQL permite adquirir esos locks.
        { pinConnection: false }
      )
    } catch (error) {
      if (error?.code !== 'DATABASE_ADVISORY_LOCK_BUSY' || attempt === 119) throw error
      await new Promise(resolve => setTimeout(resolve, Math.min(25 + (attempt * 5), 150)))
    }
  }
  throw new Error('No se pudo reservar la importacion HTML para guardar cambios')
}

function getSocialProfileDefaults(site = {}, platform = 'facebook') {
  const theme = site.theme || {}
  const normalizedPlatform = isSocialTemplate(platform) ? platform : 'facebook'
  const socialProfileScale = blockSettingNumberWithFallback(
    theme,
    'socialProfileScale',
    DEFAULT_SOCIAL_PROFILE_SCALE,
    SOCIAL_PROFILE_SCALE_MIN,
    SOCIAL_PROFILE_SCALE_MAX
  )

  return {
    platform: normalizedPlatform,
    brandName: cleanString(theme.brandName) || cleanString(site.title) || cleanString(site.name) || 'Tu marca',
    brandSubtitle: cleanString(theme.brandSubtitle) || (normalizedPlatform === 'instagram' ? 'Publicación pagada' : 'Patrocinado'),
    brandAvatar: cleanString(theme.brandAvatar),
    followers: cleanString(theme.followers),
    socialProfileScale,
    brandVerified: theme.brandVerified === undefined ? true : theme.brandVerified !== false
  }
}

function getSocialProfileLandingSpacing() {
  return {
    blockMarginLinked: false,
    blockMarginTop: 0,
    blockMarginRight: 0,
    blockMarginBottom: 18,
    blockMarginLeft: 0,
    blockPaddingLinked: true,
    blockPadding: 0,
    blockPaddingTop: 0,
    blockPaddingRight: 0,
    blockPaddingBottom: 0,
    blockPaddingLeft: 0
  }
}

function normalizeBoolean(value) {
  if (value === true || value === 1) return 1
  if (typeof value === 'string') {
    return ['1', 'true', 'yes', 'on', 'enabled'].includes(value.trim().toLowerCase()) ? 1 : 0
  }
  return 0
}

function slugify(value) {
  const base = cleanString(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')

  return base || `site-${Date.now()}`
}

function normalizeSiteRoutePath(value) {
  return cleanString(value)
    .split(/[?#]/, 1)[0]
    .split('/')
    .map(segment => {
      let decoded = segment
      try {
        decoded = decodeURIComponent(segment)
      } catch {
        decoded = segment
      }
      return slugifyPageSegment(decoded)
    })
    .filter(Boolean)
    .join('/')
}

function getDefaultRoutePrefix(siteType) {
  return siteType === 'landing_page' ? 'embudo' : 'formulario'
}

function getDefaultSiteNamePrefix(siteType) {
  return siteType === 'landing_page' ? 'Embudo' : 'Formulario'
}

function getDefaultSiteName(siteType, slug) {
  const prefix = getDefaultSiteNamePrefix(siteType)
  const suffix = cleanString(slug).match(/(\d+)$/)?.[1]
  return suffix ? `${prefix} ${suffix.padStart(2, '0')}` : `${prefix} 01`
}

async function getNextDefaultSlug(siteType) {
  const prefix = getDefaultRoutePrefix(siteType)
  const rows = await db.all(
    'SELECT slug FROM public_sites WHERE slug LIKE ?',
    [`${prefix}-%`]
  )
  const used = new Set(rows.map(row => row.slug))
  let index = 1
  let slug = `${prefix}-${String(index).padStart(2, '0')}`

  while (used.has(slug)) {
    index += 1
    slug = `${prefix}-${String(index).padStart(2, '0')}`
  }

  return slug
}

function parseHost(value) {
  const rawValue = cleanString(value)
  if (!rawValue) return ''

  const withoutProtocol = rawValue.replace(/^https?:\/\//i, '')
  const withoutPath = withoutProtocol.split('/')[0]
  const withoutUser = withoutPath.split('@').pop() || withoutPath

  if (withoutUser.startsWith('[')) {
    return withoutUser.replace(/^\[|\].*$/g, '').toLowerCase()
  }

  return withoutUser.split(':')[0].replace(/\.$/, '').toLowerCase()
}

export function normalizeDomain(value) {
  const host = parseHost(value)
  if (!host) return ''

  if (host === 'localhost' || host === '127.0.0.1' || host === '::1') {
    return host
  }

  const isValid = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)+$/.test(host)
  return isValid ? host : ''
}

export function getRequestHost(req) {
  const forwardedHost = cleanString(req.headers['x-forwarded-host']).split(',')[0]
  return normalizeDomain(forwardedHost || req.headers.host || req.hostname)
}

function parseDomainList(value) {
  return cleanString(value)
    .split(',')
    .map(normalizeDomain)
    .filter(Boolean)
}

export function isAppSubdomainHost(hostValue) {
  const host = normalizeDomain(hostValue)
  if (!host) return false

  const labels = host.split('.').filter(Boolean)
  return labels.length >= 3 && labels[0].startsWith('app')
}

function getRenderDefaultHosts() {
  const hosts = new Set()

  for (const value of [
    process.env.RENDER_EXTERNAL_HOSTNAME,
    process.env.RENDER_EXTERNAL_URL,
    process.env.VITE_API_URL,
    process.env.PUBLIC_URL
  ]) {
    const host = normalizeDomain(value)
    if (host) hosts.add(host)
  }

  return hosts
}

export function isDashboardHost(hostValue) {
  const host = normalizeDomain(hostValue)
  if (!host) return false

  if (
    host === 'localhost' ||
    host === '127.0.0.1' ||
    host === '::1' ||
    host.endsWith('.localhost') ||
    host.endsWith('.local')
  ) {
    return true
  }

  if (host.endsWith('.onrender.com')) {
    return true
  }

  const dashboardHosts = new Set([
    ...parseDomainList(process.env.DASHBOARD_DOMAINS),
    ...getRenderDefaultHosts()
  ])

  return dashboardHosts.has(host)
}

function normalizePublicBaseUrl(value) {
  const raw = cleanString(value)
  if (!raw) return ''

  try {
    const parsed = new URL(/^https?:\/\//i.test(raw) ? raw : `https://${raw}`)
    if (!['http:', 'https:'].includes(parsed.protocol)) return ''

    const host = normalizeDomain(parsed.hostname)
    if (!host) return ''

    return `${parsed.protocol}//${parsed.host}`.replace(/\/+$/, '')
  } catch {
    return ''
  }
}

function getCalendarFallbackBaseUrl() {
  const candidates = [
    ['calendar_public_base_url', process.env.CALENDAR_PUBLIC_BASE_URL],
    ['public_calendar_base_url', process.env.PUBLIC_CALENDAR_BASE_URL],
    ['render', process.env.RENDER_EXTERNAL_URL],
    ['render', process.env.RENDER_EXTERNAL_HOSTNAME],
    ['public_url', process.env.PUBLIC_URL],
    ['vite_api_url', process.env.VITE_API_URL]
  ]

  if (process.env.NODE_ENV !== 'production') {
    candidates.push(['local', `http://localhost:${process.env.PORT || 3001}`])
  }

  for (const [source, value] of candidates) {
    const baseUrl = normalizePublicBaseUrl(value)
    if (!baseUrl) continue

    const domain = normalizeDomain(baseUrl)
    if (!domain) continue

    return {
      baseUrl,
      domain,
      source
    }
  }

  return null
}

export async function getCalendarPublicBaseUrlStatus() {
  const publicConfig = await getSitesPublicDomainConfig()

  if (publicConfig.domain && publicConfig.renderDomainVerified) {
    return {
      enabled: true,
      domain: publicConfig.domain,
      baseUrl: `https://${publicConfig.domain}`,
      source: 'connected_public_domain',
      lockedToPublicCalendar: true,
      reason: ''
    }
  }

  const fallback = getCalendarFallbackBaseUrl()
  if (fallback) {
    return {
      enabled: true,
      domain: fallback.domain,
      baseUrl: fallback.baseUrl,
      source: fallback.source,
      lockedToPublicCalendar: fallback.source !== 'local',
      reason: publicConfig.domain
        ? 'El dominio público general todavía no está verificado; se usará el dominio seguro de respaldo.'
        : 'Se usará el dominio seguro de respaldo hasta conectar un dominio público.'
    }
  }

  return {
    enabled: false,
    domain: publicConfig.domain || '',
    baseUrl: '',
    source: '',
    lockedToPublicCalendar: false,
    reason: publicConfig.domain
      ? publicConfig.renderDomainError || 'El dominio público general existe, pero todavía no responde a esta app.'
      : 'Conecta un dominio público o configura RENDER_EXTERNAL_URL para generar el enlace completo.'
  }
}

export async function resolvePublicCalendarHostForHost(hostValue, { forceRefresh = false } = {}) {
  const host = normalizeDomain(hostValue)
  if (!host) {
    return { ok: false, status: 404, reason: 'invalid_host', message: 'Dominio inválido' }
  }

  const publicResolution = await resolveConnectedPublicDomainForHost(host, { forceRefresh })
  if (publicResolution.ok) {
    return {
      ...publicResolution,
      source: 'connected_public_domain',
      lockedToPublicCalendar: true
    }
  }

  const fallbackStatus = await getCalendarPublicBaseUrlStatus()
  if (fallbackStatus.enabled && matchesPublicDomain(host, fallbackStatus.domain)) {
    return {
      ok: true,
      host,
      domain: fallbackStatus.domain,
      domainConfig: null,
      source: fallbackStatus.source,
      lockedToPublicCalendar: fallbackStatus.lockedToPublicCalendar,
      fallback: true
    }
  }

  return {
    ok: false,
    status: publicResolution.status || 404,
    reason: publicResolution.reason,
    message: publicResolution.reason === 'domain_not_configured'
      ? 'Este dominio no está configurado para calendarios públicos.'
      : publicResolution.message || fallbackStatus.reason || 'Dominio público no disponible'
  }
}

export async function shouldBlockCrmOnPublicCalendarFallbackHost(hostValue) {
  const host = normalizeDomain(hostValue)
  if (!host) return false

  const fallbackStatus = await getCalendarPublicBaseUrlStatus()
  if (!fallbackStatus.enabled || !fallbackStatus.lockedToPublicCalendar) return false
  if (!matchesPublicDomain(host, fallbackStatus.domain)) return false

  const appConfig = await getSitesAppDomainConfig()
  return Boolean(
    appConfig.domain &&
    appConfig.renderDomainVerified &&
    !matchesPublicDomain(host, appConfig.domain)
  )
}

function mapSite(row) {
  if (!row) return null

  return {
    id: row.id,
    name: row.name,
    slug: row.slug,
    siteType: row.site_type || 'standard_form',
    status: row.status || 'draft',
    domain: row.public_domain || row.domain || '',
    title: row.title || '',
    description: row.description || '',
    theme: parseJson(row.theme_json, DEFAULT_THEME),
    antiTrackingEnabled: row.anti_tracking_enabled !== 0,
    metaCapiEnabled: Boolean(Number(row.meta_capi_enabled || 0)),
    metaEventName: normalizeSiteMetaEventName(row.meta_event_name, { allowNone: true }),
    renderDomainVerified: Boolean(Number(row.render_domain_verified || 0)),
    renderDomainCheckedAt: row.render_domain_checked_at || null,
    renderDomainError: row.render_domain_error || null,
    publishedAt: row.published_at || null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
    summary: false,
    submissionsCount: Number(row.submissions_count || 0),
    trackingStats: {
      views: Number(row.tracking_views || 0),
      visitors: Number(row.tracking_visitors || 0),
      sessions: Number(row.tracking_sessions || 0),
      conversions: Number(row.tracking_conversions || 0),
      convertingVisitors: Number(row.tracking_converting_visitors || 0),
      conversionRate: Number(row.tracking_visitors || 0) > 0
        ? Number(((Math.min(
            Number(row.tracking_visitors || 0),
            Number(row.tracking_converting_visitors || 0)
          ) / Number(row.tracking_visitors || 0)) * 100).toFixed(1))
        : 0
    }
  }
}

function buildSiteSummaryTheme(theme = {}) {
  const summary = {}
  const copyKeys = [
    'accentColor',
    'backgroundColor',
    'textColor',
    'template',
    'pageMode',
    'pages',
    'libraryFolderId',
    'librarySource',
    'importedHtml',
    'importedHtmlSource',
    'importedHtmlSourceActive',
    'importedHtmlSourceSiteId',
    'importedHtmlSourceSiteName',
    'importedHtmlSourceFormId',
    'importedHtmlSourcePagePath',
    'importedHtmlSourceTitle',
    'calendarSystemForm',
    'paymentGate'
  ]

  for (const key of copyKeys) {
    if (theme[key] !== undefined && theme[key] !== null) summary[key] = theme[key]
  }

  return summary
}

function mapSiteSummary(row) {
  const site = mapSite(row)
  if (!site) return null
  site.theme = buildSiteSummaryTheme(site.theme)
  site.summary = true
  return site
}

async function hydrateImportedHtmlSourceFormActivity(sites = []) {
  const candidates = (Array.isArray(sites) ? sites : []).filter(site => (
    normalizeBoolean(site?.theme?.importedHtmlSource) === 1 &&
    cleanString(site.theme.importedHtmlSourceSiteId)
  ))
  if (!candidates.length) return sites

  const sourceSiteIds = [...new Set(
    candidates.map(site => cleanString(site.theme.importedHtmlSourceSiteId)).filter(Boolean)
  )]
  const placeholders = sourceSiteIds.map(() => '?').join(', ')
  const rows = await db.all(`
    SELECT
      imported.site_id,
      imported.form_mappings_json,
      source.name AS source_name,
      source.title AS source_title
    FROM public_site_imports imported
    INNER JOIN public_sites source ON source.id = imported.site_id
    WHERE imported.site_id IN (${placeholders})
  `, sourceSiteIds)
  const sourcesById = new Map(rows.map(row => [cleanString(row.site_id), row]))

  return sites.map(site => {
    if (!candidates.includes(site)) return site
    const sourceSiteId = cleanString(site.theme.importedHtmlSourceSiteId)
    const source = sourcesById.get(sourceSiteId)
    const activeMapping = parseJson(source?.form_mappings_json, []).find(mapping => (
      mapping?.present !== false &&
      getImportedFormMappingSourceSiteId(mapping) === cleanString(site.id)
    ))
    const sourceSiteName = cleanString(source?.source_name || source?.source_title)

    return {
      ...site,
      theme: {
        ...site.theme,
        importedHtmlSourceActive: Boolean(activeMapping),
        ...(sourceSiteName ? { importedHtmlSourceSiteName: sourceSiteName } : {}),
        ...(cleanString(activeMapping?.pagePath || activeMapping?.page_path)
          ? { importedHtmlSourcePagePath: cleanString(activeMapping?.pagePath || activeMapping?.page_path) }
          : {})
      }
    }
  })
}

function buildPublicDefaultRoute(site, pageIdValue = '') {
  if (!site) return null

  const slug = cleanString(site.slug)
  const pageId = cleanString(pageIdValue)
  const page = pageId ? normalizeSitePages(site).find(item => item.id === pageId) || null : null
  const pagePath = page ? buildPublicPageRoutePath(site, page.id) : ''
  return {
    siteId: site.id,
    name: site.name || site.title || 'Ruta predeterminada',
    slug,
    siteType: site.siteType || 'standard_form',
    status: site.status || 'draft',
    ...(page ? { pageId: page.id, pageTitle: page.title || 'Página', pagePath: pagePath || '/' } : {}),
    path: page ? '/' : (slug ? `/${slug}` : '/')
  }
}

function normalizeSiteFolderSection(value = 'forms') {
  const section = cleanString(value).toLowerCase()
  return SITE_LIBRARY_FOLDER_SECTIONS.has(section) ? section : 'forms'
}

function mapSiteFolder(row) {
  if (!row) return null

  return {
    id: row.id,
    name: row.name || '',
    section: normalizeSiteFolderSection(row.section),
    sortOrder: Number(row.sort_order || 0),
    archived: Boolean(Number(row.archived || 0)),
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }
}

function withSiteLibraryMetadata(theme = {}, { folderId = '', source = '' } = {}) {
  const nextTheme = { ...(theme || {}) }
  const cleanFolderId = cleanString(folderId)
  const cleanSource = cleanString(source)
  if (cleanFolderId) nextTheme.libraryFolderId = cleanFolderId
  if (cleanSource) nextTheme.librarySource = cleanSource
  return nextTheme
}

function mapBlock(row) {
  if (!row) return null

  return {
    id: row.id,
    siteId: row.site_id,
    blockType: row.block_type,
    label: row.label || '',
    content: row.content || '',
    placeholder: row.placeholder || '',
    required: Boolean(Number(row.required || 0)),
    options: parseJson(row.options_json, []),
    settings: parseJson(row.settings_json, {}),
    sortOrder: Number(row.sort_order || 0),
    createdAt: row.created_at,
    updatedAt: row.updated_at
  }
}

function isNativeFormSite(site) {
  return FORM_SITE_TYPES.has(cleanString(site?.siteType || site?.site_type))
}

function getSystemFieldKeyForBlock(block) {
  const blockType = cleanString(block?.blockType || block?.block_type)
  if (!FIELD_BLOCK_TYPES.has(blockType)) return ''
  return getNativeSystemFieldKey({
    settings: isPlainObject(block?.settings) ? block.settings : {}
  })
}

function makeDuplicateSystemFieldError(fieldKey) {
  const error = new Error(`${getNativeSystemFieldLabel(fieldKey)} ya existe en este formulario`)
  error.status = 409
  error.code = 'duplicate_system_form_field'
  return error
}

function assertUniqueSystemFieldBlocks(blocks = []) {
  const seen = new Map()
  for (const block of blocks) {
    const fieldKey = getSystemFieldKeyForBlock(block)
    if (!fieldKey) continue
    if (seen.has(fieldKey)) {
      throw makeDuplicateSystemFieldError(fieldKey)
    }
    seen.set(fieldKey, block.id || '')
  }
}

function getEmbeddedSystemFieldBlockArrays(settings = {}) {
  return [
    settings.embeddedBlocks,
    settings.embedded_blocks,
    settings.videoFormGateEmbeddedBlocks,
    settings.video_form_gate_embedded_blocks
  ].filter(Array.isArray)
}

function assertUniqueSystemFieldsInBlockSettings(settings = {}) {
  for (const blockArray of getEmbeddedSystemFieldBlockArrays(settings)) {
    assertUniqueSystemFieldBlocks(
      blockArray.map((block, index) => ({
        id: cleanString(block?.id) || `__embedded_system_field_${index}__`,
        blockType: block?.blockType || block?.block_type,
        settings: isPlainObject(block?.settings) ? block.settings : {}
      }))
    )
  }
}

async function assertUniqueSystemFieldForInput(siteId, site, input, blockType, blockId = '') {
  const settings = isPlainObject(input?.settings) ? input.settings : {}
  assertUniqueSystemFieldsInBlockSettings(settings)
  if (!isNativeFormSite(site)) return
  const fieldKey = getSystemFieldKeyForBlock({ blockType, settings })
  if (!fieldKey) return

  const existingBlocks = await listSiteBlocks(siteId)
  const finalBlocks = [
    ...existingBlocks.filter(block => cleanString(block.id) !== cleanString(blockId)),
    { id: cleanString(blockId) || '__new_system_field__', blockType, settings }
  ]
  assertUniqueSystemFieldBlocks(finalBlocks)
}

async function assertUniqueSystemFieldsForRestore(siteId, site, inputBlocks = []) {
  for (const input of inputBlocks) {
    assertUniqueSystemFieldsInBlockSettings(isPlainObject(input.settings) ? input.settings : {})
  }

  if (!isNativeFormSite(site)) return
  const finalBlocksById = new Map((await listSiteBlocks(siteId)).map(block => [block.id, block]))

  inputBlocks.forEach((input, index) => {
    const id = cleanString(input.id) || `__new_system_field_${index}__`
    const blockType = validateBlockType(input.blockType || input.block_type)
    const settings = isPlainObject(input.settings) ? input.settings : {}
    finalBlocksById.set(id, {
      id,
      blockType,
      settings
    })
  })

  assertUniqueSystemFieldBlocks([...finalBlocksById.values()])
}

function mapSubmission(row) {
  if (!row) return null

  return {
    id: row.id,
    siteId: row.site_id,
    formSiteId: row.form_site_id || null,
    contactId: row.contact_id || null,
    domain: row.domain || '',
    responses: parseJson(row.response_json, {}),
    rawFields: parseJson(row.raw_fields_json, {}),
    mappedFields: parseJson(row.mapped_fields_json, {}),
    derivedFields: parseJson(row.derived_fields_json, {}),
    meta: parseJson(row.meta_json, {}),
    status: row.status || 'received',
    createdAt: row.created_at,
    contactName: row.contact_name || '',
    contactEmail: row.contact_email || '',
    contactPhone: row.contact_phone || ''
  }
}

function validateSiteType(value) {
  const siteType = cleanString(value) || 'standard_form'
  if (!SITE_TYPES.has(siteType)) {
    throw new Error('Tipo de site inválido')
  }
  return siteType
}

function validateSiteStatus(value) {
  const status = cleanString(value) || 'draft'
  if (!SITE_STATUSES.has(status)) {
    throw new Error('Estado de site inválido')
  }
  return status
}

function validateBlockType(value) {
  const blockType = cleanString(value)
  if (!BLOCK_TYPES.has(blockType)) {
    throw new Error('Tipo de bloque inválido')
  }
  return blockType
}

function normalizeOptionAction(value) {
  const rawAction = cleanString(value || 'continue').toLowerCase()
  const action = rawAction
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')

  const aliases = {
    normal: 'continue',
    continuar: 'continue',
    continuar_normalmente: 'continue',
    lead_frio: 'cold_lead',
    frio: 'cold_lead',
    marcar_lead_frio: 'cold_lead',
    lead_tibio: 'warm_lead',
    tibio: 'warm_lead',
    marcar_lead_tibio: 'warm_lead',
    lead_caliente: 'hot_lead',
    caliente: 'hot_lead',
    marcar_lead_caliente: 'hot_lead',
    descalificar: 'disqualify',
    descalificar_contacto: 'disqualify',
    descalificar_inmediatamente: 'disqualify',
    descalificar_al_finalizar: 'disqualify_after_submit',
    descalificar_al_finalizar_formulario: 'disqualify_after_submit',
    no_calificado: 'disqualify',
    mostrar_mensaje: 'show_message',
    mostrar_mensaje_especifico: 'show_message',
    terminar: 'end_form',
    terminar_formulario: 'end_form',
    finalizar: 'end_form',
    saltar: 'jump',
    saltar_pregunta: 'jump',
    saltar_a_pregunta: 'jump',
    dirigir: 'redirect',
    dirigir_a_sitio: 'redirect',
    redirigir: 'redirect',
    redirigir_a_sitio: 'redirect',
    sitio: 'redirect',
    pagina: 'site_page',
    página: 'site_page',
    pagina_sitio: 'site_page',
    pagina_del_sitio: 'site_page',
    dirigir_a_pagina: 'site_page',
    dirigir_a_pagina_del_sitio: 'site_page',
    redirigir_a_pagina: 'site_page',
    redirigir_a_pagina_del_sitio: 'site_page',
    etiqueta: 'tag',
    asignar_etiqueta: 'tag',
    categoria: 'category',
    categoría: 'category'
  }

  const resolvedAction = aliases[action] || action
  return OPTION_ACTIONS.has(resolvedAction) ? resolvedAction : 'continue'
}

function normalizeSubmitBeforeAction(value) {
  if (value === undefined || value === null || value === '') return true
  return Boolean(normalizeBoolean(value))
}

