        if (!video || attached.has(video)) return;
        const actions = parseActions(video);
        if (!actions.length && !hasVideoGateSource(video)) return;
        const state = {
          video,
          actions,
          triggered: new Set(),
          openedPopups: new Set(),
          blockedForms: new Set(),
          completedForms: new Set(),
          playbackActive: false,
          buffering: false,
          seeking: false,
          playbackSeconds: 0,
          persistedUniqueWatchedSeconds: 0,
          watchedRanges: [],
          persistence: persistenceConfigForVideo(video),
          persistedProgressLoaded: false,
          resumeRatioApplied: false,
          lastPersistWallTime: null,
          lastMeasurementMediaTime: null,
          lastMeasurementWallTime: null,
          lastProgressPublishWallTime: null,
          lastProgressStatusKey: ''
        };
        hydratePersistedProgress(state);
        syncSeekPolicyAttributes(state);
        let frameId = 0;
        const stopFrameSync = () => {
          if (!frameId) return;
          window.cancelAnimationFrame(frameId);
          frameId = 0;
        };
        const startFrameSync = () => {
          if (frameId || video.paused || video.ended || state.buffering || state.seeking || isPreviewPlayback(video) || !hasRealPlaybackStarted(video)) return;
          frameId = window.requestAnimationFrame(() => {
            frameId = 0;
            sync();
          });
        };
