function normalizeVideoFormGateThemeMode(settings = {}) {
  const mode = cleanString(settings.videoFormGateThemeMode || settings.video_form_gate_theme_mode)
  return mode === 'light' ? 'light' : DEFAULT_VIDEO_FORM_GATE_THEME_MODE
}

function getVideoFormGateThemePreset(settings = {}) {
  return { ...VIDEO_FORM_GATE_THEME_PRESETS[normalizeVideoFormGateThemeMode(settings)] }
}
const DEFAULT_VIDEO_PLAYER_COLOR = 'rgba(0, 0, 0, 0.40)'
const DEFAULT_VIDEO_PLAY_COLOR = 'rgba(255, 255, 255, 0.87)'
const LEGACY_VIDEO_PLAYER_COLOR = '#000000'
const LEGACY_VIDEO_PLAY_COLOR = '#ffffff'
const VIDEO_PLAYER_COLOR_DEFAULTS_VERSION = 2
const VIDEO_CONTROLS_IDLE_MS = 2600
const VIDEO_CONTROLS_LEAVE_IDLE_MS = 650

function normalizeVideoControlsMode(settings = {}) {
  const requestedMode = cleanString(settings.videoControlsMode)
  // Los videos importados anteriores al contrato declarativo guardaban
  // `overlay`; hoy ese mismo reproductor personalizado se llama `clean`.
  if (requestedMode === 'overlay') return 'clean'
  if (VIDEO_CONTROLS_MODES.has(requestedMode)) return requestedMode
  return settings.videoControls === false ? 'none' : 'clean'
}

function normalizeVideoTimelineMode(settings = {}) {
  return cleanString(settings.videoTimelineMode) === 'live_frontier' ? 'live_frontier' : 'duration'
}
const VIDEO_SPEED_OPTIONS = ['0.75', '1', '1.25', '1.5', '2']
const VIDEO_PREVIEW_MAX_SPAN_SECONDS = 40
const VIDEO_PREVIEW_DEFAULT_SECONDS = 40
const VIDEO_PREVIEW_STEP_SECONDS = 0.25


function hasModernVideoPlayerColorDefaults(settings = {}) {
  const version = Number(settings.videoPlayerColorDefaultsVersion ?? settings.video_player_color_defaults_version)
  return Number.isFinite(version) && version >= VIDEO_PLAYER_COLOR_DEFAULTS_VERSION
}

function isSameCssColorValue(value, target) {
  return normalizeCssColor(value, '').toLowerCase() === normalizeCssColor(target, '').toLowerCase()
}

function getVideoPlayerButtonColor(settings = {}) {
  const color = normalizeCssPaint(settings.videoPlayerColor, DEFAULT_VIDEO_PLAYER_COLOR) || DEFAULT_VIDEO_PLAYER_COLOR
  if (!hasModernVideoPlayerColorDefaults(settings) && isSameCssColorValue(color, LEGACY_VIDEO_PLAYER_COLOR)) {
    return DEFAULT_VIDEO_PLAYER_COLOR
  }
  return color
}

function getVideoPlayIconColor(settings = {}) {
  const color = normalizeCssPaint(settings.videoPlayColor, DEFAULT_VIDEO_PLAY_COLOR) || DEFAULT_VIDEO_PLAY_COLOR
  if (!hasModernVideoPlayerColorDefaults(settings) && isSameCssColorValue(color, LEGACY_VIDEO_PLAY_COLOR)) {
    return DEFAULT_VIDEO_PLAY_COLOR
  }
  return color
}

function normalizeVideoFormGateVideoBackground(settings = {}) {
  const fallback = normalizeVideoFormGateThemeMode(settings) === 'light'
    ? LIGHT_VIDEO_FORM_GATE_VIDEO_BACKGROUND
    : DEFAULT_VIDEO_FORM_GATE_VIDEO_BACKGROUND
  return normalizeCssPaint(
    settings.videoFormGateVideoBackground || settings.video_form_gate_video_background,
    fallback
  ) || fallback
}

function normalizeVideoPlayIconStyle(value) {
  const style = cleanString(value)
  return VIDEO_PLAY_ICON_STYLES.has(style) ? style : DEFAULT_VIDEO_PLAY_ICON_STYLE
}

function getVideoPlayIconMarkup(style) {
  if (style === 'outline') return RSTK_ICONS.playOutline
  if (style === 'soft') return RSTK_ICONS.playSoft
  if (style === 'spark') return RSTK_ICONS.playSpark
  return RSTK_ICONS.play
}

function isLegacyDefaultVideoPlay(settings = {}) {
  const shape = cleanString(settings.videoPlayShape)
  const radius = Number(settings.videoPlayRadius)
  const size = Number(settings.videoPlaySize)
  const iconSize = Number(settings.videoPlayIconSize)
  return shape === 'round' &&
    radius === LEGACY_VIDEO_PLAY_RADIUS &&
    (!Number.isFinite(size) || size === LEGACY_VIDEO_PLAY_SIZE) &&
    (!Number.isFinite(iconSize) || iconSize === LEGACY_VIDEO_PLAY_ICON_SIZE)
}

function normalizeVideoPlayShape(settings = {}) {
  const shape = cleanString(settings.videoPlayShape)
  if (VIDEO_PLAY_SHAPES.has(shape)) {
    return isLegacyDefaultVideoPlay(settings) ? DEFAULT_VIDEO_PLAY_SHAPE : shape
  }
  const radius = Number(settings.videoPlayRadius)
  return Number.isFinite(radius) && radius < 120 ? 'rectangle' : DEFAULT_VIDEO_PLAY_SHAPE
}

function normalizeVideoPlaySize(settings = {}) {
  const size = Number(settings.videoPlaySize)
  if (!Number.isFinite(size)) return DEFAULT_VIDEO_PLAY_SIZE
  if (isLegacyDefaultVideoPlay(settings) || (size === 64 && !Object.prototype.hasOwnProperty.call(settings, 'videoPlayShape'))) {
    return DEFAULT_VIDEO_PLAY_SIZE
  }
  return Math.min(VIDEO_PLAY_SIZE_MAX, Math.max(VIDEO_PLAY_SIZE_MIN, size))
}

function normalizeVideoPlayIconSize(settings = {}) {
  const size = Number(settings.videoPlayIconSize)
  if (!Number.isFinite(size)) return DEFAULT_VIDEO_PLAY_ICON_SIZE
  if (isLegacyDefaultVideoPlay(settings) || (size === 22 && !Object.prototype.hasOwnProperty.call(settings, 'videoPlayShape'))) {
    return DEFAULT_VIDEO_PLAY_ICON_SIZE
  }
  return Math.min(VIDEO_PLAY_ICON_SIZE_MAX, Math.max(VIDEO_PLAY_ICON_SIZE_MIN, size))
}

function normalizeVideoPlayRadius(settings = {}, shape = DEFAULT_VIDEO_PLAY_SHAPE) {
  if (isLegacyDefaultVideoPlay(settings)) return DEFAULT_VIDEO_PLAY_RADIUS
  const fallback = shape === 'rectangle' ? DEFAULT_VIDEO_PLAY_RADIUS : LEGACY_VIDEO_PLAY_RADIUS
  const radius = Number(settings.videoPlayRadius ?? fallback)
  const maxRadius = shape === 'rectangle' ? VIDEO_PLAY_RECTANGLE_RADIUS_MAX : LEGACY_VIDEO_PLAY_RADIUS
  return Number.isFinite(radius) ? Math.min(maxRadius, Math.max(0, radius)) : fallback
}

function normalizeVideoControlPanelRadius(settings = {}) {
  const radius = Number(settings.videoControlPanelRadius ?? DEFAULT_VIDEO_CONTROL_PANEL_RADIUS)
  return Number.isFinite(radius)
    ? Math.min(VIDEO_CONTROL_PANEL_RADIUS_MAX, Math.max(0, radius))
    : DEFAULT_VIDEO_CONTROL_PANEL_RADIUS
}

function normalizeVideoControlBarStyle(settings = {}) {
  const style = cleanString(settings.videoControlBarStyle)
  return VIDEO_CONTROL_BAR_STYLES.has(style) ? style : DEFAULT_VIDEO_CONTROL_BAR_STYLE
}

function normalizeVideoControlBarNumber(settings = {}, key = '', fallback = 0, min = 0, max = 100) {
  const value = Number(settings[key])
  return Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback
}

function getVideoControlBarBackground(settings = {}) {
  return normalizeCssPaint(settings.videoControlBarBackground, getVideoPlayerButtonColor(settings))
    || getVideoPlayerButtonColor(settings)
}

function getVideoControlBarColor(settings = {}) {
  return normalizeCssColor(settings.videoControlBarColor, getVideoPlayIconColor(settings))
}

function getVideoSoundNoticeText(settings = {}) {
  if (Object.prototype.hasOwnProperty.call(settings, 'videoSoundNoticeText')) {
    const text = cleanString(settings.videoSoundNoticeText)
    return text === LEGACY_VIDEO_SOUND_NOTICE_TEXT ? DEFAULT_VIDEO_SOUND_NOTICE_TEXT : text
  }
  return DEFAULT_VIDEO_SOUND_NOTICE_TEXT
}

function getVideoSoundNoticeHideAfter(settings = {}) {
  const value = Number(settings.videoSoundNoticeHideAfter)
  if (!Number.isFinite(value)) return DEFAULT_VIDEO_SOUND_NOTICE_HIDE_AFTER
  if (value <= 0) return 0
  return Math.min(12, Math.max(3, value))
}

function getVideoOrientationFromDimensions(width, height) {
  const numericWidth = Number(width)
  const numericHeight = Number(height)
  if (!Number.isFinite(numericWidth) || !Number.isFinite(numericHeight) || numericWidth <= 0 || numericHeight <= 0) return ''
  return numericHeight > numericWidth ? 'portrait' : 'landscape'
}

function getVideoOrientationFromAsset(asset = null) {
  if (!asset) return ''
  const directOrientation = getVideoOrientationFromDimensions(asset.width, asset.height)
  if (directOrientation) return directOrientation

  const streamVideo = asset.metadata?.stream?.video
  if (streamVideo && typeof streamVideo === 'object') {
    return getVideoOrientationFromDimensions(streamVideo.width, streamVideo.height)
  }

  return ''
}

function getVideoPortraitWidthMode(settings = {}) {
  const value = cleanString(settings.videoPortraitWidthMode)
  return value === 'fill' || value === 'framed' ? value : 'auto'
}

function getVideoPortraitWidthModeClass(mode) {
  return mode === 'fill' ? 'rstk-video-fill-width' : mode === 'auto' ? 'rstk-video-wauto' : ''
}

// El mapa canónico vive en el contrato compartido (content-blocks #1); aquí
// solo se serializa con el mismo escape por-valor del emisor histórico.
function getVideoFrameStyleVars(settings = {}, detectedOrientation = '') {
  return Object.entries(buildVideoFrameStyleVars(settings, detectedOrientation))
    .map(([name, value]) => `${name}:${escapeHtml(String(value))}`)
}

function renderVideoFrameStyle(settings = {}, detectedOrientation = '') {
  return getVideoFrameStyleVars(settings, detectedOrientation).join(';')
}

function roundVideoPreviewSecond(value) {
  return Math.round(value / VIDEO_PREVIEW_STEP_SECONDS) * VIDEO_PREVIEW_STEP_SECONDS
}

function normalizeVideoPreviewRange(settings = {}, durationSeconds) {
  const rawMax = Number(durationSeconds)
  const maxSeconds = Number.isFinite(rawMax) && rawMax > 0
    ? Math.max(VIDEO_PREVIEW_STEP_SECONDS, roundVideoPreviewSecond(rawMax))
    : null
  const timelineLimit = maxSeconds ?? Number.MAX_SAFE_INTEGER
  const minSpan = Math.min(1, Math.max(VIDEO_PREVIEW_STEP_SECONDS, maxSeconds ?? VIDEO_PREVIEW_MAX_SPAN_SECONDS))
  const maxSpan = Math.min(VIDEO_PREVIEW_MAX_SPAN_SECONDS, timelineLimit)
  const fallbackEnd = Math.min(VIDEO_PREVIEW_DEFAULT_SECONDS, timelineLimit)
  const rawStart = Number(settings.videoPreviewStart)
  const rawEnd = Number(settings.videoPreviewEnd)
  const start = Math.min(
    Math.max(0, roundVideoPreviewSecond(Number.isFinite(rawStart) ? rawStart : 0)),
    Math.max(0, timelineLimit - minSpan)
  )
  const end = Math.min(
    Math.max(start + minSpan, roundVideoPreviewSecond(Number.isFinite(rawEnd) ? rawEnd : fallbackEnd)),
    timelineLimit,
    start + maxSpan
  )

  return {
    start: Number(start.toFixed(2)),
    end: Number(end.toFixed(2))
  }
}

function renderVideoSpeedOptions(selectedSpeed) {
  const selected = cleanString(selectedSpeed || '1')
  return VIDEO_SPEED_OPTIONS
    .map(value => `<option value="${escapeHtml(value)}" ${value === selected ? 'selected' : ''}>${escapeHtml(value)}x</option>`)
    .join('')
}

function renderVideoSpeedMenuOptions(selectedSpeed, tabIndexAttr = '') {
  const selected = cleanString(selectedSpeed || '1')
  return VIDEO_SPEED_OPTIONS
    .map(value => {
      const isSelected = value === selected
      return `<button type="button" class="rstk-video-settings-option${isSelected ? ' rstk-video-settings-option-active' : ''}" data-rstk-video-speed-option="${escapeHtml(value)}" role="menuitemradio" aria-checked="${isSelected ? 'true' : 'false'}"${tabIndexAttr}><span>${escapeHtml(value)}x</span><span class="rstk-video-settings-check" aria-hidden="true">${RSTK_ICONS.check}</span></button>`
    })
    .join('')
}

function getItemTone(item) {
  const raw = String(item.title || item.text || '').trim()
  if (/^[+✓✔]/.test(raw)) return 'pro'
  if (/^[-–—✗✘x×]/i.test(raw)) return 'con'
  return 'neutral'
}

function stripToneMarker(value) {
  return String(value || '').replace(/^\s*[+\-–—✓✔✗✘x×]\s*/i, '').trim()
}

// El SITIO es master del evento Meta del calendario embebido: resuelve el evento
// "al agendar" configurado para el bloque detectado. Fallback legacy: página.
function resolveCalendarMetaOverride(context = {}, block = {}) {
  const site = context.site
  if (!site || !normalizeBoolean(site.metaCapiEnabled) || context.preview) return null
  const blockId = cleanString(block?.id)
  const eventMap = site?.theme?.metaCalendarEvents && typeof site.theme.metaCalendarEvents === 'object'
    ? site.theme.metaCalendarEvents
    : site?.theme?.meta_calendar_events && typeof site.theme.meta_calendar_events === 'object'
      ? site.theme.meta_calendar_events
      : {}
  const entry = blockId && eventMap && typeof eventMap[blockId] === 'object' ? eventMap[blockId] : null

  if (entry) {
    const disabled = entry.enabled === false ||
      cleanString(entry.enabled).toLowerCase() === 'false' ||
      cleanString(entry.eventName || entry.event_name) === SITE_META_NO_EVENT
    const eventName = disabled
      ? SITE_META_NO_EVENT
      : normalizeSiteMetaEventName(entry.eventName || entry.event_name, { allowNone: true, fallback: SITE_META_NO_EVENT })
    if (eventName === SITE_META_NO_EVENT) return null
    return {
      eventName,
      parameters: pruneSiteMetaEventParametersForEvent(entry.eventParameters || entry.event_parameters || entry.parameters, eventName)
    }
  }

  const pages = Array.isArray(site?.theme?.pages) ? site.theme.pages : []
  const page = pages.find(p => cleanString(p?.id) === cleanString(context.pageId))
  if (!page || !normalizeBoolean(page.metaCalendarEnabled ?? page.meta_calendar_enabled)) return null
  const eventName = normalizeSiteMetaEventName(page.metaCalendarEventName || page.meta_calendar_event_name, { allowNone: true, fallback: SITE_META_NO_EVENT })
  return eventName === SITE_META_NO_EVENT
    ? null
    : {
        eventName,
        parameters: pruneSiteMetaEventParametersForEvent(page.metaCalendarEventParameters || page.meta_calendar_event_parameters, eventName)
      }
}

// La URL del calendario embebido se construye en el contrato compartido
// (appendCalendarEmbedParams): mismos query params en el publicado y en el
// canvas del editor. Aquí solo se serializa el override Meta antes de llamarlo.
function buildCalendarEmbedMetaParams(calendarMetaOverride) {
  if (!calendarMetaOverride) return {}
  return {
    metaCalEvent: cleanString(calendarMetaOverride.eventName),
    metaCalData: hasSiteMetaEventParameters(calendarMetaOverride.parameters)
      ? jsonString(pruneSiteMetaEventParametersForEvent(calendarMetaOverride.parameters, calendarMetaOverride.eventName))
      : ''
  }
}

// Acción "Al agendar" configurada en el bloque de calendario. Las acciones de
// navegación usan el puente postMessage del iframe; cualquier otra cosa deja que
// el calendario use sus propias reglas.
function getCalendarEmbedCompletionRedirect(block = {}, context = {}) {
  const settings = block?.settings || {}
  const action = cleanString(settings.calendarCompletionAction || settings.calendar_completion_action)
  if (action === 'next_page') {
    const next = getNextPage(context.site, context.pageId)
    return next ? buildPageHref(next.id, { site: context.site, linkStyle: context.linkStyle }) : ''
  }
  if (action === 'specific_page') {
    const pages = normalizeSitePages(context.site)
    const targetPageId = cleanString(
      settings.calendarCompletionPageId ||
      settings.calendar_completion_page_id ||
      settings.completionPageId ||
      settings.completion_page_id
    )
    return targetPageId && pages.some(page => page.id === targetPageId)
      ? buildPageHref(targetPageId, { site: context.site, linkStyle: context.linkStyle })
      : ''
  }
  if (action === 'redirect') {
    return safeHref(settings.calendarCompletionRedirectUrl || settings.calendar_completion_redirect_url || '', '')
  }
  return ''
}

// El builder canónico vive en el contrato compartido (buildBlockStyleVars);
// aquí solo se resuelve el fondo de contraste del contexto y se serializa el
// mapa al atributo style del wrapper (mismo formato/escape histórico).
function renderBlockStyleVars(block, context = {}) {
  const vars = buildBlockStyleVars(block, {
    parentBlock: context.parentBlock,
    pageBg: cleanString(context.pageBg || context.formStyleContext?.pageBg)
  })
  const serialized = serializeCssVars(vars)
  return serialized ? ` style="${escapeHtml(serialized)}"` : ''
}

function renderBlockStyleClassName(block) {
  return buildBlockStyleClassName(block)
}

function renderBackgroundVideoElement(src, className) {
  const safeSrc = safePublicMediaUrl(src, 'video')
  if (!safeSrc) return ''

  if (getBunnyStreamVideoIdFromUrl(safeSrc)) {
    let embedUrl = safeSrc
    try {
      const parsed = new URL(safeSrc)
      parsed.searchParams.set('autoplay', 'true')
      parsed.searchParams.set('muted', 'true')
      parsed.searchParams.set('loop', 'true')
      parsed.searchParams.set('controls', 'false')
      embedUrl = parsed.toString()
    } catch {
      embedUrl = safeSrc
    }

    return `<iframe class="${escapeHtml(className)}" src="${escapeHtml(embedUrl)}" title="Video de fondo" loading="eager" allow="${escapeHtml(DEFAULT_EMBED_ALLOW)}" allowfullscreen sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-presentation" tabindex="-1" aria-hidden="true"></iframe>`
  }

  return looksLikeDirectVideoUrl(safeSrc)
    ? `<video class="${escapeHtml(className)}" src="${escapeHtml(safeSrc)}" autoplay muted loop playsinline aria-hidden="true"></video>`
    : ''
}

function renderBlockBackgroundVideo(block) {
  const settings = block?.settings || {}
  if (cleanString(settings.blockBackgroundMediaType) !== 'video') return ''
  return renderBackgroundVideoElement(settings.blockBackgroundImage, 'rstk-block-bg-video')
}

function wrapRenderedBlock(block, html, context = {}) {
  const style = renderBlockStyleVars(block, context)
  const className = renderBlockStyleClassName(block)
  const hasClassOnlyStyle = blockHasStyleWrapper(block, context)
  const backgroundVideo = renderBlockBackgroundVideo(block)
  const videoActionTargetAttr = renderVideoActionTargetAttribute(block, context)
  const countdownActionTargetAttr = renderCountdownActionTargetAttribute(block, context)
  const hiddenAttr = renderBlockHiddenAttributes(block)
  // Fix deliberado (payment #1): si el contenido no se publica (p. ej. cobro
  // deshabilitado devuelve ''), tampoco se emite el wrapper estilizado — dejaba un
  // hueco con padding en el sitio. Los bloques ocultos por el usuario (hidden attrs)
  // sí conservan su wrapper.
  if (!html && !hiddenAttr) return ''
  return style || hasClassOnlyStyle || backgroundVideo || videoActionTargetAttr || countdownActionTargetAttr || hiddenAttr
    ? `<div class="${escapeHtml(className)}" data-rstk-block-id="${escapeHtml(block.id || '')}"${videoActionTargetAttr}${countdownActionTargetAttr}${hiddenAttr}${style}>${backgroundVideo}${html}</div>`
    : html
}

function renderPublicBlock(block, context = {}) {
  const pages = Array.isArray(context.pages) ? context.pages : normalizeSitePages(context.site)
  const blockPageId = context.isInteractive || context.isStandardForm ? getBlockPageId(block, pages) : ''
  const html = FIELD_BLOCK_TYPES.has(block.blockType)
    ? renderFieldBlock(block, false, blockPageId, context)
    : renderContentBlock(block, context)
  const rendered = wrapRenderedBlock(block, html, context)

  if (context.isInteractive) {
    return `<div class="rstk-interactive-page-content" data-interactive-page-content="${escapeHtml(blockPageId)}">${rendered}</div>`
  }

  return rendered
}

function renderLandingSectionLane(lane, context = {}) {
  const columnContext = lane.section ? { ...context, parentBlock: lane.section } : context
  const columnsHtml = lane.columnBlocks.map((columnBlocks, index) => `
    <div class="rstk-section-column" data-section-column="${index}">
      ${columnBlocks.map(block => renderPublicBlock(block, columnContext)).join('\n')}
    </div>
  `).join('\n')

  if (!lane.section) {
    return `
      <section class="rstk-section-lane rstk-section-lane-legacy">
        <div class="rstk-section-inner">
          <div class="rstk-section-columns">
            ${columnsHtml}
          </div>
        </div>
      </section>
    `
  }

  const section = lane.section
  const settings = section.settings || {}
  const style = renderBlockStyleVars(section, context)
  const className = `${renderBlockStyleClassName(section)} rstk-section-lane`
  const videoActionTargetAttr = renderVideoActionTargetAttribute(section, context)
  const countdownActionTargetAttr = renderCountdownActionTargetAttribute(section, context)
  const hiddenAttr = renderBlockHiddenAttributes(section)
  const hasHeading = cleanString(section.content) || cleanString(settings.subtitle)
  const heading = hasHeading
    ? `
      <div class="rstk-section-heading">
        ${cleanString(section.content) ? `<h2>${escapeHtml(section.content)}</h2>` : ''}
        ${cleanString(settings.subtitle) ? `<p>${escapeHtml(settings.subtitle)}</p>` : ''}
      </div>
    `
    : ''

  return `
    <section class="${escapeHtml(className)}" data-rstk-block-id="${escapeHtml(section.id || '')}"${videoActionTargetAttr}${countdownActionTargetAttr}${hiddenAttr}${style}>
      ${renderBlockBackgroundVideo(section)}
      <div class="rstk-section-inner">
        ${heading}
        <div class="rstk-section-columns">
          ${columnsHtml}
        </div>
      </div>
    </section>
  `
}

function renderLandingBlocks(blocks = [], context = {}) {
  const sortedBlocks = [...blocks].sort((a, b) => a.sortOrder - b.sortOrder)
  const lanes = buildLandingSectionLanes(sortedBlocks)
  const laneBySectionId = new Map(lanes.filter(lane => lane.section).map(lane => [lane.section.id, lane]))
  const legacyLane = lanes.find(lane => !lane.section)
  const legacyBlockIds = new Set((legacyLane?.columnBlocks || []).flat().map(block => block.id))
  let legacyRendered = false

  const html = sortedBlocks.map(block => {
    if (isPanelBlock(block)) {
      return renderPublicBlock(block, context)
    }

    if (isSectionBlock(block)) {
      const lane = laneBySectionId.get(block.id)
      return lane ? renderLandingSectionLane(lane, context) : ''
    }

    if (legacyLane && !legacyRendered && legacyBlockIds.has(block.id)) {
      legacyRendered = true
      return renderLandingSectionLane(legacyLane, context)
    }

    return ''
  }).filter(Boolean)

  if (legacyLane && !legacyRendered) {
    html.push(renderLandingSectionLane(legacyLane, context))
  }

  return html.join('\n')
}

// `labelAttr` inyecta atributos en el <span class="rstk-button-label"> (p. ej.
// data-rstk-checkout-pay-label): el runtime del checkout reescribe SOLO el texto de
// ese span, así el icono/subtítulo sobreviven a la actualización del monto.
function renderSubmitButtonContent(label, subtitle = '', settings = {}, { labelAttr = '' } = {}) {
  const safeLabel = escapeHtml(cleanString(label) || 'Enviar')
  const safeSubtitle = escapeHtml(cleanString(subtitle))
  const labelSpan = `<span class="rstk-button-label"${labelAttr}>${safeLabel}</span>`
  const iconName = normalizeButtonIconName(settings.buttonIcon)
  if (!iconName) return `${labelSpan}${safeSubtitle ? `<span class="rstk-button-subtitle">${safeSubtitle}</span>` : ''}`
  const iconSide = normalizeButtonIconSide(settings.buttonIconSide)
  const icon = iconName ? `<span class="rstk-button-icon" aria-hidden="true">${RSTK_BUTTON_ICONS[iconName]}</span>` : ''
  return `<span class="rstk-button-content rstk-button-icon-${iconSide}">${iconSide === 'left' ? icon : ''}<span class="rstk-button-text-stack">${labelSpan}${safeSubtitle ? `<span class="rstk-button-subtitle">${safeSubtitle}</span>` : ''}</span>${iconSide === 'right' ? icon : ''}</span>`
}

function renderVideoPlayer(src, block, settings = {}, options = {}) {
  const timelineMode = normalizeVideoTimelineMode(settings)
  const requestedControlsMode = normalizeVideoControlsMode(settings)
  // Los controles nativos del navegador siempre revelan la duración física y
  // permiten apuntar al futuro. En modo live_frontier usamos la barra limpia,
  // que sí puede representar únicamente la franja alcanzada.
  const controlsMode = timelineMode === 'live_frontier' && requestedControlsMode === 'native'
    ? 'clean'
    : requestedControlsMode
  const showNativeControls = controlsMode === 'native'
  const showOverlay = controlsMode === 'clean'
  const showCentralPlay = settings.videoOverlayPlay !== false
  const showCustomControlBar = showOverlay && settings.videoControlBar !== false
  const showControlBarInitially = settings.videoControlBarInitiallyVisible !== false
  const showCustomPlayControl = settings.videoControlPlay !== false
  const showCustomProgress = settings.videoControlProgress !== false
  const showCustomVolume = settings.videoControlVolume !== false
  const showCustomSpeed = settings.videoControlSpeed !== false
  const showCustomSettings = settings.videoControlSettings !== false
  const showCustomTime = settings.videoControlTime !== false
  const soundHint = settings.videoSoundHint !== false
  const soundNoticeText = getVideoSoundNoticeText(settings)
  const soundNoticeHideAfter = getVideoSoundNoticeHideAfter(settings)
  const soundNoticePersistent = soundNoticeHideAfter === 0
  const previewEnabled = settings.videoPreviewEnabled !== false
  const muted = settings.videoMuted !== false
  const editorPreviewMode = Boolean(options.context?.importedNativePreviewMock)
  const editorPlaybackDisabled = editorPreviewMode && settings.videoDisableEditorPlayback === true
  const autoplay = Boolean(settings.videoAutoplay) && !editorPlaybackDisabled
  // Marcador informativo para el atributo data-rstk-video-render-preview (nadie lo
  // consume en runtime); ya NO altera el comportamiento del render.
  const renderPreviewMode = Boolean(options.context?.preview)
  // El editor HTML reproduce el mismo medio que el sitio para que loop, autoplay,
  // controles y diseño puedan verificarse ahí. La única pausa deliberada es la
  // opción explícita "No reproducir mientras se edita".
  // Paridad preview/publicado (pipeline #8): el candado inicial de la barra ya no
  // se fuerza en preview; depende solo del autoplay, igual que en el sitio publicado.
  const controlBarLockedAtStart = showCustomControlBar && !autoplay
  const initialControlsVisible = showCustomControlBar && !controlBarLockedAtStart && showControlBarInitially
  const previewLoopEnabled = previewEnabled && !autoplay && !editorPlaybackDisabled
  const preloadMode = editorPlaybackDisabled ? 'none' : (autoplay || previewLoopEnabled) ? 'metadata' : 'none'
  const previewRange = normalizeVideoPreviewRange(settings)
  // El teaser tipo Wistia siempre necesita arrancar silenciado para cumplir la
  // política de autoplay del navegador. El ajuste del usuario se recupera al
  // tocar el overlay; no debe impedir que el loop decorativo cargue.
  const startsMuted = muted || previewLoopEnabled || autoplay
  const showSoundNotice = showOverlay && soundHint && !autoplay
  const loop = Boolean(settings.videoLoop) || autoplay
  const rawSpeed = Number(settings.videoDefaultSpeed || 1)
  const speed = Number.isFinite(rawSpeed) ? Math.min(4, Math.max(0.25, rawSpeed)) : 1
  const fit = ['cover', 'contain', 'fill'].includes(cleanString(settings.videoFit)) ? cleanString(settings.videoFit) : 'cover'
  const orientation = normalizeVideoOrientation(settings, getVideoOrientationFromAsset(options.tracking?.asset))
  const orientationMode = ['portrait', 'landscape'].includes(cleanString(settings.videoOrientation))
    ? cleanString(settings.videoOrientation)
    : 'auto'
  const playerColor = getVideoPlayerButtonColor(settings)
  const playColor = getVideoPlayIconColor(settings)
  const controlPanelRadius = normalizeVideoControlPanelRadius(settings)
  const controlBarStyle = normalizeVideoControlBarStyle(settings)
  const controlBarBackground = getVideoControlBarBackground(settings)
  const controlBarColor = getVideoControlBarColor(settings)
  const controlBarWidthPercent = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarWidthPercent',
    DEFAULT_VIDEO_CONTROL_BAR_WIDTH_PERCENT,
    VIDEO_CONTROL_BAR_WIDTH_PERCENT_MIN,
    VIDEO_CONTROL_BAR_WIDTH_PERCENT_MAX
  )
  const controlBarInset = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarInset',
    DEFAULT_VIDEO_CONTROL_BAR_INSET,
    0,
    VIDEO_CONTROL_BAR_INSET_MAX
  )
  const controlBarHeight = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarHeight',
    DEFAULT_VIDEO_CONTROL_BAR_HEIGHT,
    VIDEO_CONTROL_BAR_HEIGHT_MIN,
    VIDEO_CONTROL_BAR_HEIGHT_MAX
  )
  const controlBarGap = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarGap',
    DEFAULT_VIDEO_CONTROL_BAR_GAP,
    0,
    VIDEO_CONTROL_BAR_GAP_MAX
  )
  const controlBarPaddingX = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarPaddingX',
    DEFAULT_VIDEO_CONTROL_BAR_PADDING_X,
    0,
    VIDEO_CONTROL_BAR_PADDING_X_MAX
  )
  const controlBarPaddingY = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarPaddingY',
    DEFAULT_VIDEO_CONTROL_BAR_PADDING_Y,
    0,
    VIDEO_CONTROL_BAR_PADDING_Y_MAX
  )
  const controlBarBorderWidth = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarBorderWidth',
    DEFAULT_VIDEO_CONTROL_BAR_BORDER_WIDTH,
    0,
    VIDEO_CONTROL_BAR_BORDER_WIDTH_MAX
  )
  const controlBarBlur = normalizeVideoControlBarNumber(
    settings,
    'videoControlBarBlur',
    DEFAULT_VIDEO_CONTROL_BAR_BLUR,
    0,
    VIDEO_CONTROL_BAR_BLUR_MAX
  )
  const controlBarShadow = settings.videoControlBarShadow === false
    ? 'none'
    : '0 14px 36px -24px color-mix(in srgb,currentColor 35%,transparent)'
  const playShape = normalizeVideoPlayShape(settings)
  const playSize = normalizeVideoPlaySize(settings)
  const playWidth = playShape === 'rectangle' ? Math.round(playSize * 1.45) : playSize
  const playRadius = normalizeVideoPlayRadius(settings, playShape)
  const playIconStyle = normalizeVideoPlayIconStyle(settings.videoPlayIconStyle)
  const playIconSize = normalizeVideoPlayIconSize(settings)
  const soundColor = normalizeCssPaint(settings.videoSoundColor, playColor) || playColor
  const soundNoticeCycle = `${Math.max(1, soundNoticeHideAfter + 1.6)}s`
  const gateMarkup = renderVideoFormGateMarkup(block, settings, options.context || {})
  const classes = [
    'rstk-video',
    'rstk-video-player',
    showNativeControls ? 'rstk-video-native-controls' : showOverlay ? 'rstk-video-custom-controls' : 'rstk-video-no-controls',
    showCustomControlBar ? 'rstk-video-has-control-bar' : '',
    showCustomControlBar ? `rstk-video-control-bar-${controlBarStyle}` : '',
    gateMarkup ? 'rstk-video-has-form-gate' : '',
    showCustomControlBar ? (initialControlsVisible ? 'rstk-video-controls-visible' : 'rstk-video-controls-hidden') : '',
    controlBarLockedAtStart ? 'rstk-video-controls-start-hidden' : '',
    showSoundNotice ? 'rstk-video-sound-hint' : '',
    startsMuted ? 'rstk-video-is-muted' : '',
    `rstk-video-${orientation}`,
    getVideoPortraitWidthModeClass(getVideoPortraitWidthMode(settings)),
    isVideoMobilePortraitCropEnabled(settings) ? 'rstk-video-mobile-portrait-crop' : '',
    `rstk-video-play-shape-${playShape}`,
    `rstk-video-play-${playIconStyle}`
  ].filter(Boolean).join(' ')
  const styleVars = [
    ...getVideoFrameStyleVars(settings, orientation),
    `--rstk-video-player-color:${escapeHtml(playerColor)}`,
    `--rstk-video-play-color:${escapeHtml(playColor)}`,
    `--rstk-video-control-radius:${escapeHtml(String(controlPanelRadius))}px`,
    `--rstk-video-control-bg:${escapeHtml(controlBarBackground)}`,
    `--rstk-video-control-color:${escapeHtml(controlBarColor)}`,
    `--rstk-video-control-width:${escapeHtml(String(controlBarWidthPercent))}%`,
    `--rstk-video-control-inset:${escapeHtml(String(controlBarInset))}px`,
    `--rstk-video-control-height:${escapeHtml(String(controlBarHeight))}px`,
    `--rstk-video-control-gap:${escapeHtml(String(controlBarGap))}px`,
    `--rstk-video-control-padding-x:${escapeHtml(String(controlBarPaddingX))}px`,
    `--rstk-video-control-padding-y:${escapeHtml(String(controlBarPaddingY))}px`,
    `--rstk-video-control-border-width:${escapeHtml(String(controlBarBorderWidth))}px`,
    `--rstk-video-control-blur:${escapeHtml(String(controlBarBlur))}px`,
    `--rstk-video-control-shadow:${escapeHtml(controlBarShadow)}`,
    `--rstk-video-play-width:${escapeHtml(String(playWidth))}px`,
    `--rstk-video-play-size:${escapeHtml(String(playSize))}px`,
    `--rstk-video-play-radius:${escapeHtml(String(playRadius))}px`,
    `--rstk-video-play-icon-size:${escapeHtml(String(playIconSize))}px`,
    `--rstk-video-sound-color:${escapeHtml(soundColor)}`,
    `--rstk-video-sound-cycle:${escapeHtml(soundNoticeCycle)}`
  ].join(';')

  const videoSrc = options.noTrack ? appendNoTrackParam(src) : src
  const fallbackVideoSrc = cleanString(options.fallbackSrc)
  const usableFallbackVideoSrc = fallbackVideoSrc && fallbackVideoSrc !== videoSrc
    ? fallbackVideoSrc
    : ''
  const posterVideoSrc = safePublicMediaUrl(options.posterSrc, 'image')
  const trackingEnabled = Boolean(options.tracking?.enabled)
  const trackingAttrs = buildVideoTrackingAttributes({
    enabled: trackingEnabled,
    block,
    asset: options.tracking?.asset,
    stream: options.tracking?.stream,
    provider: options.tracking?.provider || 'html5_video',
    playbackId: trackingEnabled ? (options.tracking?.playbackId || crypto.randomUUID()) : ''
  })
  const videoActionAttrs = renderVideoActionAttributes(block, settings, options.context || {})
  const controlBarTabIndex = controlBarLockedAtStart ? ' tabindex="-1"' : ''
  const progressTabIndex = controlBarLockedAtStart ? '-1' : '0'
  const videoSourceAttrs = [
    `data-rstk-video-src="${escapeHtml(videoSrc)}"`,
    usableFallbackVideoSrc ? `data-rstk-video-fallback-src="${escapeHtml(usableFallbackVideoSrc)}"` : '',
    posterVideoSrc ? `poster="${escapeHtml(posterVideoSrc)}"` : '',
    `data-rstk-video-render-preview="${renderPreviewMode ? 'true' : 'false'}"`,
    `data-rstk-video-editor-preview="${editorPreviewMode ? 'true' : 'false'}"`,
    `data-rstk-video-adaptive-quality="${settings.videoAdaptiveQuality !== false ? 'true' : 'false'}"`,
    `data-rstk-video-orientation-mode="${escapeHtml(orientationMode)}"`,
    `data-rstk-video-timeline-mode="${escapeHtml(timelineMode)}"`,
    `data-rstk-video-preview="${previewLoopEnabled ? 'true' : 'false'}"`,
    `data-rstk-video-preview-start="${escapeHtml(String(previewRange.start))}"`,
    `data-rstk-video-preview-end="${escapeHtml(String(previewRange.end))}"`,
    videoActionAttrs,
    trackingAttrs
  ].filter(Boolean).join(' ')

  return `
    <div class="${classes}" style="${styleVars}" data-rstk-video-timeline-mode="${escapeHtml(timelineMode)}" data-rstk-video-live-edge="${timelineMode === 'live_frontier' ? 'true' : 'false'}">
      <video ${videoSourceAttrs} title="${escapeHtml(block.label || 'Video')}" ${showNativeControls ? 'controls' : ''} ${startsMuted ? 'muted' : ''} ${autoplay ? 'autoplay' : ''} ${loop ? 'loop' : ''} playsinline preload="${preloadMode}" data-rstk-video-speed="${escapeHtml(String(speed))}" style="object-fit:${escapeHtml(fit)}"></video>
      ${showOverlay && showCentralPlay ? `
        <button type="button" class="rstk-video-overlay" data-rstk-video-overlay aria-label="Reproducir video">
          <span class="rstk-video-play-dot">${getVideoPlayIconMarkup(playIconStyle)}</span>
        </button>
      ` : ''}
      ${showSoundNotice ? `<span class="rstk-video-sound ${soundNoticePersistent ? 'rstk-video-sound-persistent' : 'rstk-video-sound-auto'}"><span class="rstk-video-sound-icon" aria-hidden="true">${RSTK_ICONS.volume}</span>${soundNoticeText ? `<span class="rstk-video-sound-text">${escapeHtml(soundNoticeText)}</span>` : ''}</span>` : ''}
      ${showCustomControlBar ? `
        <div class="rstk-video-control-bar" data-rstk-video-control-bar data-rstk-video-control-bar-start-visible="${showControlBarInitially ? 'true' : 'false'}"${controlBarLockedAtStart ? ' aria-hidden="true"' : ''}>
          ${showCustomPlayControl ? `<button type="button" class="rstk-video-control-button" data-rstk-video-toggle${controlBarTabIndex} aria-label="Reproducir video"><span class="rstk-video-control-play">${RSTK_ICONS.play}</span><span class="rstk-video-control-pause">${RSTK_ICONS.pause}</span></button>` : ''}
          ${showCustomProgress ? `<div class="rstk-video-progress" data-rstk-video-progress-track role="slider" tabindex="${progressTabIndex}" aria-label="Progreso del video" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span data-rstk-video-progress></span></div>` : ''}
          ${showCustomTime ? `<span class="rstk-video-timecode" data-rstk-video-timecode aria-label="Tiempo del video 0:00, queda 0:00"><span data-rstk-video-time-elapsed>0:00</span><span data-rstk-video-time-remaining>-0:00</span></span>` : ''}
          ${showCustomVolume ? `<button type="button" class="rstk-video-control-button" data-rstk-video-mute${controlBarTabIndex} aria-label="Silenciar video"><span class="rstk-video-control-volume">${RSTK_ICONS.volume}</span><span class="rstk-video-control-muted">${RSTK_ICONS.volumeMuted}</span></button>` : ''}
          ${showCustomSpeed && showCustomSettings ? `<div class="rstk-video-settings-control" data-rstk-video-settings-control><button type="button" class="rstk-video-control-button rstk-video-settings-toggle" data-rstk-video-settings-toggle aria-label="Abrir configuración del video" aria-haspopup="menu" aria-expanded="false"${controlBarTabIndex}>${RSTK_ICONS.settings}</button><div class="rstk-video-settings-menu" data-rstk-video-settings-menu role="menu" aria-label="Configuración del video" hidden><span class="rstk-video-settings-title">Velocidad</span><div class="rstk-video-settings-options">${renderVideoSpeedMenuOptions(String(speed), controlBarTabIndex)}</div></div></div>` : ''}
          ${showCustomSpeed && !showCustomSettings ? `<label class="rstk-video-speed-control rstk-video-speed-direct" aria-label="Velocidad de reproducción"><select data-rstk-video-speed-select${controlBarTabIndex}>${renderVideoSpeedOptions(String(speed))}</select></label>` : ''}
        </div>
      ` : ''}
      ${gateMarkup}
    </div>
  `
}

// Las variables proxy viven en el contrato compartido (buildEmbeddedFormProxyVars,
// embeds #14): el editor aplica el MISMO mapa inline sobre el gate del canvas.
function buildEmbeddedFormProxyStyle(theme = {}, formStyleContext = null) {
  if (!formStyleContext) return ''
  return serializeCssVars(buildEmbeddedFormProxyVars(theme, formStyleContext))
}

function buildEmbeddedFormSourceTheme(site = {}) {
  // site.theme aquí es la cadena CRUDA del embed (host + defaults de embed + theme
  // del formulario + override), SIN DEFAULT_THEME: de ella sale la explicitud del
  // fondo (fix embeds #2 — antes llegaba mergeada y el guard quedaba muerto).
  const sourceTheme = site?.theme || {}
  const theme = { ...DEFAULT_THEME, ...sourceTheme }
  const template = resolveTemplate({ ...site, theme })
  const isLandingType = site?.siteType === 'landing_page'
  const hasExplicitBackgroundColor = typeof sourceTheme.backgroundColor === 'string' && sourceTheme.backgroundColor.trim() !== ''
  const renderOverrides = resolveRenderOverrides(template, theme, isLandingType, { hasExplicitBackgroundColor })
  const v = { ...template.vars, ...(renderOverrides.vars || {}) }
  const accent = renderOverrides.accent || v.accent
  const accentStrong = renderOverrides.accent ? `color-mix(in srgb, ${renderOverrides.accent} 86%, #000)` : v.accentStrong
  const ring = renderOverrides.accent ? `color-mix(in srgb, ${renderOverrides.accent} 22%, transparent)` : v.ring
  const bodyFont = sanitizeCssFont(theme.siteBodyFontFamily) || template.font
  const siteTitleFont = sanitizeCssFont(theme.siteHeadingFontFamily)
  const siteSubtitleFont = sanitizeCssFont(theme.siteSubheadingFontFamily)
  const baseFont = bodyFont
  const display = `'Inter Tight', ${bodyFont}`
  const storedPageMaxWidth = Number(theme?.pageMaxWidth)
  const pageMaxWidth = isLandingType && storedPageMaxWidth === 1160
    ? 1440
    : themeNumber(theme, 'pageMaxWidth', isLandingType ? 1440 : (template.id === 'interactive' ? 600 : 520), 240, 3000)
  const pagePadding = themeNumber(theme, 'pagePadding', isLandingType ? 36 : 22, 0, 600)
  const pageRadius = themeNumber(theme, 'pageRadius', isLandingType ? 0 : 24, 0, 400)
  const pageBorderPaint = themePaint(theme, 'pageBorderColor')
  const pageBorder = pageBorderPaint ? paintFallbackColor(pageBorderPaint, 'transparent') : 'transparent'
  const pageBorderWidth = themeNumber(theme, 'pageBorderWidth', 0, 0, FORM_PAGE_BORDER_WIDTH_MAX)
  const backgroundMediaType = cleanString(theme.backgroundMediaType) === 'video' ? 'video' : 'image'
  const rawBackgroundPaint = normalizeCssPaint(theme.backgroundColor, '')
  const backgroundPaint = rawBackgroundPaint && (hasExplicitBackgroundColor || rawBackgroundPaint.toLowerCase() !== String(DEFAULT_THEME.backgroundColor).toLowerCase()) ? rawBackgroundPaint : ''
  const pageImage = backgroundMediaType === 'video' ? 'none' : (cssImageUrl(theme.backgroundImage) || v.pageImage)
  const pageVideo = backgroundMediaType === 'video' ? cssMediaUrl(theme.backgroundImage) : ''
  const pageOverlay = backgroundPaint ? paintLayer(backgroundPaint) : 'none'
  const pageBg = backgroundPaint && isCssColor(backgroundPaint) ? normalizeCssColor(backgroundPaint, v.pageBg) : v.pageBg
  const rawTextPaint = normalizeCssPaint(theme.textColor, '')
  const textPaint = rawTextPaint && (theme.textColorCustom || rawTextPaint.toLowerCase() !== String(DEFAULT_THEME.textColor).toLowerCase()) ? rawTextPaint : ''
  const ink = textPaint ? readableTextOnBackground(textPaint, pageBg, v.ink) : v.ink
  const muted = textPaint && isCssColor(textPaint) ? `color-mix(in srgb, ${ink} 60%, ${pageBg})` : v.muted
  const formVars = serializeCssVars(buildFormThemeStyleVars(theme, { baseFont, v, accent, ink, muted }))
  const bodyClass = [
    `rstk-tpl-${template.id}`,
    `rstk-${template.mode}`,
    `rstk-kind-${isLandingType ? 'landing' : 'form'}`,
    template.centered ? 'rstk-centered' : '',
    textPaint && isCssGradient(textPaint) ? 'rstkPageTextGradient' : '',
    site?.siteType === 'interactive_form' ? 'rstk-interactive' : '',
    `rstk-choice-${normalizeFormChoiceStyle(theme.formChoiceStyle)}`,
    `rstk-select-${normalizeFormSelectStyle(theme.formSelectStyle)}`,
    `rstk-input-${normalizeFormInputStyle(theme.formInputStyle)}`
  ].filter(Boolean).join(' ')

  const vars = [
    `--rstk-font:${baseFont}`,
    `--rstk-display:${display}`,
    siteTitleFont ? `--rstk-site-title-font:${siteTitleFont}` : '',
    siteSubtitleFont ? `--rstk-site-subtitle-font:${siteSubtitleFont}` : '',
    '--rstk-ease:cubic-bezier(.16,.84,.44,1)',
    `--rstk-page-bg:${pageBg}`,
    backgroundPaint ? `--rstk-block-bg:${backgroundPaint}` : '',
    `--rstk-page-image:${pageImage}`,
    `--rstk-page-overlay:${pageOverlay}`,
    `--rstk-page-video:${pageVideo}`,
    `--rstk-page-image-size:${pageImage === 'none' ? 'auto' : backgroundFitValue(theme.backgroundFit)}`,
    `--rstk-page-image-position:${backgroundPositionValue(theme.backgroundPosition)}`,
    `--rstk-page-image-repeat:${backgroundRepeatValue(theme.backgroundRepeat)}`,
    `--rstk-page-image-attachment:${backgroundAttachmentValue(theme.backgroundAttachment)}`,
    `--rstk-page-video-fit:${backgroundFitValue(theme.backgroundFit)}`,
    `--rstk-ink:${ink}`,
    `--rstk-muted:${muted}`,
    textPaint && isCssGradient(textPaint) ? `--rstk-page-text-paint:${textPaint}` : '',
    `--rstk-surface:${v.surface}`,
    `--rstk-surface2:${v.surface2}`,
    `--rstk-border:${v.border}`,
    `--rstk-accent:${accent}`,
    `--rstk-accent-strong:${accentStrong}`,
    `--rstk-on-accent:${v.onAccent}`,
    `--rstk-ring:${ring}`,
    `--rstk-input-bg:${v.inputBg}`,
    `--rstk-input-ink:${v.inputInk}`,
    `--rstk-input-border:${v.inputBorder}`,
    `--rstk-radius:${v.radius}`,
    `--rstk-radius-lg:${v.radiusLg}`,
    `--rstk-shadow:${v.shadow}`,
    `--rstk-heading-weight:${v.headingWeight}`,
    `--rstk-btn-radius:${v.btnRadius}`,
    `--rstk-btn-weight:${v.btnWeight}`,
    `--rstk-max:${pageMaxWidth}px`,
    `--rstk-frame-pad:${pagePadding}px`,
    `--rstk-page-border:${pageBorder}`,
    `--rstk-page-border-width:${pageBorderWidth}px`,
    `--rstk-page-radius:${pageRadius}px`,
    '--rstk-pad:clamp(18px,4vw,30px)',
    '--rstk-gap:clamp(16px,3vw,22px)',
    formVars,
    template.gradient ? `--rstk-gradient:${template.gradient}` : '',
    template.cyan ? `--rstk-cyan:${template.cyan}` : ''
  ].filter(Boolean).join(';')

  return {
    bodyClass,
    style: vars,
    pageVideo
  }
}

function splitCountdownSeconds(totalSeconds) {
  const safe = Math.max(0, Math.floor(Number.isFinite(Number(totalSeconds)) ? Number(totalSeconds) : 0))
  const days = Math.floor(safe / 86400)
  const hours = Math.floor((safe % 86400) / 3600)
  const minutes = Math.floor((safe % 3600) / 60)
  const seconds = safe % 60
  return { days, hours, minutes, seconds }
}

function formatCountdownPart(value) {
  return String(Math.max(0, Math.floor(Number(value) || 0))).padStart(2, '0')
}

function getCountdownInitialParts(settings = {}) {
  if (normalizeCountdownMode(settings.countdownMode) === 'date') {
    // Paridad content #12: parser compartido con semántica UTC del editor —
    // el primer paint SSR ya no depende de la zona horaria del servidor.
    const targetTime = parseCountdownTargetDate(settings.countdownTargetDate)
    if (targetTime !== null) {
      return splitCountdownSeconds(Math.max(0, Math.floor((targetTime - Date.now()) / 1000)))
    }
  }

  return splitCountdownSeconds(countdownDurationSeconds(settings))
}

function renderCountdownBlock(block = {}) {
  const settings = block.settings || {}
  const config = getCountdownRuntimeConfig(block)
  const parts = getCountdownInitialParts(settings)
  const showLabels = countdownShowLabels(settings)
  const units = [
    { key: 'days', label: 'Días', value: parts.days },
    { key: 'hours', label: 'Horas', value: parts.hours },
    { key: 'minutes', label: 'Min', value: parts.minutes },
    { key: 'seconds', label: 'Seg', value: parts.seconds }
  ]
  const title = cleanString(block.content)
  const expiredText = cleanString(config.expiredText)

  return `
    <section class="rstk-countdown" data-rstk-countdown="${escapeHtml(JSON.stringify(config))}">
      ${title ? `<p class="rstk-countdown-title">${escapeHtml(title).replace(/\n/g, '<br>')}</p>` : ''}
      <div class="rstk-countdown-grid" aria-label="Cuenta regresiva">
        ${units.map(unit => `
          <span class="rstk-countdown-unit" data-rstk-countdown-unit="${escapeHtml(unit.key)}">
            <strong data-rstk-countdown-part="${escapeHtml(unit.key)}">${formatCountdownPart(unit.value)}</strong>
            ${showLabels ? `<span>${escapeHtml(unit.label)}</span>` : ''}
          </span>
        `).join('')}
      </div>
      ${expiredText ? `<p class="rstk-countdown-note" data-rstk-countdown-expired hidden>${escapeHtml(expiredText)}</p>` : ''}
    </section>
  `
}

function normalizePaymentBlockLayout(value) {
  const raw = cleanString(value).toLowerCase()
  return raw === 'banner' || raw === 'minimal' ? raw : 'card'
}

function getPaymentGateFromBlock(block = {}) {
  const settings = block?.settings && typeof block.settings === 'object' ? block.settings : {}
  return normalizePaymentGateConfig(settings.paymentGate || settings.payment_gate || {})
}

function isPaymentBlockEnabled(block = {}) {
  return block?.blockType === 'payment' && isPaymentGateEnabled(getPaymentGateFromBlock(block))
}

function getPaymentGatewayLabel(gateway = '') {
  const raw = cleanString(gateway).toLowerCase()
  if (raw === 'mercadopago') return 'Mercado Pago'
  if (raw === 'conekta') return 'Conekta'
  if (raw === 'clip') return 'CLIP'
  if (raw === 'rebill') return 'Rebill'
  return 'Stripe'
}

function formatPaymentAmount(amount, currency = 'MXN') {
  const numeric = Number(amount)
  const safeCurrency = /^[A-Z]{3}$/.test(cleanString(currency).toUpperCase()) ? cleanString(currency).toUpperCase() : 'MXN'
  if (!Number.isFinite(numeric) || numeric <= 0) return 'Monto pendiente'
  try {
    return new Intl.NumberFormat('es-MX', {
      style: 'currency',
      currency: safeCurrency
    }).format(numeric)
  } catch (error) {
    return `${numeric.toFixed(2)} ${safeCurrency}`
  }
}

function formatPaymentSubscriptionCadence(paymentGate = {}) {
  const source = paymentGate.subscription && typeof paymentGate.subscription === 'object' ? paymentGate.subscription : {}
  const count = Math.max(1, Math.trunc(Number(source.intervalCount || source.interval_count || 1) || 1))
  const interval = cleanString(source.intervalType || source.interval_type || 'monthly').toLowerCase()
  if (count === 1) {
    if (interval === 'daily') return 'día'
    if (interval === 'weekly') return 'semana'
    if (interval === 'yearly') return 'año'
    return 'mes'
  }
  if (interval === 'daily') return `${count} días`
  if (interval === 'weekly') return `${count} semanas`
  if (interval === 'yearly') return `${count} años`
  return `${count} meses`
}

// Resuelve, en el servidor, qué pasa tras un pago CONFIRMADO. Espeja el patrón de
// completion de formularios (getNextPage/buildPageHref) para que "siguiente página" y
// "página específica" ya vengan como URL lista; el runtime solo la ejecuta al confirmar paid.
function normalizePaymentPostActionKind(value) {
  const raw = cleanString(value).toLowerCase()
  return ['next_page', 'specific_page', 'redirect_url', 'success_message'].includes(raw) ? raw : 'success_message'
}

function resolvePaymentPostAction(settings = {}, paymentGate = {}, block = {}, context = {}) {
  const source = settings.postPayment && typeof settings.postPayment === 'object'
    ? settings.postPayment
    : settings.post_payment && typeof settings.post_payment === 'object'
      ? settings.post_payment
      : {}
  let action = normalizePaymentPostActionKind(source.action)
  const site = context.site
  const pages = Array.isArray(context.pages) ? context.pages : normalizeSitePages(site)
  const pageId = getBlockPageId(block, pages)
  let url = ''

  if (action === 'redirect_url') {
    url = safeUrl(source.url || source.redirectUrl)
  } else if (action === 'next_page') {
    const next = getNextPage(site, pageId)
    url = next ? buildPageHref(next.id, context) : ''
  } else if (action === 'specific_page') {
    const targetPageId = cleanString(source.pageId || source.targetPageId)
    if (targetPageId && pages.some(page => page.id === targetPageId)) {
      url = buildPageHref(targetPageId, context)
    }
  }

  if (action !== 'success_message' && !url) {
    action = 'success_message'
  }

  return {
    action,
    url,
    message: cleanString(source.message || paymentGate.paidMessage || PAYMENT_POST_SUCCESS_MESSAGE_DEFAULT, 300)
  }
}

